<script>
const MOODLE_SESSKEY=<?= json_encode(sesskey()) ?>;
const STG_LOCAL_KEY="stg_nk_0716_review_user_<?= (int)$USER->id ?>";
const HAS_FULL_REVIEW=true;
const IS_SITE_ADMIN=<?= is_siteadmin($USER) ? "true" : "false" ?>;
const LEADERBOARD_ENDPOINT=window.location.href.split("?")[0].split("#")[0];
const questions=[{"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Analitis", "question": "Budaya organisasi berfungsi sebagai perekat sosial (social glue) yang menyatukan seluruh komponen organisasi dengan menyediakan standar kepatutan bertindak. Dalam konteks pencegahan fragmentasi birokrasi, bagaimana fungsi perekat sosial tersebut bekerja saat terjadi mutasi massal pegawai dari berbagai daerah ke kantor pusat?", "options": ["Mengharuskan pegawai pendatang untuk melupakan asal-usul kebudayaan daerah asalnya dan hanya berbicara dengan dialek ibu kota negara.", "Menyediakan kesamaan bahasa nilai dan standar etika dinas yang meleburkan kecanggungan primordial menjadi komitmen kerja bersama.", "Memberikan hak istimewa kepada pegawai asli daerah setempat untuk menduduki seluruh posisi strategis eselon tanpa proses seleksi.", "Membatasi interaksi tatap muka antardivisi agar pegawai dari latar belakang suku yang berbeda tidak saling memicu perselisihan kerja.", "Mewajibkan pegawai pendatang membayar uang kompensasi sosial kepada paguyuban pegawai senior di lingkungan kantor pusat dinas."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Budaya organisasi berfungsi sebagai **perekat sosial** (**social glue**) yang menyatukan keberagaman latar belakang anggota melalui **kesamaan standar nilai, bahasa kerja, dan norma perilaku bersama**, sehingga mencegah konflik primordial antardaerah.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah analisis sosiologi keorganisasian yang paling tepat mengenai peranan perekat sosial budaya kerja. Secara ilmiah, aparatur yang dimutasi dari berbagai penjuru tanah air membawa kebiasaan lokal yang beragam, di mana budaya organisasi Kementerian Keuangan menyediakan 'rumah nilai bersama' yang memungkinkan mereka berinteraksi secara harmonis, profesional, dan saling menghargai tanpa memandang sekat suku atau kedaerahan. Rekam jejak tata kelola kementerian membuktikan bahwa perekat sosial nilai integritas dan sinergi sukses menyatukan puluhan ribu aparatur di seluruh wilayah nusantara ke dalam satu korps pelayanan yang solid. Oleh karenanya, penyediaan kesamaan bahasa nilai merupakan hakikat sejati perekat sosial.</p><p>Jawaban yang sesuai adalah <strong>B. Menyediakan kesamaan bahasa nilai dan standar etika dinas yang meleburkan kecanggungan primordial menjadi komitmen kerja bersama.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena budaya organisasi menghormati kebhinekaan nusantara dan tidak menuntut penghapusan identitas budaya daerah personal.</li><li><strong>C</strong>: Salah karena memberikan jabatan berbasis kedaerahan melanggar sistem meritokrasi aparatur sipil negara dan mencoreng keadilan dinas.</li><li><strong>D</strong>: Salah karena membatasi komunikasi justru memicu prasangka sosial yang kontraproduktif bagi kelancaran koordinasi kerja dinas.</li><li><strong>E</strong>: Salah karena memungut kompensasi sosial adalah pemerasan ilegal yang melanggar hukum pidana dan mencerminkan feodalisme korup.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Analitis", "question": "Robbins menjelaskan bahwa budaya organisasi berfungsi sebagai mekanisme pembuat makna dan kendali (sense-making and control mechanism) yang memandu sikap dan perilaku anggota. Implikasi utama dari fungsi kendali budaya ini terhadap pengawasan pegawai di era kerja fleksibel (flexible working space) adalah...", "options": ["Organisasi harus menugaskan aparat intelijen untuk mengikuti ke mana pun pegawai pergi saat menjalankan tugas kerja di luar kantor.", "Pegawai dibebaskan sepenuhnya dari target capaian kinerja bulanan karena pengawasan mandiri dipandang telah menggantikan sistem.", "Pimpinan kantor wajib menghubungi nomor telepon pribadi keluarga pegawai setiap tiga puluh menit guna memastikan keberadaannya.", "Nilai yang terinternalisasi menjadi kompas moral mandiri yang menjaga produktivitas dan etika pegawai meski tanpa pengawasan fisik.", "Pemasangan gelang pelacak satelit digital pada tubuh seluruh staf pelaksana yang bekerja dari rumah kediaman sepanjang jam dinas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sebagai **mekanisme kontrol internal** (**internal control mechanism**), budaya kerja yang kuat menanamkan kesadaran etika batiniah sehingga aparatur tetap **berdisiplin, berkinerja produktif, dan menjaga integritas** di mana pun bertugas, bahkan saat bekerja tanpa pengawasan fisik atasan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merangkum konsekuensi logis fungsi kontrol budaya dalam era modern secara paling tepat dan aplikatif. Secara teori manajemen modern, pengawasan fisik jarak dekat menjadi usang di era kerja fleksibel (FWS/WFH), di mana kendali perilaku bertumpu pada integritas mandiri (self-discipline) aparatur yang meyakini bahwa jam kerja adalah amanah publik yang wajib diisi dengan penyelesaian target nyata. Evaluasi kerja fleksibel di kementerian membuktikan bahwa pegawai dengan internalisasi budaya tinggi tetap mencatatkan output prima tanpa penurunan kualitas pelayanan sedikit pun. Maka dari itu, berfungsinya nilai sebagai kompas kendali mandiri menegaskan keunggulan teori Robbins.</p><p>Jawaban yang sesuai adalah <strong>D. Nilai yang terinternalisasi menjadi kompas moral mandiri yang menjaga produktivitas dan etika pegawai meski tanpa pengawasan fisik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membuntuti pegawai dengan intelijen adalah pemborosan sumber daya negara yang melanggar hak privasi personal aparatur.</li><li><strong>B</strong>: Salah karena kerja fleksibel tetap mengikat aparatur pada sasaran kinerja pegawai (SKP) kuantitatif yang terukur dan akuntabel.</li><li><strong>C</strong>: Salah karena meneror keluarga pegawai dengan telepon interogatif mencerminkan kepemimpinan paranoia yang merusak kenyamanan kerja.</li><li><strong>E</strong>: Salah karena pemasangan gelang pelacak tahanan kepada aparatur sipil negara melanggar hak asasi manusia dan mencoreng martabat korps.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Aplikasi", "question": "Hadirnya budaya organisasi membantu para pegawai membaca situasi kerja dan memahami apa yang diharapkan institusi dari dirinya. Seorang pegawai baru mendapati meja rekan kerjanya sangat rapi dan setiap selesai pelayanan berkas rahasia langsung dimasukkan ke lemari besi terkunci. Penerapan pemahaman situasi kerja yang tepat bagi pegawai baru tersebut adalah...", "options": ["Mengadopsi standar kepatuhan yang sama dengan selalu merapikan dokumen dan mengunci berkas rahasia dinas di lemari penyimpanan.", "Menertawakan kebiasaan rekan kerja tersebut dan membiarkan berkas wajib pajak miliknya berserakan di atas lantai lobi kantor dinas.", "Membuang berkas-berkas rahasia dinas ke tempat sampah umum di pinggir jalan agar meja kerjanya terlihat lebih bersih dan luas.", "Memotret isi lemari besi rekan kerjanya dan mengunggahnya ke status media sosial pribadi guna menarik perhatian warganet daring.", "Menjual lemari besi penyimpanan berkas kantor kepada pedagang besi tua loak dengan alasan kantor memerlukan ruang meja tambahan."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Budaya organisasi membantu anggota baru **membaca norma kerja implisit** (**social cues**) dan mengadopsi standar perilaku yang diharapkan institusi: **menjaga kerahasiaan jabatan, kerapian administrasi, dan kehati-hatian pengelolaan dokumen**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah tindakan yang paling adaptif, profesional, dan mencerminkan keberhasilan sosialisasi budaya organisasi. Secara psikologi keorganisasian, artefak fisik berupa kerapian meja dan penguncian lemari arsip mengirimkan sinyal budaya yang tegas bahwa institusi sangat menjunjung tinggi prinsip kerahasiaan data wajib pajak (tax secrecy) dan kehati-hatian dokumen negara, sehingga pegawai baru yang peka akan langsung menyelaraskan perilakunya dengan standar tersebut. Data audit pengamanan dokumen kementerian membuktikan bahwa kepatuhan clean desk policy efektif mencegah kebocoran informasi strategis fiskal kepada pihak tidak berhak. Oleh sebab itu, meniru standar pengamanan berkas merupakan respons adaptasi budaya terbaik.</p><p>Jawaban yang sesuai adalah <strong>A. Mengadopsi standar kepatuhan yang sama dengan selalu merapikan dokumen dan mengunci berkas rahasia dinas di lemari penyimpanan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena mencemooh rekan yang disiplin dan menelantarkan dokumen merupakan pelanggaran berat standar operasional prosedur dinas.</li><li><strong>C</strong>: Salah karena membuang berkas rahasia negara ke tempat sampah merupakan tindak pidana penghilangan dokumen otentik milik negara.</li><li><strong>D</strong>: Salah karena memotret dan memublikasikan sarana penyimpanan rahasia melanggar kode etik kerahasiaan jabatan dan keamanan informasi.</li><li><strong>E</strong>: Salah karena menjual barang milik negara secara ilegal merupakan tindak pidana penggelapan aset inventaris kementerian keuangan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Analitis", "question": "Budaya organisasi memfasilitasi lahirnya komitmen pada sesuatu yang lebih luas daripada kepentingan pribadi seseorang (commitment beyond self-interest). Di antara fenomena kerja berikut, manakah situasi yang BUKAN merupakan wujud komitmen bersama melampaui kepentingan diri di lingkungan kantor kementerian?", "options": ["Aparatur bersedia bekerja lembur hingga larut malam demi mengamankan tenggat waktu pelaporan APBN tanpa menuntut imbalan gelap.", "Petugas pos patroli perbatasan tetap teguh mengawasi perairan meski menghadapi cuaca buruk demi menjaga kedaulatan penerimaan devisa.", "Tim verifikasi anggaran menolak cuti tahunan pada akhir tahun demi menjamin kelancaran penyaluran dana bantuan sosial bencana alam.", "Pegawai mengembalikan sisa kelebihan biaya perjalanan dinas ke kas negara secara sukarela demi menjaga akuntabilitas keuangan publik.", "Pimpinan membagi-bagikan dana alokasi belanja proyek pengadaan kantor kepada pejabat struktural sebagai uang saku pelesir pribadi."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Komitmen bersama menuntut pengorbanan demi **kemaslahatan institusi dan negara**. Mengambil dana proyek kantor untuk pelesir pribadi (**korupsi anggaran**) merupakan puncak kejahatan egoistik yang bertentangan dengan budaya organisasi.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah skenario kejahatan korupsi yang bertolak belakang secara mutlak dengan hakikat komitmen melampaui kepentingan diri. Secara hukum keuangan negara, menyalahgunakan alokasi anggaran proyek publik menjadi uang saku liburan pribadi pejabat merupakan tindak pidana korupsi penyelewengan dana dinas yang merugikan keuangan negara dan menzalimi hak rakyat penerima manfaat pembangunan. Fakta persidangan tipikor membuktikan bahwa pejabat yang mengutamakan kerakusan pribadi di atas kepentingan institusi selalu dijatuhi vonis pidana penjara dan dicabut hak politiknya. Maka dari itu, membagi-bagikan dana dinas untuk pelesir jelas bukan wujud komitmen melainkan kejahatan birokrasi.</p><p>Jawaban yang sesuai adalah <strong>E. Pimpinan membagi-bagikan dana alokasi belanja proyek pengadaan kantor kepada pejabat struktural sebagai uang saku pelesir pribadi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan wujud nyata komitmen pengabdian tinggi di mana pegawai mendahulukan akuntabilitas anggaran negara di atas kenyamanan diri.</li><li><strong>B</strong>: Merupakan cerminan dedikasi patriotik aparatur penjaga batas maritim demi mengamankan devisa negara dari kejahatan penyelundupan.</li><li><strong>C</strong>: Merupakan bukti empati kemanusiaan yang luhur dalam mendahulukan nasib warga korban bencana alam dibanding hak libur pribadi.</li><li><strong>D</strong>: Merupakan pengamalan nilai kejujuran integritas di mana aparatur menolak mengambil hak negara demi kekayaan materiil pribadi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Evaluatif", "question": "Sebuah satuan kerja pelayanan perpajakan mengalami anomali di mana setiap pegawai bekerja dengan standar etika masing-masing tanpa adanya pedoman bersama, sehingga tingkat kepuasan publik merosot tajam dan marak terjadi perselisihan antarseksi. Penilaian evaluatif yang paling tepat terhadap kondisi satuan kerja tersebut adalah...", "options": ["Kondisi kerja yang sangat ideal karena kebebasan tanpa aturan membangkitkan kreativitas tanpa batas bagi para pegawai birokrasi.", "Situasi yang wajar karena instansi pemerintah tidak membutuhkan kesatuan norma selama laporan keuangan tetap diserahkan ke kementerian.", "Krisis budaya organisasi yang parah akibat hilangnya perekat sosial dan fungsi kendali perilaku sehingga organisasi terancam rapuh.", "Prestasi yang membanggakan karena tidak adanya standar bersama membuktikan keberhasilan asas kemerdekaan mutlak aparatur sipil negara.", "Kondisi yang menguntungkan karena masyarakat pemohon dapat menyuap pegawai loket mana pun yang dirasa memberikan harga paling murah."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Ketiadaan budaya bersama yang kuat (**weak culture**) menyebabkan organisasi kehilangan stabilitas sistem sosial (**social instability**), memicu **anarki kerja, friksi internal, dan kehancuran kepercayaan publik** (**loss of public trust**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C memberikan evaluasi kritis yang paling tepat, mendalam, dan selaras dengan doktrin perilaku organisasi Robbins. Secara sosiologi institusi, organisasi yang tidak memiliki sistem makna bersama akan terperosok ke dalam anomie—kondisi tanpa norma pengikat—di mana setiap individu mengejar kepentingan sempitnya sendiri, melayani masyarakat secara serampangan, dan menghancurkan wibawa hukum instansi pemerintah. Pengalaman kegagalan tata kelola di berbagai unit birokrasi membuktikan bahwa ketiadaan budaya integritas bersama selalu berujung pada maraknya gratifikasi liar dan runtuhnya pelayanan publik. Oleh sebab itu, kondisi tersebut merupakan krisis budaya organisasi akut yang mengancam eksistensi kantor.</p><p>Jawaban yang sesuai adalah <strong>C. Krisis budaya organisasi yang parah akibat hilangnya perekat sosial dan fungsi kendali perilaku sehingga organisasi terancam rapuh.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena kebebasan anarkis tanpa etika menghancurkan kepastian hukum pelayanan dan merugikan hak-hak masyarakat luas.</li><li><strong>B</strong>: Salah karena instansi publik mengemban mandat kepercayaan rakyat yang mustahil berjalan tanpa adanya kesatuan norma integritas.</li><li><strong>D</strong>: Salah karena kemerdekaan aparatur sipil negara dibatasi oleh sumpah jabatan dan kode etik dinas yang mengikat secara yuridis.</li><li><strong>E</strong>: Salah karena membenarkan suap murah mencerminkan mentalitas korup yang bertentangan dengan hukum pidana Republik Indonesia.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Aplikasi", "question": "Budaya organisasi menjalankan fungsi penentu batas (boundary-defining role) yang membedakan organisasi tersebut dari organisasi lainnya. Seorang staf kementerian keuangan sedang ditugaskan dalam tim terpadu bersama instansi lain yang terbiasa menerima uang transportasi tidak resmi dari pihak yang diperiksa. Sikap yang paling mencerminkan fungsi penentu batas nilai kementerian keuangan adalah...", "options": ["Menolak secara santun uang transportasi tersebut dan menegaskan bahwa aparatur kementerian keuangan dilarang menerima gratifikasi.", "Menerima uang transportasi tersebut asalkan jumlah uangnya tidak melebihi batas penghasilan tidak kena pajak bulanan aparatur.", "Menyuruh instansi lain mengambil bagian uang transportasinya dengan syarat dirinya diberikan cinderamata mewah pada akhir penugasan.", "Meminta pihak yang diperiksa menaikkan uang transportasi dua kali lipat sebagai kompensasi atas risiko teguran inspektorat jenderal.", "Menyimpan uang transportasi tersebut di rekening pribadi dan membagi-bagikannya kepada anak yatim piatu di sekitar pelabuhan dinas."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Fungsi **penentu batas** (**boundary-defining role**) menegaskan pembeda identitas integritas: aparatur Kementerian Keuangan memegang prinsip **nol toleransi terhadap gratifikasi** (**zero tolerance**), meskipun institusi mitra memiliki kebiasaan kompromistis yang berbeda.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah tindakan yang paling berani, konsisten, dan menunjukkan tegaknya fungsi penentu batas identitas moral institusi. Secara etika profesi dan hukum tipikor, aparatur Kementerian Keuangan diikat oleh kode etik integritas tinggi yang melarang penerimaan uang transpor dari auditee dalam bentuk apa pun, sehingga keberanian menolak secara santun menegaskan batas jati diri pembeda yang membedakan korps Kemenkeu dari tradisi permisif instansi lain. Bukti ketegasan aparatur fiskal di berbagai tim gabungan nasional membuktikan bahwa konsistensi menolak gratifikasi berhasil menularkan standar integritas baru kepada instansi mitra. Oleh sebab itu, menolak secara santun mencerminkan fungsi penentu batas nilai sejati.</p><p>Jawaban yang sesuai adalah <strong>A. Menolak secara santun uang transportasi tersebut dan menegaskan bahwa aparatur kementerian keuangan dilarang menerima gratifikasi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena batasan penghasilan tidak kena pajak adalah ketentuan perpajakan, bukan pembenar penerimaan gratifikasi suap ilegal.</li><li><strong>C</strong>: Salah karena mengalihkan gratifikasi menjadi cinderamata mewah tetap merupakan modus transaksi penyuapan yang melanggar hukum.</li><li><strong>D</strong>: Salah karena meminta kenaikan uang transport merupakan tindak pidana pemerasan dalam jabatan yang diancam hukuman pidana berat.</li><li><strong>E</strong>: Salah karena menyalurkan uang gratifikasi ke anak yatim tidak menghapuskan sifat melawan hukum dari tindak pidana korupsi suap.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan pemahaman bahwa budaya organisasi adalah modal sosial yang memandu pembacaan situasi dan interaksi kerja, seorang kepala kantor wilayah berniat merancang 'Buku Saku Adaptasi Budaya' bagi pegawai mutasi baru. Kerangka substansi yang paling komprehensif untuk memudahkan pegawai membaca situasi dan menyelaraskan diri secara cepat adalah...", "options": ["Daftar restoran mewah di sekitar kantor dan panduan tata cara meminta traktiran makan siang gratis kepada pimpinan satuan kerja.", "Rincian nomor rekening pribadi pimpinan kantor wilayah dan jadwal iuran wajib non-resmi untuk perayaan ulang tahun pejabat eselon.", "Peta nilai inti organisasi, panduan kode perilaku interaksi harian, standar pelayanan publik, dan mekanisme pelaporan pelanggaran.", "Koleksi foto rumah pribadi para pegawai senior disertai taksiran harga pasar aset tanah guna membandingkan status kekayaan aparatur.", "Petunjuk teknis cara memalsukan tanda tangan kehadiran apel pagi tanpa terdeteksi oleh kamera pengawas keamanan lobi gedung kantor."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Instrumen orientasi budaya yang komprehensif merangkum **peta nilai institusi** (**core values**), **panduan kode perilaku harian** (*code of conduct*), **standar mutu pelayanan**, serta **saluran perlindungan pelaporan integritas** (*whistleblowing system*).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C menyajikan kerangka materi orientasi budaya yang paling utuh, terstruktur, dan berorientasi penguatan karakter aparatur. Secara ilmu manajemen sumber daya manusia, adaptasi budaya kerja pegawai baru/mutasi membutuhkan kejelasan acuan mengenai apa yang dianggap luhur dan tercela (core values), bagaimana berkomunikasi dan bertindak secara etis dengan rekan kerja dan masyarakat (code of conduct), serta ke mana harus melapor jika menyaksikan penyimpangan tanpa rasa takut (WBS). Fakta program on-boarding di kementerian membuktikan bahwa buku panduan perilaku komprehensif mempercepat adaptasi kinerja aparatur hingga 50%. Oleh karena itu, perpaduan nilai, perilaku, dan kanal pelaporan merupakan formula sintesis terbaik.</p><p>Jawaban yang sesuai adalah <strong>C. Peta nilai inti organisasi, panduan kode perilaku interaksi harian, standar pelayanan publik, dan mekanisme pelaporan pelanggaran.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena panduan mencari traktiran makan siang mencerminkan mentalitas pengemis birokrasi yang merendahkan martabat aparatur.</li><li><strong>B</strong>: Salah karena memuat iuran non-resmi ulang tahun pejabat merupakan pemerasan terselubung dan praktik feodalisme korup dinas.</li><li><strong>D</strong>: Salah karena mengumbar kekayaan pribadi rekan kerja melanggar hak privasi dan memicu kecemburuan sosial yang merusak keharmonisan.</li><li><strong>E</strong>: Salah karena memuat cara memalsukan absensi merupakan instruksi kejahatan pemalsuan dokumen yang berakibat pemecatan dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Analitis", "question": "Budaya organisasi memiliki kekuatan yang besar dalam membentuk pola perilaku dan kebiasaan para pelakunya. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai keterkaitan antara budaya organisasi dengan perilaku aparatur?", "options": ["Budaya organisasi yang sehat mampu memengaruhi aparatur yang awalnya pasif menjadi lebih proaktif dalam memberikan pelayanan publik.", "Budaya organisasi yang menjunjung transparansi membuat aparatur merasa aman dan terlindungi saat melaporkan tindak penyimpangan.", "Budaya organisasi memberikan stabilitas sosial dengan cara mereduksi ketidakpastian standar etika yang harus dipatuhi di tempat kerja.", "Budaya organisasi merupakan kekuatan absolut yang menghapus seluruh hak asasi manusia pegawai dan mewajibkan kepatuhan pidana ilegal.", "Budaya organisasi yang berorientasi hasil memotivasi tim kerja untuk mencari jalan keluar kreatif dalam memecahkan kebuntuan layanan."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Budaya organisasi **beroperasi dalam koridor hukum, etika, dan penghormatan hak asasi manusia**, serta **tidak pernah membenarkan perintah yang melanggar hukum pidana** atau meniadakan hak asasi manusia pegawai.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merupakan simpulan yang salah, menyesatkan, dan bertentangan secara frontal dengan konsep hukum administrasi negara dan nilai demokrasi. Secara yuridis dan etika publik, budaya organisasi birokrasi bertumpu pada supremasi hukum dan penghormatan martabat kemanusiaan aparatur sipil negara, sehingga tidak ada satu pun doktrin budaya kerja yang boleh menghapuskan hak asasi pegawai atau memaksakan kepatuhan terhadap perintah atasan yang melanggar hukum pidana (illegal order). Prinsip hukum kepegawaian menegaskan bahwa aparatur berhak menolak perintah atasan yang bertentangan dengan undang-undang pidana demi menjaga integritas negara. Maka dari itu, anggapan bahwa budaya menghapus hak asasi dan melegalkan perintah pidana adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>D. Budaya organisasi merupakan kekuatan absolut yang menghapus seluruh hak asasi manusia pegawai dan mewajibkan kepatuhan pidana ilegal.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena iklim budaya yang positif terbukti efektif menularkan etos kerja proaktif kepada aparatur.</li><li><strong>B</strong>: Merupakan pernyataan yang benar karena budaya keterbukaan dan keselamatan psikologis mendorong tumbuhnya budaya whistleblowing sehat.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena fungsi utama budaya memang mereduksi ambiguitas moral dengan memberikan pedoman yang jelas.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena budaya orientasi hasil memang merangsang inovasi pemecahan masalah operasional birokrasi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Evaluatif", "question": "Di sebuah kantor pelayanan kepabeanan di pelabuhan, kepala kantor baru mendapati adanya 'sub-budaya tandingan' (counter-culture) di seksi pemeriksaan barang yang membiasakan diri menerima uang terima kasih dari agen pengapalan dengan dalih uang lelah tradisi lama. Penilaian dan langkah kepemimpinan yang paling tepat dilakukan oleh kepala kantor adalah...", "options": ["Mendiamkan tradisi tersebut karena tidak ingin menimbulkan konflik horizontal dengan kelompok pemeriksa barang yang berkuasa di pelabuhan.", "Ikut menerima bagian dari uang lelah tradisi tersebut asalkan uangnya ditransfer menggunakan mata uang kripto luar negeri yang anonim.", "Memindahkan seluruh agen pengapalan ke pelabuhan pulau terpencil di luar negeri tanpa adanya koordinasi dengan kementerian perhubungan.", "Meminta seluruh pegawai yang menolak uang lelah tradisi untuk mengundurkan diri secara sukarela dari lingkungan kantor kepabeanan.", "Menindak tegas praktik tersebut melalui rotasi petugas, penegakan disiplin kode etik, dan memasang kamera pemantau terhubung sistem pusat."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kepemimpinan bertugas **mengikis dan memusnahkan sub-budaya koruptif tandingan** (**counter-culture of corruption**) melalui tindakan represif penegakan disiplin etika, perombakan formasi penugasan (*rotation*), dan pengawasan teknologi terpusat.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E menyajikan evaluasi tindakan kepemimpinan yang paling berani, tegas, dan berlandaskan mandat pembersihan integritas institusi. Secara teori perubahan budaya, sub-budaya menyimpang yang telah mengakar sebagai 'tradisi uang lelah' tidak akan hilang dengan kompromi atau pembiaran pasif, melainkan menuntut pemutusan mata rantai kolusi melalui rotasi personel secara berkala, penindakan hukuman disiplin berat bagi oknum pelanggar, serta penutupan ruang gelap interaksi transaksi lewat pengawasan CCTV terpusat. Keberhasilan reformasi pelabuhan Kementerian Keuangan membuktikan bahwa ketegasan menindak sub-budaya suap berhasil mengembalikan reputasi kepabeanan nasional. Oleh sebab itu, tindakan tegas opsi E merupakan kepemimpinan nilai yang sejati.</p><p>Jawaban yang sesuai adalah <strong>E. Menindak tegas praktik tersebut melalui rotasi petugas, penegakan disiplin kode etik, dan memasang kamera pemantau terhubung sistem pusat.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membiarkan praktik pungli mencerminkan kepemimpinan pengecut yang berkhianat terhadap sumpah jabatan penegakan hukum.</li><li><strong>B</strong>: Salah karena ikut menerima uang suap kripto merupakan tindak pidana korupsi pencucian uang dan kejahatan jabatan yang sangat memalukan.</li><li><strong>C</strong>: Salah karena memindahkan operasional agen pengapalan secara sepihak melanggar wewenang tata kelola logistik maritim nasional.</li><li><strong>D</strong>: Salah karena memecat pegawai jujur yang menolak korupsi merupakan kezaliman terbalik yang menghancurkan masa depan institusi dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 15", "difficulty": "HOTS • Aplikasi", "question": "Seorang wajib pajak penyandang disabilitas tuna rungu datang ke loket kantor pelayanan perpajakan untuk berkonsultasi mengenai pelaporan SPT tahunan. Mengacu pada budaya pelayanan kementerian keuangan yang berorientasi pada kemanusiaan dan kepuasan publik, tindakan petugas loket yang paling tepat adalah...", "options": ["Menolak melayani wajib pajak tersebut dan memintanya pulang ke rumah hingga mampu membawa juru bicara bahasa lisan pribadi.", "Menyambut ramah, berkomunikasi menggunakan tulisan tangan atau aplikasi penerjemah teks digital, dan memandu pengisian SPT hingga tuntas.", "Menyuruh petugas keamanan kantor untuk mengawal wajib pajak tersebut keluar dari area pintu gerbang kantor pelayanan dinas.", "Berteriak sekeras-kerasnya di depan telinga wajib pajak tersebut hingga seluruh orang di ruang tunggu kantor merasa kaget dan terganggu.", "Mengenakan tarif denda khusus keterlambatan pelayanan karena menganggap wajib pajak disabilitas memperlambat antrean loket dinas."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 15", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 15</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Budaya pelayanan publik yang unggul mewajibkan **kesiapsiagaan melayani kelompok rentan** (**inclusive service culture**) dengan kesabaran, empati, dan pemanfaatan media komunikasi alternatif (tulisan/digital) guna menjamin hak warga negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah tindakan aplikasi budaya pelayanan yang paling mulia, empatik, dan menjunjung tinggi hak asasi manusia serta martabat warga negara. Secara etika pelayanan publik, keterbatasan fisik warga penyandang disabilitas tidak boleh menjadi alasan penolakan hak atas layanan negara, melainkan menuntut kreativitas humanis aparatur untuk menyediakan sarana komunikasi tulisan atau teknologi digital agar substansi perpajakan dapat dipahami secara tuntas dan nyaman. Pengalaman unit pelayanan inklusif di lingkungan kementerian membuktikan bahwa ketulusan petugas loket dalam melayani kelompok rentan menuai simpati dan kepercayaan publik yang luar biasa. Oleh karenanya, menyambut ramah dan memandu via teks merupakan cerminan budaya pelayanan prima.</p><p>Jawaban yang sesuai adalah <strong>B. Menyambut ramah, berkomunikasi menggunakan tulisan tangan atau aplikasi penerjemah teks digital, dan memandu pengisian SPT hingga tuntas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menolak melayani warga disabilitas melanggar undang-undang penyandang disabilitas dan mencoreng martabat birokrasi negara.</li><li><strong>C</strong>: Salah karena mengusir pemohon layanan merupakan kezaliman birokrasi dan bentuk diskriminasi sosial yang diancam sanksi hukum berat.</li><li><strong>D</strong>: Salah karena berteriak di depan umum mempermalukan wajib pajak tuna rungu dan mencerminkan ketidakpahaman etika komunikasi inklusif.</li><li><strong>E</strong>: Salah karena memungut denda khusus kepada warga disabilitas merupakan pemerasan ilegal yang melanggar hak kesetaraan warga negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 15.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Analitis", "question": "Kementerian PANRB menerbitkan Surat Edaran Nomor 20 Tahun 2021 tentang Implementasi Core Values dan Employer Branding ASN yang diresmikan oleh Presiden Joko Widodo pada 27 Juli 2021. Alasan filosofis dan strategis paling mendasar di balik penyatuan nilai-nilai dasar ASN di seluruh Indonesia ke dalam BerAKHLAK adalah...", "options": ["Mewajibkan seluruh instansi pemerintah untuk membeli seragam batik baru yang diproduksi oleh perusahaan milik keluarga pejabat kementerian.", "Menghapuskan sistem otonomi daerah dan memusatkan seluruh penerimaan pajak bumi dan bangunan ke kas kementerian keuangan pusat.", "Menyeragamkan nilai dasar aparatur sipil negara secara nasional agar memiliki kesamaan orientasi melayani rakyat dan bebas ego sektoral.", "Meniadakan seluruh pengawasan korupsi oleh aparat penegak hukum dan menyerahkan penilaian moral sepenuhnya kepada bupati di daerah.", "Mempermudah proses pemberhentian massal aparatur sipil negara yang telah berusia di atas empat puluh tahun di seluruh pelosok negeri."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Penyatuan nilai dasar ASN ke dalam **Core Values BerAKHLAK** melalui SE Menteri PANRB No. 20 Tahun 2021 bertujuan **menyeragamkan budaya kerja aparatur secara nasional**, menghapus ego sektoral dan fragmentasi kedaerahan, serta menyatukan orientasi pelayanan publik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah analisis latar belakang kebijakan yang paling akurat, komprehensif, dan selaras dengan amanat reformasi birokrasi nasional. Sebelum lahirnya BerAKHLAK, setiap kementerian, lembaga, dan pemerintah daerah merumuskan nilai dinasnya sendiri-sendiri secara terkotak-kotak, yang kerap melahirkan sekat ego sektoral, hambatan mobilitas karier aparatur antardaerah, dan inkonsistensi standar pelayanan publik bagi masyarakat. Kebijakan Presiden Joko Widodo menyeragamkan nilai dasar ASN membuktikan bahwa penyeragaman nilai moral BerAKHLAK sukses memfasilitasi transformasi digital terpadu dan mobilitas talenta ASN nasional. Oleh sebab itu, menyeragamkan orientasi pelayanan dan menghapus ego sektoral merupakan esensi strategis utama peluncuran BerAKHLAK.</p><p>Jawaban yang sesuai adalah <strong>C. Menyeragamkan nilai dasar aparatur sipil negara secara nasional agar memiliki kesamaan orientasi melayani rakyat dan bebas ego sektoral.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena peluncuran BerAKHLAK berfokus pada transformasi karakter moralitas kerja aparatur, bukan monopoli bisnis seragam dinas.</li><li><strong>B</strong>: Salah karena pengelolaan PBB dan otonomi fiskal daerah diatur dalam undang-undang perimbangan keuangan, bukan melalui SE Core Values ASN.</li><li><strong>D</strong>: Salah karena penegakan hukum korupsi justru semakin diperketat dengan menjadikan akuntabilitas sebagai pilar utama BerAKHLAK.</li><li><strong>E</strong>: Salah karena regulasi nilai dasar ASN bertujuan mengembangkan kompetensi talenta aparatur, bukan dasar pemecatan sepihak berbasis usia.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Aplikasi", "question": "Nilai 'Berorientasi Pelayanan' memiliki panduan perilaku utama: memahami dan memenuhi kebutuhan masyarakat. Seorang kepala seksi pelayanan perizinan kepabeanan mendapati banyaknya pelaku UMKM ekspor rempah-rempah yang kesulitan memahami dokumen Certificate of Origin secara digital. Tindakan yang paling tepat mencerminkan panduan perilaku Berorientasi Pelayanan adalah...", "options": ["Membuka klinik konsultasi ekspor UMKM gratis, menyediakan panduan infografis ringkas, dan mendampingi hingga berkas ekspor terbit.", "Menolak seluruh permohonan ekspor rempah UMKM tersebut dan menyuruh mereka menyewa jasa agen konsultan swasta yang berbiaya mahal.", "Menyita barang rempah-rempah yang hendak diekspor dengan alasan pemilik usaha UMKM tidak menguasai istilah teknis kepabeanan dinas.", "Meminta bagian saham sebesar tiga puluh persen pada usaha UMKM rempah sebagai imbalan pengesahan dokumen Certificate of Origin.", "Membiarkan berkas ekspor UMKM menumpuk di meja kerja tanpa kepastian waktu penyelesaian hingga barang rempah membusuk di gudang."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Panduan perilaku **Berorientasi Pelayanan** menuntut aparatur untuk **proaktif memahami dan memenuhi kebutuhan masyarakat** melalui pendampingan konsultatif gratis, edukasi proses yang ramah, dan percepatan fasilitasi ekspor produk rakyat.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah cerminan implementasi nilai Berorientasi Pelayanan yang paling nyata, solutif, dan berpihak pada ekonomi kerakyatan. Secara mandat pelayanan publik, aparatur negara hadir bukan untuk mempersulit birokrasi melainkan menjadi fasilitator dan problem solver bagi pelaku usaha kecil agar mampu menembus pasar global dan meningkatkan devisa ekspor negara. Fakta keberhasilan program Klinik Ekspor di berbagai kantor kepabeanan daerah membuktikan bahwa pendampingan sabar kepada pelaku UMKM sukses melipatgandakan volume ekspor daerah dan mengangkat kesejahteraan petani rempah. Oleh karenanya, membuka klinik konsultasi gratis dan mendampingi hingga terbit merupakan wujud sejati Berorientasi Pelayanan.</p><p>Jawaban yang sesuai adalah <strong>A. Membuka klinik konsultasi ekspor UMKM gratis, menyediakan panduan infografis ringkas, dan mendampingi hingga berkas ekspor terbit.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena memaksa UMKM menyewa jasa agen swasta mahal bertentangan dengan komitmen negara dalam memfasilitasi kemudahan berusaha.</li><li><strong>C</strong>: Salah karena menyita barang komoditas ekspor tanpa pelanggaran hukum pidana merupakan tindakan penyalahgunaan wewenang sewenang-wenang.</li><li><strong>D</strong>: Salah karena meminta bagian saham kepemilikan usaha merupakan tindak pidana korupsi pemerasan dalam jabatan dan pemerasan ekonomi.</li><li><strong>E</strong>: Salah karena menelantarkan berkas ekspor hingga barang membusuk merupakan bentuk kelalaian tugas berat yang merugikan perekonomian rakyat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Analitis", "question": "Aparatur sipil negara diwajibkan mempraktikkan panduan perilaku berorientasi pelayanan: ramah, cekatan, solutif, dan dapat diandalkan. Di antara skenario pelayanan berikut, manakah perilaku yang BUKAN merupakan wujud dari panduan perilaku tersebut di lingkungan kantor pemerintah?", "options": ["Petugas loket menyapa pemohon dengan senyuman santun dan memberikan penjelasan alur verifikasi dengan bahasa yang mudah dipahami.", "Petugas perbendaharaan langsung menelusuri akar kendala sistem ketika dana transfer ke kas daerah mengalami retur pencairan di bank.", "Aparatur bersedia dihubungi pada jam kerja untuk memberikan kepastian tindak lanjut atas permohonan restitusi pajak yang diajukan wajib pajak.", "Petugas loket sigap memproses berkas permohonan surat keterangan fiskal sesuai standar operasional prosedur tanpa menunda waktu dinas.", "Petugas meja informasi memasang wajah masam, memarahi masyarakat yang bertanya alur berkas, dan menyuruh pemohon mencari informasi sendiri."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Panduan perilaku Berorientasi Pelayanan mewajibkan **sikap ramah, cekatan, solutif, dan dapat diandalkan**. Bersikap judes, memarahi masyarakat, dan melempar tanggung jawab (**unfriendly and unhelpful**) merupakan **pelanggaran nyata terhadap core values ASN**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E merupakan contoh tindakan yang tidak etis dan mencoreng martabat korps aparatur sipil negara di hadapan masyarakat luas. Secara standar pelayanan publik modern, petugas garis depan (frontliner) adalah representasi wajah negara, di mana sikap sinis, memarahi warga, dan menolak memberikan panduan informasi mencerminkan arogansi priyayi kolonial masa lalu yang sangat dibenci masyarakat pembayar pajak. Laporan evaluasi ombudsman menunjukkan bahwa sikap tidak ramah petugas loket merupakan sumber keluhan masyarakat nomor satu di unit pelayanan publik. Oleh sebab itu, memasang wajah masam dan memarahi pemohon jelas bertolak belakang dengan panduan perilaku Berorientasi Pelayanan.</p><p>Jawaban yang sesuai adalah <strong>E. Petugas meja informasi memasang wajah masam, memarahi masyarakat yang bertanya alur berkas, dan menyuruh pemohon mencari informasi sendiri.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan penerapan sikap ramah (friendly) yang humanis dalam menciptakan kenyamanan komunikasi pelayanan publik di kantor dinas.</li><li><strong>B</strong>: Merupakan cerminan sikap cekatan dan solutif (responsive and problem-solving) dalam mengatasi kendala perbankan perbendaharaan negara.</li><li><strong>C</strong>: Merupakan manifestasi aparatur yang dapat diandalkan (reliable) dalam memberikan kepastian informasi hak restitusi keuangan warga.</li><li><strong>D</strong>: Merupakan wujud sikap cekatan dan disiplin waktu operasional dalam menyelesaikan dokumen masyarakat tanpa penundaan berbelit-belit.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Aplikasi", "question": "Salah satu butir panduan perilaku Berorientasi Pelayanan adalah melakukan perbaikan tiada henti (continuous improvement). Seorang kepala kantor perbendaharaan mendapati bahwa waktu tunggu pencairan dana bantuan operasional sekolah (BOS) masih memakan waktu dua hari kerja. Inisiatif yang paling tepat mencerminkan semangat perbaikan tiada henti adalah...", "options": ["Menambah tahapan verifikasi berkas menjadi sepuluh meja pejabat guna membuktikan bahwa kantor perbendaharaan bekerja sangat teliti.", "Melakukan simplifikasi proses bisnis melalui integrasi sistem validasi digital sehingga pencairan BOS tuntas dalam hitungan jam sah.", "Menghentikan seluruh pencairan dana BOS ke sekolah-sekolah di wilayahnya agar staf perbendaharaan dapat beristirahat dengan tenang.", "Mengharuskan kepala sekolah datang secara fisik ke kantor kementerian keuangan pusat di ibu kota negara membawa berkas hardcopy.", "Mewajibkan sekolah menyetor uang administrasi percepatan pencairan dana BOS sebesar lima persen dari total alokasi yang disalurkan."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Prinsip **perbaikan tiada henti** (**continuous improvement**) mendorong inovasi **penyederhanaan proses bisnis** (**business process reengineering**) guna memangkas birokrasi, menghemat waktu pelayanan publik, dan meningkatkan kemanfaatan anggaran negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah inisiatif manajerial yang paling tepat, progresif, dan selaras dengan prinsip perbaikan tiada henti. Secara tata kelola perbendaharaan modern, perbaikan berkesinambungan bermakna meninjau kembali titik-titik sumbatan birokrasi (bottlenecks) dan memanfaatkan teknologi integrasi basis data agar hak keuangan sekolah untuk mendidik anak bangsa dapat disalurkan secara instan, aman, dan tanpa biaya perantara. Fakta implementasi SPAN dan SAKTI di perbendaharaan membuktikan bahwa digitalisasi proses sukses memangkas waktu pencairan dari berhari-hari menjadi hitungan menit. Maka dari itu, simplifikasi proses melalui integrasi digital merupakan cerminan perbaikan tiada henti yang sesungguhnya.</p><p>Jawaban yang sesuai adalah <strong>B. Melakukan simplifikasi proses bisnis melalui integrasi sistem validasi digital sehingga pencairan BOS tuntas dalam hitungan jam sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menambah meja birokrasi menjadi sepuluh meja merupakan langkah mundur yang memperparah inefisiensi birokrasi dinas.</li><li><strong>C</strong>: Salah karena menghentikan penyaluran dana pendidikan melanggar amanat konstitusi dan merugikan hak belajar jutaan anak sekolah.</li><li><strong>D</strong>: Salah karena memaksa kepala sekolah daerah bepergian ke ibu kota memboroskan anggaran sekolah dan menyiksa tenaga pendidik.</li><li><strong>E</strong>: Salah karena memungut potongan lima persen dari dana BOS sekolah merupakan tindak pidana korupsi pemotongan dana bantuan sosial.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Evaluatif", "question": "Pimpinan instansi menginstruksikan agar seluruh pegawai di unit pelayanan tidak hanya dinilai dari tercapainya target penerimaan nominal kas negara, melainkan juga dinilai kepatuhannya terhadap perilaku Berorientasi Pelayanan melalui survei kepuasan berkala kepada masyarakat. Penilaian yang paling tepat terhadap kebijakan pimpinan instansi tersebut adalah...", "options": ["Kebijakan yang membuang waktu dinas karena aparatur pemerintah hanya bertanggung jawab kepada atasan dinas, bukan kepada masyarakat.", "Keputusan yang keliru karena kepuasan masyarakat tidak memiliki hubungan logis dengan kelangsungan kedaulatan penerimaan keuangan negara.", "Langkah yang merugikan aparatur karena masyarakat pada umumnya selalu memberikan penilaian buruk kepada instansi kementerian.", "Keputusan yang sangat tepat karena menyeimbangkan orientasi hasil kuantitatif dengan keluhuran mutu pelayanan publik berkeadilan.", "Kebijakan yang melanggar undang-undang kepegawaian karena kinerja ASN hanya boleh diukur melalui kehadiran fisik mesin sidik jari kantor."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integrasi Core Values BerAKHLAK ke dalam penilaian kinerja menuntut keseimbangan antara **target hasil kuantitatif** (**what**) dengan **perilaku etika pelayanan dan kepuasan masyarakat** (**how**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D memberikan evaluasi manajerial yang paling tepat, modern, dan selaras dengan doktrin reformasi birokrasi nasional. Secara teori akuntabilitas publik, aparatur sipil negara digaji oleh rakyat melalui pajak negara, sehingga mengukur kepuasan masyarakat pengguna layanan merupakan indikator kinerja utama (IKU) yang sangat sah untuk menilai apakah mandat kedaulatan telah dijalankan secara bermartabat dan memuaskan rakyat. Rekam jejak penilaian reformasi kementerian membuktikan bahwa integrasi indeks kepuasan masyarakat mendorong aparatur untuk melayani secara tulus dan mengikis mentalitas ingin dilayani. Oleh karenanya, menyeimbangkan target nominal dan kepuasan publik merupakan kebijakan kepemimpinan yang paripurna.</p><p>Jawaban yang sesuai adalah <strong>D. Keputusan yang sangat tepat karena menyeimbangkan orientasi hasil kuantitatif dengan keluhuran mutu pelayanan publik berkeadilan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena aparatur adalah pelayan masyarakat (civil servant) yang memikul mandat moral melayani kepentingan seluruh rakyat Indonesia.</li><li><strong>B</strong>: Salah karena kepuasan masyarakat adalah kunci utama kepatuhan sukarela (voluntary compliance) dalam membayar pajak negara.</li><li><strong>C</strong>: Salah karena fakta membuktikan masyarakat sangat objektif dan memberikan apresiasi tinggi pada unit dinas yang melayani secara tulus.</li><li><strong>E</strong>: Salah karena undang-undang manajemen ASN modern mewajibkan penilaian berbasis hasil kerja nyata dan evaluasi perilaku etika berbobot.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan butir panduan perilaku Berorientasi Pelayanan (memahami kebutuhan, ramah, cekatan, solutif, handal, dan perbaikan tiada henti), rancangan standar pelayanan loket terpadu yang paling komprehensif untuk diterapkan di seluruh kantor pelayanan fiskal daerah adalah...", "options": ["Menyediakan antrean digital berkeadilan, standar waktu penyelesaian transparan, ruang ramah disabilitas, dan evaluasi kepuasan harian.", "Mewajibkan masyarakat membawa surat rekomendasi dari partai politik berkuasa sebelum diberikan nomor urut antrean loket pelayanan dinas.", "Menetapkan tarif parkir kendaraan bermotor yang sangat mahal di halaman kantor guna mencegah masyarakat datang mengurus dokumen izin.", "Memasang pengeras suara bervolume tinggi yang menyiarkan lagu mars instansi secara berulang guna mendominasi suasana ruang tunggu.", "Mewajibkan seluruh staf loket mengenakan topeng pelindung wajah hitam pekat agar masyarakat tidak dapat mengenali identitas petugas dinas."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Rancangan standar pelayanan prima (**service excellence design**) mengintegrasikan **sistem antrean objektif**, **kepastian waktu penyelesaian**, **fasilitas inklusif ramah kelompok rentan**, dan **mekanisme evaluasi umpan balik harian** (*real-time feedback*).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A menyajikan sintesis arsitektur pelayanan yang paling utuh, teruji, dan memenuhi standar pelayanan publik internasional. Secara tata kelola pelayanan publik, kepuasan masyarakat tercipta ketika ada kepastian antrean tanpa calo (antrean digital), kejelasan batas waktu pemrosesan izin (transparansi janji layanan), kemudahan akses bagi warga lansia dan disabilitas, serta ruang evaluasi kepuasan langsung di meja loket (e-survey). Implementasi di kantor pelayanan modern membuktikan bahwa kombinasi keempat fasilitas ini berhasil mengantarkan instansi meraih predikat kepuasan publik bintang lima secara berkelanjutan. Oleh karena itu, perpaduan sistem antrean, kepastian waktu, sarana inklusif, dan evaluasi harian merupakan formula terbaik.</p><p>Jawaban yang sesuai adalah <strong>A. Menyediakan antrean digital berkeadilan, standar waktu penyelesaian transparan, ruang ramah disabilitas, dan evaluasi kepuasan harian.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena mencampuradukkan rekomendasi partai politik melanggar asas netralitas aparatur sipil negara dan mencederai keadilan publik.</li><li><strong>C</strong>: Salah karena memungut tarif parkir mahal demi menghalau kedatangan warga mencerminkan sabotase hak pelayanan publik masyarakat.</li><li><strong>D</strong>: Salah karena kebisingan pengeras suara mars dinas mengganggu kenyamanan komunikasi dan mencerminkan arogansi militeristik semu.</li><li><strong>E</strong>: Salah karena mewajibkan topeng wajah hitam melanggar asas transparansi identitas dinas dan menciptakan kecurigaan publik di loket.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Analitis", "question": "Pemaknaan yang benar terhadap nilai Berorientasi Pelayanan sangat penting agar aparatur tidak salah dalam mengeksekusi wewenang tugasnya. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai hakikat nilai Berorientasi Pelayanan bagi aparatur sipil negara?", "options": ["Berorientasi pelayanan menuntut aparatur untuk bersikap solutif dalam membantu kendala administrasi yang dihadapi masyarakat pengguna.", "Berorientasi pelayanan mendorong aparatur melakukan perbaikan berkelanjutan terhadap sarana dan prosedur kerja birokrasi di kantor.", "Berorientasi pelayanan mewajibkan sikap ramah dan cekatan dalam menyapa serta menuntaskan urusan permohonan dinas masyarakat.", "Berorientasi pelayanan berarti aparatur wajib mengabulkan seluruh permintaan masyarakat meskipun secara nyata melanggar regulasi hukum.", "Berorientasi pelayanan menempatkan kepuasan masyarakat yang sah sebagai salah satu tolok ukur utama keberhasilan pelaksanaan tugas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai Berorientasi Pelayanan **harus selalu berada dalam koridor hukum dan kepatuhan regulasi** (**legal compliance**). Menuruti permintaan warga yang melanggar hukum bukan bentuk pelayanan, melainkan **tindakan maladministrasi dan tindak pidana kolusi**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah simpulan yang salah, menyesatkan, dan merusak kepatuhan hukum aparatur sipil negara. Secara hukum administrasi pemerintahan, prinsip pelayanan prima menuntut aparatur untuk membantu masyarakat secara ramah dan solutif namun tetap teguh mematuhi batasan peraturan perundang-undangan, sehingga menolak permintaan ilegal—seperti permintaan manipulasi pajak atau penyelundupan barang—justru merupakan bagian dari menjaga integritas pelayanan publik itu sendiri. Putusan peradilan tipikor menegaskan bahwa dalih 'melayani dan menyenangkan masyarakat' tidak dapat membenarkan tindakan meloloskan dokumen yang melanggar hukum negara. Oleh karenanya, menyatakan bahwa aparatur wajib menuruti permintaan yang melanggar hukum adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>D. Berorientasi pelayanan berarti aparatur wajib mengabulkan seluruh permintaan masyarakat meskipun secara nyata melanggar regulasi hukum.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena sikap solutif membantu kendala warga merupakan butir panduan perilaku Berorientasi Pelayanan.</li><li><strong>B</strong>: Merupakan pernyataan yang benar karena semangat continuous improvement memang menjadi pilar penyempurnaan mutu layanan publik.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena keramahan dan kecekatan merupakan etika dasar yang wajib ditunjukkan setiap aparatur di loket.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena kepuasan masyarakat yang sah memang menjadi tolok ukur efektivitas kinerja aparatur sipil negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Evaluatif", "question": "Sebuah kantor pelayanan pajak di kawasan sentra pertanian meluncurkan program 'Mobil Pajak Keliling' yang mendatangi desa-desa terpencil pada hari pasar tradisional guna melayani pendaftaran NPWP dan asistensi pelaporan SPT para petani. Penilaian yang paling tepat terhadap inisiatif kantor pelayanan tersebut berdasarkan nilai Berorientasi Pelayanan adalah...", "options": ["Tindakan yang keliru karena petani desa seharusnya dipaksa datang sendiri ke kantor ibu kota kabupaten dengan menaiki angkutan umum.", "Langkah yang membuang waktu dinas karena sektor pertanian tradisional dipandang tidak memberikan kontribusi pada penerimaan pajak negara.", "Kebijakan yang melanggar aturan hukum dinas karena mobil dinas kementerian tidak boleh digunakan melintasi jalanan pedesaan yang berlumpur.", "Tindakan yang merendahkan martabat aparatur sipil negara karena pegawai berpangkat golongan tiga tidak pantas melayani masyarakat desa.", "Inisiatif jemput bola yang sangat luhur dan tepat sasaran karena proaktif memahami dan memenuhi kebutuhan layanan masyarakat pedesaan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Inisiatif **jemput bola** (**proactive outreach service**) mencerminkan komitmen tertinggi nilai **Berorientasi Pelayanan**, di mana aparatur mendekatkan akses layanan publik kepada masyarakat di pelosok yang mengalami hambatan geografis.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E memberikan penilaian yang paling tepat, apresiatif, dan selaras dengan mandat keadilan sosial pelayanan publik. Secara teori administrasi publik, aparatur negara tidak boleh bersikap pasif hanya menunggu di kantor ber-AC, melainkan wajib proaktif menjangkau kantong-kantong masyarakat rentan yang memiliki keterbatasan sarana digital dan transportasi agar hak-hak perpajakan dan edukasi keuangan negara dirasakan merata oleh seluruh lapisan bangsa. Keberhasilan program Mobil Pajak Keliling membuktikan peningkatan signifikan dalam kepatuhan wajib pajak sektor pertanian dan menuai kebanggaan masyarakat desa terhadap kementerian keuangan. Maka dari itu, inisiatif jemput bola tersebut merupakan manifestasi luhur Berorientasi Pelayanan.</p><p>Jawaban yang sesuai adalah <strong>E. Inisiatif jemput bola yang sangat luhur dan tepat sasaran karena proaktif memahami dan memenuhi kebutuhan layanan masyarakat pedesaan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena memaksa warga pelosok bepergian jauh dengan biaya mahal bertentangan dengan asas kemudahan akses pelayanan publik.</li><li><strong>B</strong>: Salah karena sektor pertanian adalah tulang punggung ketahanan pangan nasional yang berhak mendapatkan pembinaan fiskal yang setara.</li><li><strong>C</strong>: Salah karena mobil dinas operasional pelayanan memang dirancang untuk menjangkau seluruh medan geografis wilayah penugasan dinas.</li><li><strong>D</strong>: Salah karena memandang rendah masyarakat desa mencerminkan mentalitas feodal priyayi kolonial yang merusak martabat korps ASN.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Aplikasi", "question": "Pada saat batas akhir pelaporan SPT tahunan secara daring, terjadi lonjakan akses publik yang mengakibatkan laman pelaporan pajak nasional mengalami kelambatan transaksi. Seorang pejabat penanggung jawab pusat kontak bantuan (contact center) kementerian keuangan dihadapkan pada ratusan telepon keluhan masyarakat yang panik. Sikap cekatan dan solutif yang wajib diambil oleh pejabat tersebut adalah...", "options": ["Mencabut seluruh sambungan kabel telepon kantor bantuan agar para operator tidak perlu mendengarkan keluhan panik dari masyarakat.", "Menambah kapasitas petugas respons cepat daring, menyajikan panduan pengisian bertahap, dan mengumumkan komitmen solusi perbaikan.", "Menyalahkan masyarakat yang baru melapor pada hari terakhir dan mengancam akan mengenakan denda maksimal kepada seluruh penelepon.", "Mengunggah pesan suara otomatis yang menyatakan bahwa kementerian keuangan tidak bertanggung jawab atas kegagalan sistem daring.", "Menutup kantor bantuan dan memulangkan seluruh pegawai operator lebih awal agar terhindar dari stres menghadapi keluhan masyarakat."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Panduan perilaku **cekatan dan solutif** menuntut aparatur untuk **tanggap mengurai kepanikan publik dalam krisis sistemik**, memperkuat kapasitas respon komunikasi darurat, serta memberikan kepastian solusi dan rasa tenang bagi masyarakat.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah tindakan kepemimpinan krisis yang paling cekatan, bertanggung jawab, dan menenangkan masyarakat pengguna layanan. Secara manajemen komunikasi krisis pelayanan publik, kepanikan masyarakat akibat gangguan sistem TI di hari tenggat waktu harus dijawab dengan keterbukaan informasi, penambahan kanal dan staf pemandu (contingency response team), serta penjelasan solutif bahwa hak-hak pelaporan wajib pajak dijamin tidak dirugikan oleh kendala teknis peladen pusat. Fakta penanganan krisis di Direktorat Jenderal Pajak membuktikan bahwa respons cepat dan proaktif mampu meredam kepanikan publik dan memulihkan kelancaran pelaporan SPT secara teratur. Oleh sebab itu, penguatan kanal bantuan dan panduan solutif mencerminkan jiwa Berorientasi Pelayanan sejati.</p><p>Jawaban yang sesuai adalah <strong>B. Menambah kapasitas petugas respons cepat daring, menyajikan panduan pengisian bertahap, dan mengumumkan komitmen solusi perbaikan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena memutus kabel telepon merupakan tindakan pengecut yang melanggar undang-undang keterbukaan informasi publik dinas.</li><li><strong>C</strong>: Salah karena menyalahkan dan mengintimidasi warga yang panik mencerminkan arogansi birokrasi yang memperkeruh situasi krisis.</li><li><strong>D</strong>: Salah karena melepaskan tanggung jawab kelembagaan meruntuhkan kredibilitas institusi pemerintah di mata masyarakat pembayar pajak.</li><li><strong>E</strong>: Salah karena memulangkan petugas saat masyarakat membutuhkan bantuan merupakan desersi dinas dan pelanggaran etika kepemimpinan berat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 16", "difficulty": "HOTS • Kreasi", "question": "Sebuah satuan kerja kantor perbendaharaan yang baru dibentuk bertekad membangun budaya Berorientasi Pelayanan sejak hari pertama operasionalnya. Formula program internalisasi yang paling efektif untuk menanamkan jiwa melayani ke dalam sanubari seluruh jajaran staf adalah...", "options": ["Mewajibkan pegawai menghafalkan seluruh pasal undang-undang perbendaharaan negara di bawah ancaman pemotongan tunjangan operasional.", "Melarang seluruh staf tersenyum saat jam kerja berlangsung agar kantor perbendaharaan terlihat sangat berwibawa dan menakutkan.", "Memadukan pelatihan hospitality pelayanan prima, simulasi penanganan keluhan sulit, teladan atasan, dan penghargaan staf teramah.", "Mengganti seluruh staf loket pelayanan dengan kerabat keluarga kepala kantor agar seluruh transaksi keuangan dapat diatur secara rahasia.", "Menyediakan ruang khusus di kantor pelayanan tempat pimpinan dapat menerima bingkisan cinderamata mewah dari satuan kerja mitra."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 16", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 16</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Membangun budaya Berorientasi Pelayanan menuntut **pendekatan multi-dimensi**: **pelatihan kompetensi keramahtamahan** (*hospitality skills*), **simulasi pemecahan komplain** (*complaint handling*), **keteladanan pemimpin**, serta **apresiasi perilaku unggul** (*recognition*).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C menyajikan sintesis pembudayaan nilai pelayanan yang paling komprehensif, humanis, dan berorientasi keunggulan mutu. Secara psikologi perilaku kerja, keterampilan melayani dengan tulus (hospitality) tidak lahir dari paksaan ancaman sanksi, melainkan diasah melalui pelatihan keterampilan komunikasi empatik, pembiasaan simulasi menghadapi situasi sulit di loket, keteladanan atasan yang memperlakukan bawahan secara santun, serta pemberian penghargaan rutin (employee of the month) bagi staf berkinerja teramah. Pengalaman percontohan kantor modern membuktikan bahwa ekosistem pembinaan terpadu ini sukses mencetak aparatur yang ramah dan solutif secara konsisten. Maka dari itu, formulasi opsi C merupakan strategi pembudayaan terbaik.</p><p>Jawaban yang sesuai adalah <strong>C. Memadukan pelatihan hospitality pelayanan prima, simulasi penanganan keluhan sulit, teladan atasan, dan penghargaan staf teramah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena hafalan pasal di bawah ancaman sanksi uang melahirkan ketakutan kaku yang mematikan kehangatan senyum pelayanan publik.</li><li><strong>B</strong>: Salah karena melarang tersenyum demi kewibawaan menakutkan mencerminkan pemikiran usang feodalisme yang ditentang reformasi birokrasi.</li><li><strong>D</strong>: Salah karena memasukkan kerabat keluarga untuk transaksi rahasia merupakan tindak pidana korupsi kolusi dan nepotisme yang melanggar hukum.</li><li><strong>E</strong>: Salah karena menyediakan ruangan penerimaan cinderamata rekanan merupakan pelembagaan gratifikasi ilegal yang merusak integritas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 16.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Analitis", "question": "Nilai Akuntabel memuat panduan perilaku: menggunakan kekayaan dan barang milik negara secara bertanggung jawab, efektif, dan efisien. Di antara skenario pemanfaatan aset dinas berikut, tindakan aparatur yang mencerminkan pelanggaran paling nyata terhadap panduan perilaku Akuntabel tersebut adalah...", "options": ["Mematikan lampu ruangan kerja dan pendingin udara kantor saat jam istirahat dinas guna menghemat konsumsi energi listrik negara.", "Menggunakan kertas bekas yang masih bersih satu sisinya untuk mencetak draf dokumen telaah internal sebelum pencetakan naskah akhir.", "Menyimpan kendaraan dinas operasional di garasi kantor pada akhir pekan dan menggunakan kendaraan pribadi untuk urusan keluarga.", "Melakukan perawatan rutin berkala terhadap perangkat peladen komputer kantor agar masa pakai ekonomis perangkat bertahan lama.", "Menggunakan mobil dinas operasional kantor dan anggaran bensin dinas untuk mengantar keluarga berlibur ke luar kota pada akhir pekan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Panduan perilaku **Akuntabel** mewajibkan aparatur untuk **menggunakan barang milik negara (BMN) secara bertanggung jawab, efektif, dan efisien**. Menggunakan kendaraan dinas operasional untuk kepentingan rekreasi pribadi keluarga merupakan **penyalahgunaan aset negara** (**misuse of state property**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah contoh pelanggaran nyata terhadap panduan perilaku nilai Akuntabel dalam tata kelola barang milik negara. Secara regulasi perbendaharaan dan kode etik dinas, kendaraan dinas operasional dan jatah bahan bakar minyak dibiayai oleh uang pajak rakyat semata-mata untuk mendukung kelancaran tugas dinas kedinasan resmi, sehingga memanfaatkannya untuk urusan domestik rekreasi keluarga merupakan bentuk penyalahgunaan fasilitas negara yang merugikan keuangan kas dinas. Data pengawasan kepatuhan internal kementerian mencatat bahwa penyalahgunaan kendaraan dinas selalu dijatuhi sanksi hukuman disiplin kepegawaian. Oleh sebab itu, menggunakan mobil dinas untuk pelesir keluarga jelas merupakan pelanggaran nilai Akuntabel.</p><p>Jawaban yang sesuai adalah <strong>E. Menggunakan mobil dinas operasional kantor dan anggaran bensin dinas untuk mengantar keluarga berlibur ke luar kota pada akhir pekan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan wujud nyata efisiensi energi listrik yang sangat bertanggung jawab dalam menghemat biaya operasional kantor negara.</li><li><strong>B</strong>: Merupakan penerapan perilaku hemat dan efisien (eco-friendly) dalam memanfaatkan persediaan alat tulis kantor secara bijaksana.</li><li><strong>C</strong>: Merupakan cerminan integritas akuntabilitas tinggi di mana aparatur memisahkan secara tegas antara aset dinas dan kebutuhan privat.</li><li><strong>D</strong>: Merupakan manifestasi tanggung jawab aparatur dalam menjaga dan memelihara masa guna barang milik negara agar tidak cepat rusak.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Aplikasi", "question": "Nilai Akuntabel menegaskan kewajiban aparatur untuk tidak menyalahgunakan kewenangan jabatan. Seorang pejabat pembuat komitmen (PPK) didatangi oleh seorang kontraktor yang memohon agar tagihan termin proyeknya dilunasi seratus persen meskipun pekerjaan fisik bangunan baru mencapai delapan puluh persen. Sikap yang wajib diambil oleh PPK tersebut demi menjaga nilai Akuntabel adalah...", "options": ["Menyetujui pembayaran seratus persen asalkan kontraktor bersedia memberikan bagian uang terima kasih sebesar lima persen kepada PPK.", "Meminta kontraktor membuat surat pernyataan palsu yang menyatakan bahwa bangunan sudah selesai seratus persen agar terhindar audit BPK.", "Menolak pencairan seratus persen dan hanya menyetujui pembayaran sesuai kemajuan prestasi fisik pekerjaan riil yang terverifikasi sah.", "Melarikan diri ke luar negeri dengan membawa berkas tagihan kontraktor agar tidak perlu menandatangani dokumen pencairan dinas kantor.", "Mencairkan dana termin secara penuh lalu meminjam sebagian uang tersebut untuk modal usaha perdagangan saham pribadi di bursa efek."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Prinsip **Akuntabel** menuntut aparatur untuk **menolak penyalahgunaan wewenang** dan membayar tagihan belanja negara **berdasarkan prestasi kemajuan fisik pekerjaan riil yang sah** (**output-based payment**), guna mencegah kerugian keuangan negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah keputusan profesional yang paling tepat, berintegritas, dan patuh hukum perbendaharaan negara. Secara regulasi pengadaan barang dan jasa pemerintah (Peraturan Presiden tentang Pengadaan Barang/Jasa Pemerintah), pembayaran prestasi pekerjaan wajib didasarkan pada berita acara kemajuan fisik yang teruji secara faktual di lapangan, di mana mencairkan dana mendahului prestasi riil merupakan tindak pidana korupsi pembayaran fiktif yang merugikan keuangan negara. Fakta audit BPK menunjukkan bahwa PPK yang mencairkan termin di atas kemajuan fisik riil selalu ditetapkan sebagai tersangka tindak pidana korupsi. Maka dari itu, ketegasan menolak dan hanya membayar sesuai prestasi fisik riil 80% mencerminkan nilai Akuntabel sejati.</p><p>Jawaban yang sesuai adalah <strong>C. Menolak pencairan seratus persen dan hanya menyetujui pembayaran sesuai kemajuan prestasi fisik pekerjaan riil yang terverifikasi sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menyetujui pencairan fiktif demi imbalan lima persen merupakan tindak pidana suap dan korupsi pengeluaran kas negara.</li><li><strong>B</strong>: Salah karena membuat surat pernyataan palsu merupakan tindak pidana pemalsuan surat otentik yang melanggar hukum pidana materiil.</li><li><strong>D</strong>: Salah karena melarikan diri ke luar negeri mencerminkan kepengecutan desersi dinas yang tidak menyelesaikan tanggung jawab hukum PPK.</li><li><strong>E</strong>: Salah karena meminjam uang pencairan proyek dinas untuk spekulasi saham pribadi merupakan tindak pidana penggelapan kas negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Analitis", "question": "Nilai 'Kompeten' memuat panduan perilaku: meningkatkan kompetensi diri untuk menjawab tantangan yang selalu berubah, membantu orang lain belajar, dan melaksanakan tugas dengan kualitas terbaik. Dalam menghadapi implementasi sistem core tax terintegrasi yang baru, wujud nyata pengamalan nilai Kompeten oleh seorang fungsional penyuluh pajak adalah...", "options": ["Mempelajari modul sistem baru secara mendalam, melatih rekan sejawat, dan menyajikan panduan sosialisasi berkualitas bagi wajib pajak.", "Menolak menggunakan sistem digital baru tersebut dan mengajak seluruh wajib pajak untuk kembali menggunakan formulir kertas manual kuno.", "Menyembunyikan buku manual pengoperasian sistem baru di laci meja pribadi agar hanya dirinya yang dianggap pintar oleh pimpinan kantor.", "Menyewa tenaga joki lepas dari luar kementerian untuk mengoperasikan komputer dinasnya sepanjang hari kerja saat melayani publik.", "Mengajukan permohonan pensiun dini secara massal bersama seluruh staf seksi penyuluhan guna menghindari kewajiban belajar sistem baru."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Kompeten** mewujud dalam **pembelajar mandiri berkelanjutan** (**continuous learner**), kerelaan **berbagi pengetahuan kepada rekan sejawat** (*helping others learn*), serta **memberikan output kinerja berkualitas terbaik** bagi masyarakat pemangku kepentingan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A merangkum ketiga butir panduan perilaku nilai Kompeten secara paripurna dan saling menguatkan. Secara teori manajemen pengetahuan (knowledge management), menghadapi disrupsi sistem teknologi informasi modern menuntut aparatur untuk proaktif mengasah keahlian baru secara mandiri, menularkannya kepada rekan sejawat agar kapasitas tim merata, serta menghasilkan materi edukasi yang mudah dicerna masyarakat wajib pajak. Fakta keberhasilan migrasi sistem TI kementerian membuktikan bahwa aparatur yang kompeten dan gemar berbagi ilmu menjadi ujung tombak keberhasilan reformasi birokrasi nasional. Oleh karena itu, belajar mendalam, melatih rekan, dan melayani dengan mutu terbaik merupakan manifestasi sejati nilai Kompeten.</p><p>Jawaban yang sesuai adalah <strong>A. Mempelajari modul sistem baru secara mendalam, melatih rekan sejawat, dan menyajikan panduan sosialisasi berkualitas bagi wajib pajak.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena menolak sistem baru dan mengajak kembali ke manual merupakan bentuk resistensi destruktif terhadap kemajuan bangsa.</li><li><strong>C</strong>: Salah karena menyembunyikan ilmu pengetahuan demi pamrih pujian pribadi bertentangan dengan panduan perilaku membantu orang lain belajar.</li><li><strong>D</strong>: Salah karena menyewa joki luar untuk tugas kedinasan melanggar kerahasiaan jabatan dinas dan merupakan bentuk ketidakmampuan fatal.</li><li><strong>E</strong>: Salah karena melarikan diri dari kewajiban belajar mencerminkan mentalitas kemalasan birokrasi yang memalukan martabat korps ASN.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Analitis", "question": "Nilai 'Harmonis' menuntut aparatur untuk menghargai setiap orang apa pun latar belakangnya, suka menolong orang lain, dan membangun lingkungan kerja yang kondusif. Di antara situasi kerja berikut, manakah skenario yang BUKAN merupakan penerapan nilai Harmonis di lingkungan kerja kantor pemerintah?", "options": ["Pegawai mengucapkan selamat hari raya keagamaan secara tulus dan saling berbagi makanan kepada rekan kerja yang merayakannya.", "Pimpinan membagi penugasan tim audit secara diskriminatif dengan hanya menempatkan pegawai dari satu suku daerah tertentu di posisi basah.", "Aparatur secara sukarela membantu menyelesaikan beban administrasi rekan kerja yang sedang berduka atas wafatnya anggota keluarga.", "Seluruh pegawai menyambut hangat kedatangan staf mutasi baru dari luar pulau dan membantunya mencari tempat tinggal yang aman.", "Rapat pembahasan anggaran dinas diselenggarakan dengan suasana saling menghargai pendapat dan bebas dari ejekan bernuansa personal."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Harmonis** menolak segala bentuk **diskriminasi suku, agama, ras, dan antargolongan** (**SARA**). Membagi penugasan berbasis primordialisme kesukuan merupakan racun yang menghancurkan keharmonisan lingkungan kerja.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah skenario penyimpangan yang bertentangan secara frontal dengan hakikat nilai Harmonis dalam Core Values BerAKHLAK. Secara sosiologi organisasi dan hukum kepegawaian, membeda-bedakan pegawai berdasarkan suku dalam penugasan kerja merupakan tindakan diskriminasi primordial yang memicu kecemburuan sosial, merusak iklim kondusif kantor, dan memecah belah keutuhan persatuan aparatur sipil negara. Laporan pengawasan komisi ASN menegaskan bahwa praktik nepotisme kedaerahan merupakan pelanggaran berat kode etik yang dijatuhi sanksi pencopotan jabatan bagi pimpinan yang melakukannya. Oleh sebab itu, membagi penugasan secara diskriminatif suku jelas bukan penerapan nilai Harmonis melainkan perusak keharmonisan.</p><p>Jawaban yang sesuai adalah <strong>B. Pimpinan membagi penugasan tim audit secara diskriminatif dengan hanya menempatkan pegawai dari satu suku daerah tertentu di posisi basah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan wujud nyata toleransi dan saling menghormati keberagaman latar belakang keagamaan yang memperkokoh persaudaraan dinas.</li><li><strong>C</strong>: Merupakan bukti sikap suka menolong dan empati kemanusiaan yang luhur dalam meringankan duka rekan sejawat yang tertimpa musibah.</li><li><strong>D</strong>: Merupakan cerminan keramahan inklusif dalam menyambut anggota keluarga baru korps dinas agar cepat beradaptasi di lingkungan baru.</li><li><strong>E</strong>: Merupakan manifestasi penciptaan lingkungan kerja kondusif dan dialogis yang menjunjung martabat kebebasan berpendapat ilmiah.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Aplikasi", "question": "Nilai 'Loyal' mewajibkan aparatur memegang teguh ideologi Pancasila, UUD 1945, setia pada NKRI dan pemerintahan sah, menjaga nama baik ASN, pimpinan, instansi, dan negara, serta menjaga rahasia jabatan dan negara. Seorang staf perbendaharaan diajak oleh sekelompok orang untuk bergabung dalam organisasi kemasyarakatan terlarang yang bertujuan mengganti Pancasila dengan ideologi lain. Sikap yang paling mencerminkan nilai Loyal adalah...", "options": ["Bergabung secara aktif dalam organisasi terlarang tersebut dan menyumbangkan sebagian uang kas kantor perbendaharaan setiap bulannya.", "Menyetujui ajakan tersebut dengan syarat dirinya ditunjuk sebagai bendahara umum pengelola dana pemberontakan organisasi terlarang.", "Mendiamkan ajakan tersebut dan memasang lambang organisasi terlarang tersebut di layar komputer dinas lobi kantor perbendaharaan.", "Menolak secara tegas ajakan tersebut, setia pada Pancasila dan NKRI, serta melaporkan gerakan terlarang tersebut kepada aparat berwenang.", "Mengajak seluruh rekan kerja satu seksi kantor perbendaharaan untuk bersama-sama menghadiri rapat rahasia makar organisasi terlarang."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Loyal** menuntut **kesetiaan mutlak kepada Pancasila, UUD 1945, dan Negara Kesatuan Republik Indonesia** (**loyalty to the constitution**). Menolak organisasi terlarang dan melaporkannya merupakan kewajiban konstitusional setiap abdi negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah tindakan yang paling berani, patriotik, dan memenuhi sumpah setia aparatur sipil negara kepada bangsa dan negara. Secara hukum tata negara dan undang-undang kepegawaian (Undang-Undang ASN), keterlibatan aparatur dalam organisasi anti-Pancasila atau gerakan makar merupakan pelanggaran berat terhadap sumpah jabatan yang berakibat pada sanksi pemberhentian tidak dengan hormat (pemecatan) dan tuntutan pidana makar. Sikap tegas menolak dan melaporkan indikasi gerakan separatis membuktikan keteguhan loyalitas ideologis aparatur sebagai perekat dan pemersatu bangsa. Oleh karena itu, menolak tegas dan melapor kepada aparat berwenang merupakan perwujudan sejati nilai Loyal.</p><p>Jawaban yang sesuai adalah <strong>D. Menolak secara tegas ajakan tersebut, setia pada Pancasila dan NKRI, serta melaporkan gerakan terlarang tersebut kepada aparat berwenang.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena bergabung dengan organisasi makar dan menyalurkan uang dinas merupakan tindak pidana makar dan korupsi pengkhianatan negara.</li><li><strong>B</strong>: Salah karena bersedia menjadi bendahara gerakan makar merupakan tindak pidana terorisme pemberontakan yang diancam hukuman mati.</li><li><strong>C</strong>: Salah karena memajang simbol organisasi terlarang di komputer dinas mencerminkan pembangkangan ideologis yang melanggar hukum negara.</li><li><strong>E</strong>: Salah karena memprovokasi rekan dinas untuk rapat makar merupakan permufakatan jahat pengkhianatan kedaulatan tanah air Indonesia.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Aplikasi", "question": "Nilai 'Adaptif' mewajibkan aparatur cepat menyesuaikan diri menghadapi perubahan, terus berinovasi dan mengembangkan kreativitas, serta bertindak proaktif. Ketika terjadi perubahan regulasi penganggaran yang mengharuskan penggunaan sistem klasifikasi belanja baru dalam waktu satu pekan, sikap yang paling mencerminkan nilai Adaptif dari seorang staf perencana anggaran adalah...", "options": ["Menolak menyusun anggaran dan melakukan aksi mogok kerja massal hingga kementerian keuangan mengembalikan aturan penganggaran lama.", "Mengisi berkas usulan anggaran dengan angka sembarangan tanpa membaca regulasi klasifikasi baru demi mengejar batas tenggat waktu.", "Mempelajari regulasi baru secara cepat, berkonsultasi secara proaktif dengan unit pembina teknis, dan menyesuaikan usulan anggaran dinas.", "Menyalahkan pimpinan pusat kementerian di media sosial pribadi atas ketidakmampuan dirinya memahami perubahan nomenklatur belanja.", "Menyerahkan penyusunan usulan anggaran kepada pihak swasta dengan memungut biaya dari kas operasional rumah tangga kantor wilayah."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Panduan perilaku **Adaptif** menuntut **kelincahan belajar** (**learning agility**), sikap **proaktif menghadapi perubahan regulasi**, serta kegigihan berinovasi demi memastikan kesinambungan fungsi penganggaran negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah cerminan implementasi nilai Adaptif yang paling tangguh, profesional, dan berorientasi solusi kerja. Secara teori kelincahan organisasi (organizational agility), aparatur di era transformasi dituntut memiliki ketahanan mental dan kecepatan adaptasi tinggi saat regulasi kebijakan mengalami pembaruan, di mana mempelajari regulasi baru dan berkoordinasi proaktif dengan unit pembina teknis memastikan akurasi alokasi belanja negara tetap terjaga tanpa terputus. Fakta penerapan berbagai pembaruan aplikasi perbendaharaan membuktikan bahwa aparatur yang adaptif sukses menyelesaikan penyesuaian DIPA tepat waktu. Oleh sebab itu, belajar cepat dan berkoordinasi proaktif merupakan wujud nyata nilai Adaptif.</p><p>Jawaban yang sesuai adalah <strong>C. Mempelajari regulasi baru secara cepat, berkonsultasi secara proaktif dengan unit pembina teknis, dan menyesuaikan usulan anggaran dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mogok kerja merupakan tindakan indisipliner berat aparatur sipil negara yang melumpuhkan pelayanan publik keuangan negara.</li><li><strong>B</strong>: Salah karena mengisi angka belanja secara serampangan melanggar prinsip kehati-hatian akuntabilitas dan merusak perencanaan anggaran.</li><li><strong>D</strong>: Salah karena mencaci maki pimpinan di media sosial melanggar kode etik kesopanan ASN dan mencerminkan keengganan beradaptasi positif.</li><li><strong>E</strong>: Kurang tepat karena penyusunan perencanaan anggaran negara adalah tugas kedinasan mandiri yang tidak boleh dilempar ke pihak luar.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Analitis", "question": "Nilai 'Kolaboratif' menuntut aparatur untuk memberi kesempatan kepada berbagai pihak untuk berkontribusi, terbuka dalam bekerja sama untuk menghasilkan nilai tambah, serta menggerakkan pemanfaatan berbagai sumber daya untuk tujuan bersama. Dalam penanganan penyelundupan satwa langka yang dilindungi di bandara internasional, wujud penerapan nilai Kolaboratif yang paling tepat oleh petugas bea dan cukai adalah...", "options": ["Bekerja sama secara terbuka dengan balai karantina, kepolisian, dan BKSDA dalam proses identifikasi satwa, penindakan, dan pelepasliaran.", "Menyita satwa langka tersebut untuk dipelihara secara pribadi di rumah kediaman pejabat kepala kantor pengawasan kepabeanan daerah.", "Menjual satwa langka sitaan tersebut kepada pasar gelap satwa liar luar negeri guna menambah kas penerimaan negara bukan pajak ilegal.", "Menolak berbicara dengan petugas balai konservasi sumber daya alam karena merasa wewenang kepabeanan lebih tinggi dibanding instansi lain.", "Membiarkan penyelundup satwa langka lolos dari pemeriksaan bandara dengan imbalan imbalan uang pelicin sebesar sepuluh juta rupiah."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Panduan perilaku **Kolaboratif** menuntut **sinergi terpadu antar-instansi** (**whole-of-government approach**), di mana keterbukaan bekerja sama dengan aparat kepolisian, karantina, dan BKSDA menghasilkan nilai tambah perlindungan keanekaragaman hayati bangsa.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D menyajikan analisis penerapan kolaborasi antar-lembaga penegak hukum yang paling tepat, profesional, dan selaras dengan mandat nilai Kolaboratif. Secara tata kelola perbatasan (integrated border management), penegakan hukum kepabeanan atas kejahatan satwa langka membutuhkan keahlian biologi dari karantina dan BKSDA serta wewenang penyidikan dari kepolisian, sehingga kerja sama terbuka lintas sektor berhasil menyelamatkan satwa langka dari kepunahan sekaligus menindak jaringan penyelundup internasional secara tuntas. Rekam jejak operasi penindakan bersama di bandara membuktikan bahwa kolaborasi solid antarinstitusi menghasilkan tingkat keberhasilan penegakan hukum yang luar biasa tinggi. Oleh karena itu, sinergi terpadu bea cukai dengan BKSDA dan kepolisian mencerminkan hakikat nilai Kolaboratif.</p><p>Jawaban yang sesuai adalah <strong>A. Bekerja sama secara terbuka dengan balai karantina, kepolisian, dan BKSDA dalam proses identifikasi satwa, penindakan, dan pelepasliaran.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena memelihara satwa langka sitaan secara pribadi merupakan tindak pidana penggelapan barang sitaan negara dan kejahatan satwa.</li><li><strong>C</strong>: Salah karena menjual satwa sitaan ke pasar gelap merupakan kejahatan luar biasa perdagangan satwa liar yang melanggar konvensi internasional.</li><li><strong>D</strong>: Salah karena sikap arogansi sektoral menolak kerja sama menghambat penegakan hukum terpadu dan melanggar nilai Kolaboratif.</li><li><strong>E</strong>: Salah karena menerima uang suap dan meloloskan penyelundup merupakan tindak pidana korupsi penyuapan dan pengkhianatan kedaulatan negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Analitis", "question": "Nilai Akuntabel dan Loyal menjadi pilar penting integritas aparatur sipil negara. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai keterkaitan fungsional antara nilai Akuntabel dan Loyal dalam praktik birokrasi pemerintahan?", "options": ["Akuntabilitas menuntut aparatur mempertanggungjawabkan setiap rupiah penggunaan anggaran belanja negara kepada publik secara sah.", "Loyalitas aparatur bermakna kesetiaan luhur kepada konstitusi dan cita-cita proklamasi kemerdekaan Republik Indonesia yang berdaulat.", "Akuntabilitas melarang keras penyalahgunaan wewenang jabatan untuk memperkaya diri sendiri, keluarga, atau kelompok kroni tertentu.", "Loyalitas mengharuskan aparatur untuk menutupi tindak pidana korupsi yang dilakukan oleh pimpinan kantor demi menjaga nama baik korps dinas.", "Akuntabilitas mengharuskan aparatur mengelola kekayaan barang milik negara secara efektif, efisien, dan bebas dari pemborosan dinas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Loyalitas sejati aparatur adalah **kesetiaan kepada negara, hukum, dan kebenaran**, bukan kepatuhan buta yang menutupi kejahatan korupsi pimpinan (**misplaced loyalty**). Menutupi korupsi adalah **tindak pidana perintangan penyidikan** (**obstruction of justice**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah simpulan yang salah, sesat, dan merupakan bentuk pemikiran keliru yang kerap disalahgunakan oleh oknum korup di birokrasi. Secara hukum pidana dan doktrin etika aparatur sipil negara, kesetiaan kepada negara dan sumpah jabatan berdiri jauh lebih tinggi daripada kesetiaan semu kepada figur individu atasan, sehingga menutupi kejahatan korupsi pimpinan dengan dalih menjaga nama baik korps adalah permufakatan jahat perintangan penyidikan (obstruction of justice) yang diancam pidana penjara. Sikap loyalitas yang benar justru menuntut pengungkapan kebenaran dan pelaporan korupsi demi menyelamatkan martabat sejati institusi negara dari kehancuran moral. Oleh karena itu, menutupi korupsi pimpinan jelas merupakan kekeliruan fatal yang bertolak belakang dengan nilai Loyal.</p><p>Jawaban yang sesuai adalah <strong>D. Loyalitas mengharuskan aparatur untuk menutupi tindak pidana korupsi yang dilakukan oleh pimpinan kantor demi menjaga nama baik korps dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena akuntabilitas publik memang menuntut pertanggungjawaban yuridis atas setiap rupiah dana APBN.</li><li><strong>B</strong>: Merupakan pernyataan yang benar karena loyalitas ASN pada hakikatnya bertumpu pada kesetiaan konstitusional kepada Pancasila dan UUD 1945.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena larangan penyalahgunaan wewenang (abuse of power) adalah pilar mutlak nilai Akuntabel.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena pengelolaan BMN yang efisien dan bertanggung jawab merupakan butir panduan perilaku Akuntabel.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Evaluatif", "question": "Sebuah kantor wilayah instansi fiskal menggabungkan tim pemeriksa pajak dan tim intelijen kepabeanan dalam program 'Joint Audit Penerimaan' guna membongkar modus penyelundupan barang mewah sekaligus penggelapan pajak penghasilan korporasi. Kedua tim awalnya saling curiga mengenai pembagian kredit poin prestasi kerja. Langkah manajerial pimpinan wilayah yang paling tepat untuk mewujudkan nilai Harmonis dan Kolaboratif adalah...", "options": ["Membatalkan seluruh program joint audit dan membiarkan para pengemplang pajak bebas dari pemeriksaan aparat penegak hukum dinas.", "Memberikan seluruh angka kredit poin prestasi kerja hanya kepada tim pajak dan mencoret nama seluruh anggota tim kepabeanan kantor.", "Memerintahkan kedua tim untuk saling bertarung secara fisik di lapangan kantor guna menentukan siapa kelompok yang paling berhak atas poin.", "Memotong gaji seluruh anggota kedua tim hingga mereka bersedia bekerja sama tanpa menanyakan kejelasan penilaian prestasi kerja dinas.", "Menetapkan aturan pembagian angka kredit berkeadilan, menyelaraskan target kinerja bersama, dan membangun ruang kerja kolaboratif."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Mewujudkan sinergi **Harmonis dan Kolaboratif** menuntut kepemimpinan yang adil dalam **menyelaraskan sasaran kinerja bersama** (**shared goals**) serta **menetapkan sistem pengakuan dan penghargaan yang berkeadilan** (*equitable recognition*).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D memberikan solusi evaluatif yang paling adil, konstruktif, dan berorientasi penguatan kolaborasi antar-disiplin ilmu fiskal. Secara teori manajemen kinerja kolaboratif, kecurigaan dan resistensi kerja sama antarunit kerja selalu bersumber dari ketidakjelasan sistem pengakuan prestasi (credit sharing), sehingga penetapan formula pembagian angka kredit yang proporsional dan transparan terbukti berhasil meleburkan ego sektoral menjadi komitmen sinergi pembongkaran kejahatan pajak multinasional. Fakta pelaksanaan Joint Program di Kementerian Keuangan membuktikan bahwa audit terpadu pajak-bea cukai sukses memulihkan penerimaan negara hingga puluhan triliun rupiah secara gemilang. Maka dari itu, penetapan aturan kredit berkeadilan dan target bersama merupakan langkah manajerial terbaik.</p><p>Jawaban yang sesuai adalah <strong>E. Menetapkan aturan pembagian angka kredit berkeadilan, menyelaraskan target kinerja bersama, dan membangun ruang kerja kolaboratif.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membatalkan audit terpadu merupakan tindakan menyerah yang merugikan keuangan negara dan membiarkan mafia hukum berjaya.</li><li><strong>B</strong>: Salah karena memberikan kredit poin sepihak kepada satu pihak merupakan ketidakadilan terang-terangan yang merusak nilai Harmonis.</li><li><strong>C</strong>: Salah karena pertarungan fisik merupakan tindakan anarki barbar yang melanggar etika birokrasi dan mencoreng martabat aparatur.</li><li><strong>D</strong>: Salah karena memotong gaji aparatur secara sepihak melanggar regulasi hak keuangan kepegawaian dan memicu demotivasi kerja parah.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 17", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan keseluruhan panduan perilaku BerAKHLAK (Berorientasi Pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, dan Kolaboratif), sebuah unit kerja perbendaharaan bertekad menyusun 'Pakta Aksi Transformasi ASN'. Rancangan program integratif yang paling tepat mencakup seluruh dimensi nilai BerAKHLAK tersebut adalah...", "options": ["Menyelenggarakan upacara apel bendera setiap dua jam sekali dan memotong tunjangan bagi pegawai yang tidak mampu menahan haus dan lapar.", "Mengintegrasikan pelayanan prima ramah, pengelolaan BMN akuntabel, pembelajaran berkelanjutan, toleransi keragaman, dan sinergi digital.", "Mewajibkan pegawai menandatangani kesepakatan untuk bekerja selama dua puluh empat jam penuh setiap hari tanpa pernah pulang ke rumah.", "Menghapuskan seluruh sistem komputer digital dan kembali menggunakan mesin tik manual kuno demi membuktikan kepatuhan nilai tradisi.", "Mewajibkan setiap pegawai menyetor uang kas rahasia kepada kepala kantor guna membiayai acara jamuan makan malam pejabat eselon pusat."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 17", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 17</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sintesis penerapan BerAKHLAK terpadu mengintegrasikan **tujuh pilar nilai**: **pelayanan prima** (*Berorientasi Pelayanan*), **tata kelola BMN bertanggung jawab** (*Akuntabel*), **pengembangan kapasitas diri** (*Kompeten*), **toleransi keragaman** (*Harmonis*), **kesetiaan negara** (*Loyal*), **kelincahan adaptasi** (*Adaptif*), dan **sinergi kemitraan** (*Kolaboratif*).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B menyajikan rancangan transformasi budaya yang paling komprehensif, seimbang, dan mencakup seluruh spektrum panduan perilaku BerAKHLAK secara harmonis. Secara teori manajemen modern, keunggulan birokrasi tidak dapat dicapai secara parsial, melainkan menuntut integrasi antara keramahan pelayanan loket, kebersihan pertanggungjawaban aset negara, tradisi saling belajar antargenerasi, kerukunan dalam kebinekaan, kesetiaan pada konstitusi, serta pemanfaatan sinergi teknologi digital guna menghasilkan dampak kemanfaatan nyata bagi rakyat. Implementasi terpadu di unit-unit percontohan zona integritas nasional membuktikan bahwa ekosistem BerAKHLAK terpadu berhasil melahirkan aparatur yang unggul dan tepercaya. Oleh sebab itu, formulasi opsi B merupakan rancangan aksi terbaik penutup sub-paket ini.</p><p>Jawaban yang sesuai adalah <strong>B. Mengintegrasikan pelayanan prima ramah, pengelolaan BMN akuntabel, pembelajaran berkelanjutan, toleransi keragaman, dan sinergi digital.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena apel fisik berlebihan yang menyiksa raga aparatur melanggar asas kemanusiaan dan merusak produktivitas pelayanan publik.</li><li><strong>C</strong>: Salah karena melarang pegawai pulang ke rumah melanggar hak asasi perlindungan keluarga dan memicu kehancuran kesehatan mental aparatur.</li><li><strong>D</strong>: Salah karena kembali ke mesin tik manual merupakan kemunduran peradaban birokrasi yang melanggar nilai inovasi dan efisiensi teknologi.</li><li><strong>E</strong>: Salah karena menyetor uang rahasia untuk jamuan pejabat merupakan tindak pidana korupsi pungutan liar dan gratifikasi terlarang.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 17.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Analitis", "question": "Presiden Republik Indonesia meresmikan employer branding bagi Aparatur Sipil Negara (ASN) dengan semboyan 'Bangga Melayani Bangsa'. Makna filosofis dan psikologis paling mendalam dari semboyan 'Bangga Melayani Bangsa' bagi transformasi mentalitas birokrasi Indonesia adalah...", "options": ["Mendorong aparatur untuk memamerkan tanda pangkat kepegawaiannya di pusat perbelanjaan agar ditakuti oleh para pedagang pasar.", "Mewajibkan aparatur menuntut perlakuan istimewa dan fasilitas ruang tunggu khusus VVIP di seluruh stasiun kereta api dan bandara.", "Menjadikan kebanggaan aparatur bertumpu pada besarnya jumlah uang gratifikasi tidak resmi yang berhasil dikumpulkan setiap bulan.", "Menggeser paradigma priyayi yang minta dilayani menjadi aparatur berjiwa pelayan publik yang tulus dan bangga mengabdi demi rakyat.", "Memberikan hak imunitas hukum mutlak kepada aparatur negara dari segala tuntutan hukum perdata maupun tindak pidana korupsi dinas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Employer branding **Bangga Melayani Bangsa** menegaskan **pergeseran paradigma mentalitas aparatur** (**mindset shift**): membuang mental priyayi zaman kolonial yang minta dilayani dan menggantikannya dengan rasa bangga tulus melayani kepentingan masyarakat dan negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merangkum esensi amanat Presiden Joko Widodo dalam peluncuran employer branding ASN secara paling tepat dan fundamental. Secara historis dan sosiologi birokrasi, birokrasi Indonesia mewarisi feodalisme kolonial (ambtenaar) yang kerap memposisikan pejabat publik sebagai penguasa yang minta dihormati dan dilayani rakyat, sehingga semboyan 'Bangga Melayani Bangsa' diluncurkan untuk membalik mentalitas tersebut menjadi kebanggaan melayani (servant leadership) di mana kehormatan aparatur diukur dari kemampuannya memberikan kemaslahatan bagi masyarakat. Bukti survei budaya kerja nasional memperlihatkan bahwa internalisasi semboyan ini berhasil menurunkan arogansi birokrasi di loket pelayanan. Oleh sebab itu, pergeseran paradigma priyayi menjadi pelayan rakyat merupakan makna sejati employer branding ASN.</p><p>Jawaban yang sesuai adalah <strong>D. Menggeser paradigma priyayi yang minta dilayani menjadi aparatur berjiwa pelayan publik yang tulus dan bangga mengabdi demi rakyat.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena memamerkan pangkat dinas demi menakut-nakuti warga mencerminkan arogansi feodal yang mencoreng martabat ASN.</li><li><strong>B</strong>: Salah karena menuntut perlakuan istimewa bertentangan secara diametral dengan semangat kesahajaan dan jiwa melayani rakyat.</li><li><strong>C</strong>: Salah karena mengumpulkan uang gratifikasi merupakan tindak pidana korupsi penyuapan yang merusak nama baik bangsa dan negara.</li><li><strong>E</strong>: Salah karena aparatur sipil negara tunduk pada asas kesetaraan di hadapan hukum dan tidak memiliki kekebalan pidana korupsi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Analitis", "question": "Dalam peluncuran Core Values ASN, Presiden menegaskan bahwa ASN bukan lagi pejabat zaman kolonial yang minta dilayani melainkan abdi negara yang melayani. Implikasi operasional dari pesan Presiden tersebut pada pelayanan di kantor pengawasan kepabeanan adalah...", "options": ["Pejabat kepabeanan mewajibkan pengusaha importir membungkuk sembilan puluh derajat setiap kali memasuki ruangan dinas kantor.", "Petugas kepabeanan bersikap profesional, santun, transparan, dan memfasilitasi kelancaran arus barang tanpa meminta imbalan apa pun.", "Aparatur memperlambat pemeriksaan kontainer pelabuhan berhari-hari hingga importir datang mengantarkan bingkisan makanan mewah.", "Pimpinan kantor memungut uang tiket masuk bagi masyarakat yang hendak berkonsultasi mengenai prosedur kepabeanan di lobi kantor.", "Petugas pos pemeriksaan perbatasan menolak memeriksa paspor warga yang melintas dengan alasan sedang asyik bermain gim ponsel."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Amanat Presiden menuntut aparatur kepabeanan untuk **meninggalkan budaya feodal kolonial** dan bertindak sebagai **fasilitator perdagangan yang profesional, ramah, dan bebas dari pungutan liar** (**trade facilitator and industrial promoter**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah perwujudan konkret yang paling tepat dari pesan Presiden mengenai pemberantasan mentalitas priyayi kolonial. Secara tugas pokok dan fungsi kepabeanan modern, aparatur bertindak sebagai pelindung industri dan fasilitator perdagangan (trade facilitator) yang berkewajiban melayani pelaku usaha secara adil, transparan, dan cepat guna menurunkan biaya logistik nasional, tanpa mengharapkan perlakuan sembah atau pemberian cinderamata gelap. Fakta reformasi kepabeanan nasional membuktikan bahwa pelayanan profesional tanpa pungli berhasil mendongkrak indeks kemudahan berusaha (Ease of Doing Business) Indonesia di tingkat dunia. Oleh karena itu, pelayanan profesional tanpa pamrih merupakan wujud nyata pesan Presiden.</p><p>Jawaban yang sesuai adalah <strong>B. Petugas kepabeanan bersikap profesional, santun, transparan, dan memfasilitasi kelancaran arus barang tanpa meminta imbalan apa pun.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mewajibkan sujud membungkuk merupakan bentuk perbudakan feodal yang merendahkan martabat masyarakat pelaku usaha.</li><li><strong>C</strong>: Salah karena sengaja memperlambat kontainer demi bingkisan merupakan tindak pidana korupsi pemerasan dalam proses kepabeanan.</li><li><strong>D</strong>: Salah karena memungut tiket masuk konsultasi merupakan pungutan liar ilegal yang melanggar undang-undang pelayanan publik.</li><li><strong>E</strong>: Salah karena bermain gim saat jam dinas merupakan kelalaian tugas penjaga perbatasan yang membahayakan kedaulatan negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Aplikasi", "question": "Penyatuan nilai dasar ke dalam BerAKHLAK menegaskan bahwa ASN di mana pun bertugas—baik kementerian, lembaga, maupun pemerintah daerah—memiliki standar etika yang seragam. Di antara perilaku aparatur berikut, manakah tindakan yang BUKAN merupakan cerminan dari keseragaman nilai BerAKHLAK tersebut?", "options": ["Aparatur pemerintah daerah melayani pengurusan KTP secara gratis dan ramah sesuai standar pelayanan publik nasional.", "Petugas kantor pajak di ibu kota melayani konsultasi pengisian formulir dengan penuh integritas tanpa membedakan status sosial.", "Aparat perbendaharaan daerah memproses pencairan dana desa secara tepat waktu demi percepatan pembangunan infrastruktur desa.", "Petugas karantina perbatasan melakukan pengujian komoditas pangan secara cermat guna mencegah masuknya wabah penyakit hewan.", "Pejabat dinas daerah menolak melayani warga yang berasal dari luar daerahnya dengan alasan peraturan daerah hanya untuk warganya."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Keseragaman Core Values BerAKHLAK menuntut **pelayanan berkeadilan tanpa sekat kedaerahan** (**universal public service**). Menolak melayani warga luar daerah merupakan **tindakan diskriminatif parokial** yang merusak persatuan nasional.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah skenario diskriminasi birokrasi yang melanggar prinsip keseragaman nilai BerAKHLAK dan amanat konstitusi negara. Secara hukum kewarganegaraan, setiap warga negara Indonesia berhak mendapatkan pelayanan publik di seluruh wilayah Negara Kesatuan Republik Indonesia tanpa boleh dihambat oleh sekat primordial kedaerahan sempit, sehingga menolak melayani warga luar daerah bertentangan dengan fungsi ASN sebagai perekat dan pemersatu bangsa. Keputusan Menteri Dalam Negeri dan MenPANRB menegaskan bahwa pelayanan administrasi kependudukan nasional terintegrasi secara daring melintasi batas domisili. Maka dari itu, penolakan berbasis domisili daerah jelas bertolak belakang dengan keseragaman nilai BerAKHLAK.</p><p>Jawaban yang sesuai adalah <strong>E. Pejabat dinas daerah menolak melayani warga yang berasal dari luar daerahnya dengan alasan peraturan daerah hanya untuk warganya.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan wujud penerapan nilai Berorientasi Pelayanan di tingkat pemerintah daerah yang selaras dengan standar mutu nasional.</li><li><strong>B</strong>: Merupakan penerapan nilai Akuntabel dan Pelayanan prima yang adil di lingkungan instansi perpajakan kementerian pusat.</li><li><strong>C</strong>: Merupakan pengamalan nilai Akuntabel dan Kolaboratif dalam mendukung kelancaran pemanfaatan dana desa untuk rakyat banyak.</li><li><strong>D</strong>: Merupakan cerminan nilai Kompeten dan Profesionalisme aparat pengawas perbatasan dalam melindungi ketahanan hayati bangsa.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf muda lulusan politeknik keuangan negara ditempatkan di sebuah pulau terluar perbatasan yang minim fasilitas hiburan dan sinyal komunikasi. Sikap yang paling mencerminkan penghayatan semboyan 'Bangga Melayani Bangsa' dari staf muda tersebut adalah...", "options": ["Menjalankan tugas pengawasan kepabeanan dengan dedikasi penuh dan bersyukur dapat mengawal kedaulatan fiskal di garda terdepan.", "Meninggalkan pos tugas tanpa izin pimpinan kantor wilayah dan bersembunyi di rumah orang tua di kota besar sepanjang tahun dinas.", "Mengajukan gugatan hukum perdata kepada presiden republik indonesia karena merasa hak liburan mewahnya telah dilanggar dinas.", "Menjual perlengkapan seragam dinas operasional pos perbatasan kepada nelayan asing guna membeli tiket pesawat pulang kampung.", "Melakukan mogok makan di halaman pos pengawasan dinas hingga kepala kantor pusat memindahkan dirinya kembali ke ibu kota negara."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Semangat **Bangga Melayani Bangsa** mewujud dalam **patriotisme pengabdian di garis depan** (**frontline dedication**), di mana penugasan di daerah terpencil disikapi sebagai kehormatan mulia dalam mengawal batas kedaulatan penerimaan negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah cerminan sikap mentalitas aparatur yang paling membanggakan, tangguh, dan selaras dengan sumpah setia abdi negara. Secara etika profesi kepegawaian, penempatan di pulau perbatasan terluar merupakan kepercayaan negara yang sangat strategis untuk mengamankan wilayah maritim nusantara dari penyelundupan komoditas ilegal dan narkotika, sehingga rasa bangga mengabdi di garda terdepan mengalahkan segala keterbatasan fasilitas fisik. Teladan ribuan aparatur perbatasan Kementerian Keuangan membuktikan bahwa dedikasi tulus di pulau terpencil berhasil menjaga keutuhan fiskal bangsa. Oleh sebab itu, menjalankan tugas dengan dedikasi penuh merupakan wujud nyata Bangga Melayani Bangsa.</p><p>Jawaban yang sesuai adalah <strong>A. Menjalankan tugas pengawasan kepabeanan dengan dedikasi penuh dan bersyukur dapat mengawal kedaulatan fiskal di garda terdepan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena desersi meninggalkan pos perbatasan merupakan pelanggaran disiplin berat yang berujung pada sanksi pemecatan dinas.</li><li><strong>C</strong>: Salah karena penempatan wilayah dinas merupakan wewenang sah negara yang telah disepakati saat menandatangani kontrak ikatan dinas.</li><li><strong>D</strong>: Salah karena menjual aset perlengkapan dinas kepada pihak asing merupakan tindak pidana penggelapan dan pengkhianatan kedaulatan.</li><li><strong>E</strong>: Salah karena mogok makan untuk memaksakan mutasi mencerminkan ketidakmatangan mentalitas aparatur yang merusak kehormatan korps.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat eselon di instansi keuangan daerah selalu menuntut agar ajudannya membukakan pintu mobil dinas, membawakan tas kerja pribadi, dan memesankan meja khusus di restoran mewah setiap kali melakukan kunjungan kerja. Evaluasi yang paling tepat terhadap perilaku pejabat tersebut mengacu pada arahan Presiden Joko Widodo adalah...", "options": ["Perilaku yang sangat pantas dan wajib ditiru oleh seluruh pejabat eselon lain demi menjaga martabat dan keagungan korps dinas.", "Tindakan yang tepat karena seorang pejabat pemerintah daerah memang memiliki kasta sosial yang jauh lebih tinggi dibanding staf ajudan.", "Perilaku feodal usang yang bertentangan dengan semangat ASN modern yang seharusnya rendah hati dan berfokus melayani publik.", "Langkah yang luar biasa brilian karena ajudan memang direkrut khusus oleh negara untuk menjadi pelayan pribadi keluarga pejabat.", "Kebijakan yang patut diapresiasi karena pembukaan pintu mobil terbukti mampu meningkatkan penerimaan pajak daerah secara drastis."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Arahan Presiden secara tegas **menolak mentalitas pejabat feodal zaman kolonial** yang gemar minta dilayani. Pejabat ASN modern dituntut memiliki **kepemimpinan yang melayani** (**servant leadership**), bersahaja, dan menghormati martabat staf.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C memberikan evaluasi kritis yang paling tajam, tepat, dan berakar pada pesan moral peluncuran Core Values ASN. Secara teori kepemimpinan modern, arogansi birokrasi yang menuntut perlakuan bak raja kolonial merupakan residu feodalisme masa lalu yang merusak kultur egaliter dan menghambat komunikasi kerja tim yang produktif, di mana pejabat seharusnya menjadi teladan kerendahan hati dan kepedulian terhadap bawahan. Berbagai pedoman reformasi birokrasi kementerian secara eksplisit melarang pemborosan fasilitas ajudan untuk urusan domestik pribadi pejabat. Oleh karenanya, perilaku pejabat tersebut jelas merupakan kebiasaan feodal usang yang bertentangan dengan nilai ASN.</p><p>Jawaban yang sesuai adalah <strong>C. Perilaku feodal usang yang bertentangan dengan semangat ASN modern yang seharusnya rendah hati dan berfokus melayani publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena memamerkan kemewahan dan feodalisme justru meruntuhkan kehormatan korps birokrasi di hadapan masyarakat publik.</li><li><strong>B</strong>: Salah karena negara demokrasi Pancasila tidak mengenal kasta sosial dan menjunjung asas kesetaraan martabat seluruh warga negara.</li><li><strong>D</strong>: Salah karena staf pendamping kedinasan dibiayai negara untuk membantu tugas substantif dinas, bukan menjadi pelayan pribadi.</li><li><strong>E</strong>: Salah karena pembukaan pintu mobil tidak memiliki korelasi logis maupun empiris terhadap efektivitas penerimaan pajak daerah.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan amanat peluncuran employer branding 'Bangga Melayani Bangsa' dan pemberantasan mentalitas birokrasi kolonial, rancangan kebijakan tata kelola kantor pelayanan yang paling efektif untuk membumikan budaya kesetaraan dan pelayanan prima adalah...", "options": ["Membangun tangga eskalator khusus berlapis karpet sutra yang hanya boleh dilewati oleh kepala kantor dan pejabat eselon kementerian.", "Mewajibkan seluruh pegawai menyumbangkan sepuluh persen gaji pokoknya setiap bulan untuk membelikan hadiah ulang tahun istri pimpinan.", "Mengharuskan masyarakat pemohon layanan berlutut di lantai loket saat menyampaikan dokumen permohonan surat keterangan dinas kantor.", "Menghapuskan seluruh jam kerja dinas kantor dan membiarkan para pegawai masuk kerja kapan pun sesuai dengan suasana hati pribadi.", "Menerapkan open office space, meniadakan sekat feodal hierarkis, mengutamakan dialog egaliter, dan menyederhanakan alur birokrasi."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Membasmi feodalisme birokrasi menuntut **desain tata ruang dan tata kelola egaliter**: penerapan **ruang kerja terbuka** (**open office space**), perataan komunikasi dialogis, penghapusan sekat feodal, dan debirokratisasi proses pelayanan publik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E menyajikan sintesis kebijakan transformasi kelembagaan yang paling modern, teruji, dan berorientasi efisiensi birokrasi. Secara psikologi arsitektur dan manajemen perubahan, sekat-sekat ruangan tertutup yang mewah bagi pejabat melanggengkan jurang feodalisme dan menghambat kolaborasi cepat dengan staf pelaksana, sehingga adopsi tata ruang kerja terbuka (open workspace) yang membaurkan pimpinan dan tim kerja berhasil memotong birokrasi serta mempercepat penyelesaian urusan publik secara transparan. Fakta modernisasi gedung kantor Kementerian Keuangan membuktikan bahwa open office space sukses menciptakan iklim kerja egaliter yang lincah dan bebas feodal. Oleh karenanya, formulasi opsi E merupakan kebijakan terbaik.</p><p>Jawaban yang sesuai adalah <strong>E. Menerapkan open office space, meniadakan sekat feodal hierarkis, mengutamakan dialog egaliter, dan menyederhanakan alur birokrasi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membangun eskalator karpet sutra eksklusif pejabat mencerminkan kemewahan feodal yang melukai hati nurani rakyat.</li><li><strong>B</strong>: Salah karena memungut potongan gaji demi hadiah keluarga pejabat merupakan pemerasan terorganisasi yang melanggar hukum kepegawaian.</li><li><strong>C</strong>: Salah karena mewajibkan masyarakat berlutut merupakan penghinaan keji terhadap martabat kemanusiaan warga negara pembayar pajak.</li><li><strong>D</strong>: Salah karena menghapus jam kerja dinas melahirkan anarki birokrasi yang melumpuhkan pelayanan publik dan melanggar hukum dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Aplikasi", "question": "Seorang wajib pajak yang sudah lanjut usia dan kebingungan membawa berkas dokumen pajak yang tidak tersusun rapi ke loket pelayanan. Mengacu pada jiwa 'Bangga Melayani Bangsa', sikap yang wajib ditunjukkan oleh petugas loket adalah...", "options": ["Melemparkan berkas dokumen tersebut ke lantai dan menyuruh wajib pajak lansia tersebut keluar dari gedung kantor pelayanan dinas.", "Membimbing wajib pajak lansia dengan sabar, membantu menyortir dokumen, menjelaskan prosedur dengan santun, dan menyelesaikan urusan.", "Meminta uang tip khusus sebesar dua ratus ribu rupiah kepada warga lansia tersebut sebagai upah jasa menyusun berkas kertas dinas.", "Membiarkan warga lansia tersebut menunggu di kursi antrean selama berjam-jam sementara petugas loket asyik mengobrol santai di kantin.", "Menyuruh petugas keamanan kantor untuk menginterogasi warga lansia tersebut atas tuduhan membuat kekacauan administrasi dinas kantor."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Jiwa **Bangga Melayani Bangsa** mewajibkan **kesabaran, kesantunan, dan kepedulian tulus** (**compassionate service**) kepada warga lanjut usia, membantu merapikan dokumen, dan menuntaskan urusan perpajakannya tanpa pamrih pungli.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah tindakan yang paling mulia, humanis, dan mencerminkan esensi hakiki aparatur sebagai pelayan publik yang berhati nurani. Secara etika kemanusiaan dan standar pelayanan kementerian keuangan, warga lansia yang memiliki keterbatasan pemahaman administrasi berhak mendapatkan bantuan pendampingan khusus (affirmative assistance) dari petugas loket, di mana kesabaran membantu menata dokumen dan menjelaskan alur secara santun menjadi bukti nyata bahwa negara hadir melayani dan memuliakan warganya. Data survei kepuasan kementerian membuktikan bahwa ketulusan melayani kelompok rentan menumbuhkan rasa cinta dan kepatuhan sukarela masyarakat terhadap instansi pemerintah. Oleh sebab itu, mendampingi dengan sabar dan santun merupakan wujud sejati Bangga Melayani Bangsa.</p><p>Jawaban yang sesuai adalah <strong>B. Membimbing wajib pajak lansia dengan sabar, membantu menyortir dokumen, menjelaskan prosedur dengan santun, dan menyelesaikan urusan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena melemparkan berkas dan mengusir warga lansia merupakan kebiadaban moral yang melanggar undang-undang pelayanan publik.</li><li><strong>C</strong>: Salah karena meminta uang jasa penataan berkas merupakan tindak pidana korupsi pungutan liar dan pemerasan terhadap orang tua.</li><li><strong>D</strong>: Salah karena menelantarkan pemohon demi mengobrol di kantin merupakan kelalaian tugas indisipliner berat yang sangat memalukan.</li><li><strong>E</strong>: Salah karena menginterogasi warga lansia yang kebingungan mencerminkan kezaliman birokrasi paranoia yang mencoreng martabat korps.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Analitis", "question": "Employer branding 'Bangga Melayani Bangsa' dirancang sebagai identitas kebanggaan bagi seluruh korps ASN. Di antara simpulan-simpulan berikut, manakah pernyataan yang KELIRU mengenai hakikat dan tujuan implementasi employer branding ASN tersebut?", "options": ["Employer branding ASN bertujuan meningkatkan daya tarik profesi aparatur sipil negara di mata talenta terbaik putra-putri bangsa.", "Employer branding ASN menanamkan kebanggaan pada profesi pelayan publik yang bermartabat dan memiliki dampak sosial luas.", "Employer branding ASN menyatukan orientasi budaya kerja aparatur dari berbagai kementerian dan daerah ke dalam satu visi pelayanan.", "Employer branding ASN berarti aparatur negara memiliki hak istimewa untuk kebal dari segala bentuk sanksi hukum pidana di pengadilan.", "Employer branding ASN memperkuat komitmen etika aparatur untuk memberikan kinerja terbaik dalam mengawal kedaulatan negara."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Employer branding **Bangga Melayani Bangsa** adalah instrumen penguatan **daya tarik talenta, kebanggaan profesi, dan komitmen pelayanan publik**, serta **sama sekali tidak memberikan kekebalan hukum pidana** bagi aparatur negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah simpulan yang salah, menyesatkan, dan bertentangan secara mutlak dengan prinsip negara hukum (rechtsstaat). Secara yuridis konstitusional, konsep employer branding ASN diciptakan untuk merekrut generasi unggul bangsa dan mengobarkan semangat pengabdian aparatur, bukan untuk menciptakan kasta warga negara kelas satu yang kebal dari jeratan hukum peradilan pidana, di mana aparatur yang melanggar hukum tetap diproses secara adil di hadapan hakim pengadilan. Asas equality before the law dalam Pasal 27 UUD 1945 menegaskan bahwa seluruh warga negara—termasuk aparatur sipil negara—memiliki kedudukan hukum yang setara. Oleh karena itu, menyatakan bahwa employer branding memberikan kekebalan pidana adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>D. Employer branding ASN berarti aparatur negara memiliki hak istimewa untuk kebal dari segala bentuk sanksi hukum pidana di pengadilan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena employer branding memang berfungsi sebagai strategi talent attraction bagi generasi muda unggul.</li><li><strong>B</strong>: Merupakan pernyataan yang benar karena kebanggaan melayani bangsa menumbuhkan harga diri (self-esteem) positif pada profesi ASN.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena penyatuan semboyan nasional sukses mengikis sekat fragmentasi antar-instansi pemerintah.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena semboyan tersebut menjadi pengingat konstan atas komitmen pengabdian kepada tanah air.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Evaluatif", "question": "Seorang kepala kantor pelayanan perpajakan secara rutin meluangkan waktu satu jam setiap hari Jumat untuk duduk di meja loket garis depan melayani langsung permohonan masyarakat bersama petugas loket lainnya. Penilaian yang paling tepat terhadap tindakan kepala kantor tersebut mengacu pada semboyan 'Bangga Melayani Bangsa' adalah...", "options": ["Tindakan keteladanan yang sangat luar biasa karena pimpinan menunjukkan secara nyata kerendahan hati dan jiwa melayani di garis depan.", "Tindakan yang membuang waktu dinas karena seorang kepala kantor eselon seharusnya hanya bertugas menandatangani surat keputusan mutasi.", "Keputusan yang keliru karena pimpinan kantor pelayanan dapat tertular penyakit dari masyarakat umum yang mengantre di loket dinas.", "Langkah yang merendahkan martabat jabatan karena pimpinan setara kepala kantor tidak pantas berbicara langsung dengan wajib pajak kecil.", "Kebijakan yang melanggar hukum perbendaharaan negara karena pelayanan loket dinas hanya boleh dilakukan oleh tenaga pegawai honorer."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Keteladanan pimpinan (**leading by example**) yang terjun langsung melayani di loket publik membuktikan penghayatan sejati **Bangga Melayani Bangsa**, mengikis arogansi struktural, serta memberikan suntikan moral yang dahsyat bagi staf garis depan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A memberikan penilaian evaluatif yang paling tepat, membanggakan, dan berlandaskan teori kepemimpinan transformasional modern. Secara manajemen pelayanan prima, ketika seorang pimpinan puncak bersedia turun langsung melayani di loket, ia tidak hanya mendengar langsung aspirasi dan kesulitan rakyat pembayar pajak, melainkan juga mengirimkan pesan simbolik yang sangat kuat kepada seluruh bawahannya bahwa melayani masyarakat adalah tugas yang paling mulia dan terhormat di kementerian keuangan. Rekam jejak para pemimpin reformis kementerian membuktikan bahwa teladan turun ke loket sukses mengubah kultur kantor menjadi ramah dan responsif. Oleh sebab itu, inisiatif kepala kantor tersebut merupakan keteladanan kepemimpinan yang sangat luar biasa.</p><p>Jawaban yang sesuai adalah <strong>A. Tindakan keteladanan yang sangat luar biasa karena pimpinan menunjukkan secara nyata kerendahan hati dan jiwa melayani di garis depan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena peran kepemimpinan modern menuntut pemahaman operasional riil di lapangan, bukan sekadar menandatangani kertas administratif.</li><li><strong>C</strong>: Salah karena memandang masyarakat sebagai sumber penyakit mencerminkan arogansi narsistik yang bertentangan dengan kemanusiaan.</li><li><strong>D</strong>: Salah karena melayani seluruh lapisan wajib pajak—termasuk pelaku usaha kecil—merupakan kehormatan tertinggi abdi negara Republik Indonesia.</li><li><strong>E</strong>: Salah karena pelayanan loket publik adalah wewenang resmi pejabat fungsional dan pelaksana aparatur sipil negara yang sah.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 18", "difficulty": "HOTS • Kreasi", "question": "Dalam mendidik calon pegawai negeri sipil (CPNS) baru agar memiliki karakter yang selaras dengan semboyan 'Bangga Melayani Bangsa' dan terbebas dari mental priyayi kolonial, rancangan kurikulum orientasi lapangan yang paling efektif adalah...", "options": ["Melatih CPNS tata cara meminta dihormati oleh masyarakat dan memberikan wewenang untuk menilang kendaraan bermotor di jalan umum.", "Mewajibkan CPNS menghafalkan silsilah keluarga pejabat pimpinan tinggi kementerian keuangan sejak era kemerdekaan hingga saat ini.", "Menerjunkan CPNS dalam program pendampingan sosial masyarakat desa terpencil dipadukan dengan praktik pelayanan langsung di loket publik.", "Mengunci seluruh CPNS di dalam ruang kelas tertutup selama tiga bulan tanpa diizinkan melihat dunia luar atau berkomunikasi dengan warga.", "Mengajari CPNS strategi melobi atasan agar cepat dinaikkan pangkatnya tanpa perlu menunjukkan kinerja nyata dalam pelayanan dinas."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 18", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 18</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Pendidikan karakter abdi negara yang unggul menuntut **pembelajaran pengalaman nyata** (**experiential learning**): menerjunkan calon aparatur dalam **pendampingan masyarakat akar rumput** dan **praktik pelayanan publik garis depan** guna mengasah empati kemanusiaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C menyajikan sintesis kurikulum pendidikan karakter aparatur yang paling progresif, humanis, dan berdaya ubah tinggi. Secara pedagogi andragogi, empati dan jiwa melayani tidak dapat dihafalkan dari lembaran modul teori di ruang kelas, melainkan harus ditumbuhkan melalui perjumpaan langsung dengan realitas denyut kehidupan masyarakat kecil di desa dan pengalaman nyata melayani warga di loket dinas kantor, sehingga calon aparatur memahami secara mendalam untuk siapa mereka mengabdi. Bukti program orientasi kepemimpinan muda kementerian membuktikan bahwa paparan sosial lapangan sukses membentuk aparatur yang rendah hati dan berdedikasi tinggi. Oleh karenanya, perpaduan pendampingan warga dan praktik loket merupakan formula kurikulum terbaik.</p><p>Jawaban yang sesuai adalah <strong>C. Menerjunkan CPNS dalam program pendampingan sosial masyarakat desa terpencil dipadukan dengan praktik pelayanan langsung di loket publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mengajari cara meminta dihormati merupakan pengembangbiakan mentalitas feodal kolonial yang merusak karakter aparatur.</li><li><strong>B</strong>: Salah karena menghafal silsilah keluarga pejabat merupakan tradisi neoklonialisme yang bertentangan dengan prinsip meritokrasi dinas.</li><li><strong>D</strong>: Salah karena mengisolasi CPNS dari masyarakat mematikan kepekaan sosial dan melahirkan aparatur yang terasing dari realitas bangsanya.</li><li><strong>E</strong>: Salah karena mengajarkan teknik melobi atasan merupakan internalisasi budaya penjilat korup yang merusak tatanan kepegawaian profesional.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 18.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Analitis", "question": "Dalam matriks penyelarasan nilai, nilai Integritas pada Kementerian Keuangan berkorespondensi langsung dengan nilai Akuntabel dan Loyal pada Core Values ASN BerAKHLAK. Hubungan substansial paling mendasar yang menjelaskan mengapa Integritas memayungi dimensi Akuntabel dan Loyal sekaligus adalah...", "options": ["Karena pegawai yang berintegritas memiliki wewenang untuk mencairkan anggaran kas negara tanpa perlu menyertakan kuitansi belanja sah.", "Integritas menuntut pertanggungjawaban jujur atas amanah publik (Akuntabel) sekaligus kesetiaan mutlak pada konstitusi negara (Loyal).", "Karena nilai Akuntabel dan Loyal hanya berlaku bagi staf honorer sementara Integritas merupakan monopoli hak para pejabat eselon satu.", "Integritas membebaskan aparatur dari kewajiban mematuhi kode etik dinas apabila sedang menjalankan tugas luar dinas kementerian.", "Karena kementerian keuangan menolak seluruh nilai BerAKHLAK dan menggantikannya secara sepihak dengan peraturan menteri keuangan."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Integritas** Kementerian Keuangan berkorespondensi dengan **Akuntabel** (kejujuran dan kehati-hatian mengelola anggaran publik) serta **Loyal** (kesetiaan pada Pancasila, konstitusi, dan penjagaan martabat negara).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah analisis komparasi filosofis yang paling tepat mengenai matriks penyelarasan nilai ASN dan nilai kementerian. Secara konseptual, integritas dalam domain pengelolaan keuangan negara mencakup dua sisi mata uang: pertanggungjawaban yang jujur, cermat, dan transparan atas setiap rupiah uang rakyat (esensi Akuntabel) serta kesetiaan teguh membela kepentingan bangsa di atas kepentingan pribadi dan rahasia jabatan negara (esensi Loyal). Laporan kinerja reformasi kementerian membuktikan bahwa aparatur yang berintegritas tinggi secara konsisten mampu mewujudkan akuntabilitas perbendaharaan sekaligus kesetiaan ideologis yang kokoh. Oleh sebab itu, perpaduan tanggung jawab publik dan kesetiaan konstitusi menjelaskan pemetaan tersebut secara sempurna.</p><p>Jawaban yang sesuai adalah <strong>B. Integritas menuntut pertanggungjawaban jujur atas amanah publik (Akuntabel) sekaligus kesetiaan mutlak pada konstitusi negara (Loyal).</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena nilai integritas justru mewajibkan kelengkapan kuitansi pengeluaran yang sah dan menolak pencairan kas tanpa bukti.</li><li><strong>C</strong>: Salah karena seluruh nilai berlaku setara bagi seluruh jajaran aparatur tanpa memandang tingkatan eselon jabatan kepegawaian.</li><li><strong>D</strong>: Salah karena kode etik dinas melekat pada diri aparatur di mana pun berada, baik di dalam kantor maupun saat penugasan luar dinas.</li><li><strong>E</strong>: Salah karena Kementerian Keuangan menyelaraskan dan memperkuat BerAKHLAK secara harmonis dalam arsitektur budaya kerjanya.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Analitis", "question": "Matriks penyelarasan menempatkan nilai Profesionalisme Kementerian Keuangan berkorespondensi dengan nilai Kompeten pada Core Values BerAKHLAK. Mengapa penguasaan kompetensi terbaik menjadi fondasi mutlak bagi terwujudnya profesionalisme pengelolaan fiskal negara?", "options": ["Karena kompetensi teknis memungkinkan aparatur merekayasa pembukuan laporan pajak agar terlihat seimbang secara otomatis di sistem.", "Karena seorang profesional berhak menolak melayani masyarakat yang tidak mampu berbahasa asing saat berkonsultasi di loket dinas.", "Karena kompetensi memberikan hak bagi pejabat untuk memungut honorarium tambahan dari setiap berkas perizinan yang ditandatanganinya.", "Karena gelar kompetensi formal menghapuskan kewajiban aparatur untuk mematuhi jam kerja dinas dan aturan absensi elektronik kantor.", "Pengelolaan keuangan dan kekayaan negara yang rumit menuntut keahlian analitis presisi tinggi guna menjamin akurasi kebijakan publik."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Profesionalisme** berkorespondensi dengan **Kompeten**, di mana amanah mengelola anggaran, utang negara, bea cukai, dan perpajakan menuntut **keahlian terbaik dan kecermatan analitis tingkat tinggi** (**technical and analytical mastery**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E menyajikan analisis kebutuhan teknokratis yang paling valid mengenai korelasi Profesionalisme dan Kompeten. Secara ilmu ekonomi publik, kekeliruan perhitungan makroekonomi atau salah penetapan regulasi fiskal akibat ketidakmampuan kompetensi aparatur dapat memicu krisis likuiditas kas negara, pembengkakan utang, dan kekacauan moneter yang menyengsarakan ratusan juta rakyat, sehingga kompetensi teknis terbaik merupakan harga mati yang menopang profesionalitas birokrasi perbendaharaan. Pengakuan lembaga pemeringkat internasional atas kredibilitas fiskal Indonesia membuktikan bahwa profesionalisme berbasis kompetensi unggul sukses menjaga stabilitas ekonomi nasional. Maka dari itu, tuntutan keahlian analitis presisi tinggi menjadi fondasi mutlak profesionalisme.</p><p>Jawaban yang sesuai adalah <strong>E. Pengelolaan keuangan dan kekayaan negara yang rumit menuntut keahlian analitis presisi tinggi guna menjamin akurasi kebijakan publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena merekayasa pembukuan merupakan kejahatan pemalsuan laporan keuangan negara yang bertentangan dengan profesionalisme.</li><li><strong>B</strong>: Salah karena pelayanan publik wajib menggunakan bahasa nasional yang dipahami rakyat dan tidak boleh mendiskriminasi warga negara.</li><li><strong>C</strong>: Salah karena memungut honorarium tambahan dari penandatanganan izin dinas merupakan tindak pidana korupsi pemerasan dalam jabatan.</li><li><strong>D</strong>: Salah karena kepemilikan kompetensi keahlian tidak membebaskan pegawai dari kewajiban mematuhi jam kerja dinas resmi kementerian.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Aplikasi", "question": "Nilai Sinergi pada Kementerian Keuangan berkorespondensi dengan nilai Harmonis dan Kolaboratif pada BerAKHLAK. Wujud nyata penerapan nilai Sinergi yang memadukan keharmonisan internal dan kolaborasi eksternal dalam pengamanan penerimaan perpajakan adalah...", "options": ["Membangun hubungan kerja sama solid dengan aparat kepolisian dan kejaksaan dalam pertukaran data penegakan hukum tindak pidana pajak.", "Menolak berbagi informasi perpajakan dengan aparat penegak hukum lain dengan dalih menjaga kerahasiaan kekayaan pejabat kantor.", "Membiarkan penagihan pajak macet pada korporasi besar asalkan pemilik perusahaan bersedia membiayai acara rekreasi tahunan staf.", "Menyerahkan seluruh wewenang pemeriksaan pajak kepada asosiasi pengusaha swasta guna menghindari konflik sengketa penetapan pajak.", "Melakukan penyerbuan fisik sepihak ke kantor kejaksaan negeri saat terjadi silang pendapat mengenai interpretasi pasal hukum pidana."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Sinergi** memadukan **Harmonis** (hubungan kerja yang saling menghargai) dan **Kolaboratif** (keterbukaan bekerja sama menghasilkan nilai tambah), seperti **kerja sama pertukaran data perpajakan dengan aparat penegak hukum** (**integrated law enforcement**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah contoh penerapan sinergi antar-lembaga penegak hukum yang paling tepat, berintegritas, dan berkekuatan hukum sah. Secara tata kelola penegakan hukum fiskal, membongkar kejahatan perpajakan yang terorganisasi dan tindak pidana pencucian uang membutuhkan kerja sama erat (kolaboratif) dan saling percaya (harmonis) antara Direktorat Jenderal Pajak, Kepolisian RI, dan Kejaksaan Agung dalam pertukaran data intelijen keuangan secara aman dan cepat. Keberhasilan penindakan kasus pengemplangan pajak bernilai miliaran rupiah membuktikan bahwa sinergi penegakan hukum terpadu berhasil memulihkan kerugian pendapatan negara secara gemilang. Oleh sebab itu, kerja sama solid pertukaran data merupakan perwujudan sejati nilai Sinergi.</p><p>Jawaban yang sesuai adalah <strong>A. Membangun hubungan kerja sama solid dengan aparat kepolisian dan kejaksaan dalam pertukaran data penegakan hukum tindak pidana pajak.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena menolak berbagi data dengan aparat hukum sah melanggar undang-undang pencegahan tindak pidana pencucian uang.</li><li><strong>C</strong>: Salah karena membiarkan penunggak pajak demi biaya liburan merupakan tindak pidana korupsi kolusi penyuapan yang merugikan negara.</li><li><strong>D</strong>: Salah karena penegakan hukum pajak adalah kewenangan berdaulat negara yang dilarang dialihkan kepada entitas asosiasi bisnis swasta.</li><li><strong>E</strong>: Salah karena penyerbuan fisik antarinstitusi negara merupakan tindakan anarki kriminal yang mencoreng martabat aparatur sipil negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Analitis", "question": "Nilai Kesempurnaan pada Kementerian Keuangan berkorespondensi dengan nilai Adaptif pada BerAKHLAK. Di antara tindakan-tindakan berikut, manakah perilaku yang BUKAN merupakan cerminan dari penyelarasan nilai Kesempurnaan dan Adaptif dalam operasional kantor?", "options": ["Melakukan evaluasi berkala terhadap kelemahan aplikasi pelayanan dan segera merilis pembaruan fitur guna memudahkan masyarakat.", "Mempelajari praktik terbaik manajemen perbendaharaan negara maju dan mengadopsinya sesuai karakteristik hukum perbendaharaan Indonesia.", "Mendorong staf untuk menciptakan inovasi otomasi pelaporan yang memangkas waktu kerja rutin bulanan secara teruji dan akuntabel.", "Menolak mengubah prosedur manual loket yang berbelit-belit dengan alasan bahwa cara lama telah digunakan sejak tiga puluh tahun lalu.", "Merespons dinamika disrupsi ekonomi digital dengan menyusun regulasi pemungutan pajak perdagangan elektronik yang berkeadilan."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Kesempurnaan** menuntut upaya perbaikan tiada henti, sedangkan **Adaptif** menuntut kelincahan menyesuaikan diri terhadap perubahan zaman. Mempertahankan prosedur usang (**resisting change/status quo trap**) bertentangan dengan kedua nilai tersebut.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah cerminan sikap jumud (status quo bias) yang bertolak belakang secara mutlak dengan penyelarasan nilai Kesempurnaan dan Adaptif. Secara teori manajemen mutu dan kelincahan birokrasi, mempertahankan cara kerja manual yang lambat dan usang hanya karena alasan tradisi masa lalu mencerminkan keengganan berbenah diri yang mematikan inovasi dan merugikan kecepatan pelayanan masyarakat pembayar pajak di era modern. Kajian reformasi birokrasi membuktikan bahwa unit kerja yang terjebak pada romantisme masa lalu tergilas oleh tuntutan publik atas kecepatan layanan digital. Maka dari itu, menolak perbaikan prosedur manual jelas bukan cerminan nilai Kesempurnaan dan Adaptif.</p><p>Jawaban yang sesuai adalah <strong>D. Menolak mengubah prosedur manual loket yang berbelit-belit dengan alasan bahwa cara lama telah digunakan sejak tiga puluh tahun lalu.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan wujud nyata komitmen continuous improvement yang adaptif dalam menyempurnakan keandalan sarana digital publik.</li><li><strong>B</strong>: Merupakan penerapan benchmarking cerdas yang adaptif dalam menyempurnakan standar pengelolaan perbendaharaan negara.</li><li><strong>C</strong>: Merupakan cerminan kreativitas dan inovasi yang selaras dengan panduan perilaku adaptif dan dorongan menuju kesempurnaan.</li><li><strong>E</strong>: Merupakan manifestasi responsivitas kebijakan fiskal yang lincah (agile policy) dalam mengimbangi evolusi ekonomi digital.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Evaluatif", "question": "Sebuah kementerian teknis fiskal mengintegrasikan Core Values BerAKHLAK ke dalam budaya kerjanya tanpa menghapuskan 5 Nilai Kementerian Keuangan, melainkan menyandingkannya secara harmonis dalam matriks nilai. Penilaian yang paling tepat terhadap strategi harmonisasi nilai tersebut adalah...", "options": ["Keputusan yang keliru karena kementerian seharusnya tunduk pada peraturan nasional dan membubarkan seluruh nilai lama dinas kantor.", "Tindakan yang membuang waktu dinas karena aparatur pemerintah tidak mampu menghafal dua tatanan nilai secara bersamaan di kantor.", "Keputusan yang sangat tepat karena mengontekstualisasikan payung etika nasional ASN ke dalam kekhasan amanah pengelolaan fiskal negara.", "Langkah yang melanggar hukum tata negara karena menteri keuangan tidak memiliki wewenang mengatur etika aparatur di lingkungannya.", "Kebijakan yang tidak efektif karena penyandingan matriks nilai hanya akan memicu kebingungan moral bagi para staf pelaksana loket."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Harmonisasi nilai melalui matriks penyelarasan adalah **langkah strategis yang tepat** (**contextual alignment**), karena BerAKHLAK berfungsi sebagai **standar payung etik nasional**, sementara 5 Nilai Kemenkeu **mengoperasionalisasikan amanah spesifik pengelolaan keuangan negara**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C memberikan evaluasi yang paling tepat, harmonis, dan berbasis hukum administrasi negara. Surat Edaran Menteri PANRB No. 20 Tahun 2021 secara tegas memperbolehkan kementerian/lembaga mempertahankan kekhasan nilai instansinya sepanjang selaras dan memetakan diri ke dalam payung Core Values BerAKHLAK, sehingga Kementerian Keuangan mampu menjaga warisan tradisi integritas pengawal fiskal sekaligus menyatu dalam korps nasional ASN. Rekam jejak pembinaan budaya kementerian membuktikan bahwa matriks penyelarasan justru memperkaya pemahaman aparatur dan mempertegas komitmen etika pelayanan publik. Oleh karenanya, kontekstualisasi payung etika nasional ke dalam tugas fiskal merupakan keputusan manajerial yang sangat brilian.</p><p>Jawaban yang sesuai adalah <strong>C. Keputusan yang sangat tepat karena mengontekstualisasikan payung etika nasional ASN ke dalam kekhasan amanah pengelolaan fiskal negara.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena SE MenPANRB tidak mewajibkan penghapusan nilai instansi melainkan penyelarasan harmonis ke dalam payung BerAKHLAK.</li><li><strong>B</strong>: Salah karena aparatur fiskal memiliki tingkat intelektualitas tinggi untuk memahami keselarasan filosofis kedua tatanan nilai dinas.</li><li><strong>D</strong>: Salah karena menteri keuangan memikul kewenangan regulatif sah selaku pembina kepegawaian internal di lingkungan kementeriannya.</li><li><strong>E</strong>: Salah karena matriks pemetaan justru menjernihkan panduan perilaku operasional dan menghilangkan potensi keraguan tafsir etika.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Aplikasi", "question": "Nilai Pelayanan pada Kementerian Keuangan berkorespondensi dengan nilai Berorientasi Pelayanan pada BerAKHLAK. Dalam penanganan restitusi kelebihan pembayaran pajak penghasilan wajib pajak orang pribadi, tindakan yang paling mencerminkan keselarasan kedua nilai tersebut adalah...", "options": ["Memproses verifikasi restitusi secara transparan, tepat waktu, akurat, dan mengembalikan hak kelebihan pajak warga tanpa biaya apa pun.", "Memotong dana restitusi wajib pajak sebesar dua puluh persen sebagai kompensasi biaya lembur dinas para pegawai seksi pemeriksaan.", "Menunda penerbitan surat perintah pembayaran kelebihan pajak hingga wajib pajak bersedia memberikan parcel elektronik ke rumah pejabat.", "Mengharuskan wajib pajak mentraktir makan malam seluruh pegawai seksi pemeriksaan di restoran mewah sebelum berkas ditandatangani.", "Menolak berkas permohonan restitusi secara lisan tanpa memberikan surat penolakan resmi agar wajib pajak tidak dapat mengajukan gugatan."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Pelayanan** Kemenkeu dan **Berorientasi Pelayanan** BerAKHLAK menuntut pelayanan yang **memenuhi kepuasan pemangku kepentingan secara transparan, cepat, akurat, aman**, serta **mengembalikan hak keuangan warga negara tanpa potongan ilegal**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah tindakan yang paling profesional, bermoral, dan memenuhi regulasi perpajakan yang sah. Secara hukum hak wajib pajak (taxpayers' rights), kelebihan pembayaran pajak adalah hak milik sah warga negara yang wajib dikembalikan oleh negara secara utuh dan tepat waktu sesuai ketentuan undang-undang tanpa boleh dipotong biaya atau dipersulit dengan dalih apa pun. Keberhasilan digitalisasi proses restitusi dipercepat di Direktorat Jenderal Pajak membuktikan bahwa pelayanan pengembalian dana yang transparan berhasil meningkatkan kepuasan dan kepatuhan sukarela masyarakat. Oleh sebab itu, memproses restitusi secara transparan, cepat, dan tanpa biaya mencerminkan perwujudan sejati nilai Pelayanan.</p><p>Jawaban yang sesuai adalah <strong>A. Memproses verifikasi restitusi secara transparan, tepat waktu, akurat, dan mengembalikan hak kelebihan pajak warga tanpa biaya apa pun.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena memotong dana hak restitusi warga merupakan tindak pidana korupsi pemerasan dalam jabatan dan pemotongan uang negara.</li><li><strong>C</strong>: Salah karena menahan hak uang restitusi demi parcel merupakan tindak pidana korupsi suap dan gratifikasi ilegal yang melanggar hukum.</li><li><strong>D</strong>: Salah karena meminta jamuan makan malam merupakan pelanggaran kode etik integritas dan pemerasan terselubung terhadap wajib pajak.</li><li><strong>E</strong>: Salah karena menolak tanpa surat resmi merupakan tindakan kesewenang-wenangan maladministrasi yang melanggar kepastian hukum warga.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Kreasi", "question": "Sebuah kantor wilayah kementerian keuangan berniat menyusun program kampanye nilai 'Harmoni Nilai Negarawan Fiskal' untuk menginternalisasikan matriks penyelarasan BerAKHLAK dan 5 Nilai Kemenkeu kepada seluruh aparatur. Rancangan kampanye edukasi yang paling terpadu dan menyentuh kesadaran praktis adalah...", "options": ["Mewajibkan pegawai berdiri membaca teks matriks nilai di bawah guyuran hujan lebat guna melatih ketahanan fisik mental aparatur.", "Menempelkan draf matriks nilai di langit-langit atap gedung kantor yang tidak dapat terbaca oleh mata manusia biasa dari lantai.", "Memotong tunjangan kinerja pegawai yang tidak mampu menghafal urutan kata-kata singkatan BerAKHLAK dalam waktu lima detik dinas.", "Menyajikan video studi kasus dilema etika riil, membedah keterkaitan kedua nilai dalam simulasi kerja, dan mengapresiasi teladan nyata.", "Mewajibkan seluruh staf menyalin naskah matriks nilai menggunakan tulisan tangan sebanyak seribu lembar kertas folio bergaris."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kampanye edukasi nilai terpadu yang efektif memadukan **media studi kasus dilema riil** (**case-based ethical training**), **simulasi pemecahan masalah operasional**, serta **apresiasi keteladanan nyata aparatur di lapangan**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D menyajikan sintesis metodologi edukasi budaya kerja yang paling modern, interaktif, dan berdampak mendalam bagi kesadaran moral aparatur. Secara andragogi, pemahaman hubungan nilai abstrak tidak akan tertanam melalui hukuman fisik atau hafalan mekanistik, melainkan melalui pembedahan kasus-kasus nyata di mana aparatur diajak menimbang bagaimana nilai Integritas/Akuntabel dan Nilai Pelayanan beroperasi saat menghadapi godaan uang suap atau komplain warga di loket dinas. Keberhasilan program internalisasi di kementerian membuktikan bahwa pembelajaran berbasis video studi kasus sukses mendongkrak pemahaman etika aparatur hingga di atas 95%. Oleh karenanya, video studi kasus dan apresiasi teladan merupakan rancangan kampanye terbaik.</p><p>Jawaban yang sesuai adalah <strong>D. Menyajikan video studi kasus dilema etika riil, membedah keterkaitan kedua nilai dalam simulasi kerja, dan mengapresiasi teladan nyata.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menjemur pegawai di bawah hujan lebat merupakan perpeloncoan fisik primitif yang melanggar hak asasi aparatur dinas.</li><li><strong>B</strong>: Salah karena menempelkan teks di langit-langit yang tak terbaca merupakan kesia-siaan media komunikasi yang membuang anggaran kantor.</li><li><strong>C</strong>: Salah karena hukuman pemotongan uang atas hafalan cepat melahirkan ketakutan kaku yang tidak menyentuh kesadaran nurani etika.</li><li><strong>E</strong>: Salah karena hukuman menyalin seribu lembar folio merupakan metode penghukuman usang anak sekolah yang merendahkan martabat ASN.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Analitis", "question": "Penyelarasan nilai Sinergi Kementerian Keuangan dengan nilai Harmonis dan Kolaboratif pada BerAKHLAK menuntut kerja sama produktif. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai hakikat Sinergi dan Kolaboratif di sektor publik?", "options": ["Sinergi menuntut aparatur meruntuhkan ego sektoral demi mencapai target penerimaan dan pengelolaan kekayaan negara bersama.", "Kolaboratif mengharuskan kementerian keuangan menyetujui seluruh permintaan pembebasan pajak dari korporasi tanpa pengujian hukum.", "Sinergi mengutamakan komunikasi yang terbuka, saling percaya, dan saling menghargai antarseksi di lingkungan kantor kementerian.", "Kolaboratif membuka ruang bagi pemangku kepentingan eksternal untuk memberikan kontribusi konstruktif bagi perbaikan layanan.", "Sinergi mendorong pemanfaatan bersama sumber daya teknologi informasi antarunit eselon satu demi efisiensi anggaran belanja negara."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Kolaboratif** menuntut kerja sama produktif dalam batas **kepentingan umum dan supremasi hukum** (**public interest and legal framework**). Menyetujui pembebasan pajak korporasi tanpa dasar hukum bukan kolaborasi, melainkan **tindak pidana korupsi persekongkolan jahat**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merupakan simpulan yang salah, menyesatkan, dan menjadi kedok bagi kejahatan kolusi pengorbanan pendapatan negara. Secara hukum fiskal dan tindak pidana korupsi, pemberian fasilitas pembebasan pajak (tax incentive/holiday) wajib memenuhi persyaratan kriteria hukum ketat yang diatur dalam undang-undang, di mana meloloskan permohonan korporasi tanpa dasar hukum yang sah merupakan tindak pidana korupsi permufakatan jahat yang merugikan keuangan kas negara. Fakta persidangan tipikor menegaskan bahwa pejabat yang bersekongkol membebaskan pajak perusahaan secara sepihak selalu dijatuhi vonis pidana penjara. Oleh sebab itu, menyatakan bahwa kolaboratif berarti menyetujui seluruh pembebasan pajak tanpa aturan adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>B. Kolaboratif mengharuskan kementerian keuangan menyetujui seluruh permintaan pembebasan pajak dari korporasi tanpa pengujian hukum.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena meruntuhkan silo ego sektoral merupakan esensi utama bekerjanya nilai Sinergi kelembagaan.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena rasa saling percaya dan keterbukaan komunikasi merupakan fondasi budaya kerja yang harmonis.</li><li><strong>D</strong>: Merupakan pernyataan yang benar karena keterbukaan menerima kontribusi pemangku kepentingan merupakan butir panduan Kolaboratif.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena berbagi sumber daya TI (data sharing) antar-eselon mencerminkan sinergi perbendaharaan modern.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Evaluatif", "question": "Dalam penanganan kapal tanker asing pengangkut minyak mentah ilegal di perairan teritorial, terjadi perselisihan wewenang penindakan antara petugas patroli kepabeanan dengan instansi pengawas maritim lain yang ingin menyita muatan secara terpisah. Sikap evaluatif kepala kantor kepabeanan yang paling mencerminkan integrasi nilai Sinergi dan Kolaboratif BerAKHLAK adalah...", "options": ["Memerintahkan kapal patroli kepabeanan melepaskan tembakan meriam ke arah kapal instansi mitra guna membuktikan supremasi senjata dinas.", "Melepaskan kapal tanker asing tersebut agar berlayar bebas keluar perairan indonesia demi menghindari konflik antar-lembaga negara.", "Menyuruh nahkoda kapal asing menyuap kedua pimpinan instansi penegak hukum secara merata di dalam kamar kapten kapal tanker.", "Membiarkan anak buah kapal tanker membakar muatan minyak mentah di laut agar tidak ada satu pun instansi yang mendapatkan barang bukti.", "Menginisiasi gelar perkara bersama di pangkalan darat terdekat untuk memetakan wewenang yuridis dan melakukan penindakan terpadu."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Penerapan nilai **Sinergi dan Kolaboratif** dalam penegakan hukum maritim menuntut **koordinasi terpadu dan gelar perkara bersama** (**joint case evaluation**), mendahulukan keselamatan kedaulatan negara, dan menyampingkan ego sektoral kelembagaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E menyajikan evaluasi tindakan kepemimpinan yang paling bermartabat, taat hukum, dan menjunjung tinggi keselamatan kedaulatan bangsa. Secara hukum acara pidana maritim, tumpang tindih kewenangan di laut teritorial tidak boleh diselesaikan dengan arogansi kekerasan antar-aparat negara, melainkan melalui koordinasi gelar perkara bersama di pangkalan darat guna membedah yurisdiksi kepabeanan, pelayaran, dan pidana minyak bumi, sehingga proses penyidikan berjalan kokoh di pengadilan dan barang bukti minyak negara terselamatkan. Keberhasilan Satgas Terpadu Maritim membuktikan bahwa operasi gabungan terbukti melumpuhkan jaringan mafia bahan bakar internasional secara tuntas. Oleh karenanya, menginisiasi gelar perkara terpadu mencerminkan keunggulan Sinergi dan Kolaboratif.</p><p>Jawaban yang sesuai adalah <strong>E. Menginisiasi gelar perkara bersama di pangkalan darat terdekat untuk memetakan wewenang yuridis dan melakukan penindakan terpadu.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menembaki sesama aparat penegak hukum negara merupakan tindakan makar kriminal yang sangat memalukan bangsa.</li><li><strong>B</strong>: Salah karena melepaskan pelaku kejahatan minyak mentah merupakan pengkhianatan kedaulatan negara dan pembiaran tindak pidana.</li><li><strong>C</strong>: Salah karena meminta uang suap dari pelaku penyelundupan merupakan tindak pidana korupsi penerimaan suap yang diancam pidana penjara.</li><li><strong>D</strong>: Salah karena membiarkan pembakaran minyak mencemari ekosistem laut maritim dan membahayakan keselamatan pelayaran nasional.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 19", "difficulty": "HOTS • Aplikasi", "question": "Seorang pejabat pengelola utang negara di kementerian keuangan sedang merancang penerbitan Surat Berharga Syariah Negara (Sukuk) ritel untuk membiayai proyek pembangunan jalur kereta api perintis di pulau sumatera. Mengacu pada integrasi nilai Integritas (Akuntabel), Profesionalisme (Kompeten), dan Pelayanan (Berorientasi Pelayanan), langkah yang wajib dieksekusi oleh pejabat tersebut adalah...", "options": ["Menetapkan suku bunga imbal hasil secara fiktif yang merugikan para pembeli sukuk ritel demi memperkaya agen perbankan swasta asing.", "Menerbitkan sukuk tanpa adanya proyek fisik dasar (underlying asset) yang sah dan menyembunyikan laporan keuangan dari audit publik.", "Merancang struktur sukuk secara transparan, berbasis aset riil terverifikasi, memberikan imbalan adil, dan mengawal kemanfaatan proyek.", "Mengalihkan seluruh dana hasil penjualan sukuk pembangunan kereta api untuk membiayai pesta perayaan ulang tahun pejabat kementerian.", "Menjual sukuk negara hanya kepada anggota keluarga pribadi pejabat dengan potongan diskon harga rahasia sebesar lima puluh persen."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 19", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 19</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Pengelolaan pembiayaan negara yang mencerminkan integrasi nilai menuntut **akuntabilitas aset dasar** (*underlying asset* sah), **kompetensi profesional struktur keuangan syariah**, serta **orientasi pelayanan pembangunan infrastruktur nyata** bagi kemaslahatan masyarakat.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah langkah aplikasi integrasi nilai yang paling tepat, profesional, dan memenuhi standar tata kelola pembiayaan syariah negara. Secara regulasi pasar modal syariah dan perbendaharaan negara (Undang-Undang SBSN), penerbitan sukuk negara wajib didasarkan pada underlying asset proyek riil yang diverifikasi secara cermat (Akuntabel/Kompeten), menawarkan instrumen investasi aman bagi masyarakat luas, serta memastikan dana terserap untuk membangun fasilitas publik perintis yang melayani mobilitas rakyat (Pelayanan). Rekam jejak penerbitan Sukuk Negara membuktikan bahwa tata kelola berintegritas tinggi berhasil membiayai ribuan proyek strategis nasional tanpa cela korupsi. Maka dari itu, merancang sukuk secara transparan dan berorientasi manfaat publik merupakan cerminan integrasi nilai penutup sub-paket ini.</p><p>Jawaban yang sesuai adalah <strong>C. Merancang struktur sukuk secara transparan, berbasis aset riil terverifikasi, memberikan imbalan adil, dan mengawal kemanfaatan proyek.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena memanipulasi imbal hasil secara fiktif merupakan penipuan investasi keuangan publik yang merusak kredibilitas negara.</li><li><strong>B</strong>: Salah karena menerbitkan sukuk tanpa underlying asset melanggar prinsip syariah dan undang-undang perbendaharaan negara.</li><li><strong>D</strong>: Salah karena menyelewengkan dana sukuk untuk pesta pribadi merupakan tindak pidana korupsi penyimpangan dana pembiayaan APBN.</li><li><strong>E</strong>: Salah karena menjual sukuk berdiskon khusus kepada keluarga merupakan kejahatan nepotisme dan korupsi pasar modal negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 19.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Analitis", "question": "Berdasarkan tabel Nilai-Nilai Kementerian Keuangan (PMK Nomor 190/PMK.01/2018), nilai Integritas dimaknai sebagai berpikir, berkata, berperilaku, dan bertindak dengan baik dan benar serta memegang teguh kode etik dan prinsip-prinsip moral. Unsur pembeda mendasar yang menuntut keselarasan keempat dimensi (berpikir, berkata, berperilaku, dan bertindak) dalam nilai Integritas tersebut adalah...", "options": ["Agar aparatur diperbolehkan memungut uang tanda terima kasih dari masyarakat asalkan kata-kata penolakannya disampaikan dengan sangat halus.", "Karena seorang aparatur kementerian keuangan berhak memiliki standar ganda dalam mengeksekusi wewenang tugas kedinasan di loket kantor.", "Agar aparatur dapat menyembunyikan niat manipulasi anggaran belanja di dalam alam pikiran batinnya tanpa terdeteksi oleh mesin pemeriksa.", "Karena pemikiran moral aparatur hanya berlaku saat berada di dalam rumah ibadah dan tidak mengikat saat menandatangani berkas dinas.", "Menolak kemunafikan birokrasi sehingga kejujuran nurani batiniah memancar konsisten menjadi ucapan santun dan tindakan nyata di loket."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Integritas** Kementerian Keuangan menuntut **kesatuan utuh tanpa cela** (**wholeness and alignment**): apa yang dipikirkan dalam hati nurani, diucapkan dalam perkataan, dan dilakukan dalam tindakan nyata harus **selaras memegang teguh kode etik dan moral**, menolak segala bentuk kemunafikan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E merangkum makna filosofis definisi Integritas dalam PMK 190/PMK.01/2018 secara paling tepat dan mendalam. Secara etika kepegawaian modern, integritas bukan sekadar kepandaian bertutur kata manis di hadapan atasan atau kepura-puraan di depan kamera pengawas, melainkan kesatuan yang kokoh antara kejernihan niat berpikir batiniah dengan keteguhan menolak suap dalam tindakan operasional di loket pelayanan masyarakat. Riset psikologi organisasi membuktikan bahwa aparatur yang memiliki keselarasan pikir-ucap-tindak memiliki ketahanan etika tertinggi di hadapan godaan gratifikasi liar. Oleh karena itu, penolakan kemunafikan dan konsistensi nurani batiniah menjadi pembeda hakiki dari definisi nilai Integritas.</p><p>Jawaban yang sesuai adalah <strong>E. Menolak kemunafikan birokrasi sehingga kejujuran nurani batiniah memancar konsisten menjadi ucapan santun dan tindakan nyata di loket.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena keselarasan integritas menolak mutlak segala bentuk pungutan uang suap, bukan melegalkan gratifikasi santun.</li><li><strong>B</strong>: Salah karena integritas menolak standar ganda (double standards) dan mewajibkan konsistensi moral yang teguh tanpa kepalsuan.</li><li><strong>C</strong>: Salah karena integritas menuntut kebersihan pikiran batiniah sejak awal dan menolak niat jahat manipulasi kas negara.</li><li><strong>D</strong>: Salah karena nilai integritas mengikat aparatur di segala ruang dan waktu, terutama saat mengeksekusi tanda tangan dokumen keuangan negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Analitis", "question": "Nilai Profesionalisme dalam tabel Nilai Kementerian Keuangan dimaknai sebagai bekerja tuntas dan akurat atas dasar kompetensi terbaik dengan penuh tanggung jawab dan komitmen yang tinggi. Keterkaitan logis antara 'bekerja tuntas' dan 'bekerja akurat' dalam menjaga akuntabilitas keuangan negara adalah...", "options": ["Pekerjaan tuntas berarti menghapus seluruh arsip tagihan perbendaharaan sedangkan akurat berarti membagi kas dinas secara merata.", "Bekerja tuntas hanya dituntut kepada staf pelaksana sedangkan keakuratan data merupakan tanggung jawab mutlak sekretaris jenderal.", "Tuntas menjamin kepastian penyelesaian seluruh tahapan proses tanpa penundaan, sementara akurat menjamin kebenaran angka tanpa celah salah.", "Akurat berarti menyelesaikan berkas tepat jam dua belas malam sedangkan tuntas berarti membiarkan berkas tagihan tanpa ditandatangani.", "Keduanya merupakan jargon administratif formalitas yang tidak memiliki konsekuensi yuridis dalam pemeriksaan auditor BPK RI."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Dalam nilai **Profesionalisme**, **bekerja tuntas** menjamin **kepastian penyelesaian seluruh rantai proses administrasi** (**completeness and closure**), sedangkan **bekerja akurat** menjamin **validitas dan kebenaran materiil angka keuangan** (**precision and accuracy**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah analisis komparasi fungsional yang paling presisi mengenai makna Profesionalisme dalam PMK 190/PMK.01/2018. Secara manajemen keuangan publik, sebuah laporan perbendaharaan tidak ada gunanya jika tuntas diserahkan tepat waktu namun memuat angka yang salah (tidak akurat), dan sebaliknya angka yang sangat akurat tidak akan bermakna jika dokumennya mangkrak dan tidak pernah dituntaskan penyelesaiannya. Perpaduan antara tuntas dan akurat inilah yang mengantarkan Kementerian Keuangan meraih predikat opini Wajar Tanpa Pengecualian (WTP) atas Laporan Keuangan Pemerintah Pusat (LKPP) berturut-turut. Maka dari itu, tuntas tanpa penundaan dan akurat tanpa cela mencerminkan hakikat Profesionalisme sejati.</p><p>Jawaban yang sesuai adalah <strong>C. Tuntas menjamin kepastian penyelesaian seluruh tahapan proses tanpa penundaan, sementara akurat menjamin kebenaran angka tanpa celah salah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menghapus arsip tagihan dan membagi kas gelap merupakan tindak pidana korupsi penggelapan uang perbendaharaan negara.</li><li><strong>B</strong>: Salah karena tuntutan bekerja tuntas dan akurat mengikat seluruh jajaran aparatur tanpa terkecuali pada seluruh tingkatan hierarki.</li><li><strong>D</strong>: Salah karena membiarkan berkas tanpa tanda tangan merupakan bentuk ketidaktuntasan kerja yang melanggar standar operasional dinas.</li><li><strong>E</strong>: Salah karena ketuntasan dan keakuratan adalah standar primer pengujian audit Badan Pemeriksa Keuangan (BPK) atas laporan keuangan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Aplikasi", "question": "Nilai Sinergi dimaknai sebagai membangun dan memastikan hubungan kerja sama internal yang produktif serta kemitraan yang harmonis dengan para pemangku kepentingan. Dalam penanganan restitusi kepabeanan bagi eksportir industri manufaktur nasional, wujud nyata penerapan nilai Sinergi yang tepat adalah...", "options": ["Membangun koordinasi integrasi data antara kantor kepabeanan, perbendaharaan, dan perbankan guna mempercepat pengembalian bea masuk sah.", "Menolak kerja sama dengan pihak perbankan persepsi dinas karena menganggap perbankan sebagai musuh bebuyutan instansi pemerintah.", "Meminta pengusaha industri manufaktur menyetor uang pelicin kemitraan sebesar sepuluh juta rupiah ke rekening kas pribadi pimpinan.", "Memutuskan sambungan internet kantor kepabeanan agar sistem perbendaharaan tidak dapat memantau pergerakan kas restitusi dinas.", "Menyita barang hasil ekspor industri manufaktur tersebut di gudang pelabuhan tanpa adanya bukti pelanggaran kepabeanan yang sah."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Sinergi** mewajibkan aparatur kementerian untuk **membangun kemitraan produktif dan harmonis** (**productive partnership**), memadukan pertukaran data antar-unit dan perbankan persepsi guna mempercepat pelayanan hak keuangan pelaku industri nasional.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah cerminan aplikasi nilai Sinergi yang paling profesional, tepat, dan berdaya guna bagi perekonomian nasional. Secara tata kelola penerimaan negara, percepatan pengembalian bea masuk (drawback) untuk bahan baku ekspor membutuhkan integrasi sistem data antara Direktorat Jenderal Bea Cukai, Direktorat Jenderal Perbendaharaan, dan bank persepsi operasional agar hak likuiditas eksportir cair tepat waktu dan devisa negara meningkat. Fakta implementasi program National Logistic Ecosystem (NLE) membuktikan bahwa sinergi lintas instansi dan perbankan berhasil memangkas waktu pengembalian bea masuk hingga 70%. Oleh sebab itu, koordinasi integrasi data antar-entitas mencerminkan perwujudan sejati nilai Sinergi.</p><p>Jawaban yang sesuai adalah <strong>A. Membangun koordinasi integrasi data antara kantor kepabeanan, perbendaharaan, dan perbankan guna mempercepat pengembalian bea masuk sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena memusuhi perbankan persepsi merupakan tindakan paranoid konyol yang melumpuhkan sistem pembayaran kas negara.</li><li><strong>C</strong>: Salah karena meminta uang pelicin kemitraan merupakan tindak pidana korupsi pemerasan dan gratifikasi ilegal yang melanggar hukum.</li><li><strong>D</strong>: Salah karena menyabotase sambungan internet demi menutup pengawasan merupakan tindak pidana kejahatan siber dan desersi dinas.</li><li><strong>E</strong>: Salah karena menyita barang ekspor tanpa dasar hukum sah melanggar undang-undang kepabeanan dan merugikan dunia usaha nasional.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Analitis", "question": "Nilai Pelayanan dimaknai sebagai memberikan layanan yang memenuhi kepuasan pemangku kepentingan yang dilakukan dengan sepenuh hati, transparan, cepat, akurat, dan aman. Di antara praktik-praktik pelayanan loket berikut, manakah tindakan yang BUKAN merupakan penerapan nilai Pelayanan sesuai definisi resmi PMK 190/PMK.01/2018?", "options": ["Menyediakan jalur percepatan berkas khusus bagi pemohon yang bersedia membayar uang pelicin ekstra kepada kepala seksi pelayanan.", "Menyelesaikan permohonan surat keterangan fiskal dalam batas waktu lima belas menit sesuai janji layanan dinas yang dipublikasikan.", "Menyimpan data identitas pribadi wajib pajak pada peladen pelindung siber yang aman guna mencegah kebocoran data rahasia publik.", "Petugas loket menyapa masyarakat dengan penuh kehangatan hati dan memandu pengisian formulir hingga tuntas tanpa meminta imbalan.", "Menampilkan bagan alur persyaratan permohonan dinas secara terbuka di lobi kantor agar masyarakat mengetahui kepastian biaya nol rupiah."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Pelayanan** menuntut pemberian layanan dengan **sepenuh hati, transparan, cepat, akurat, dan aman** (**wholehearted, transparent, fast, accurate, secure**). Membuka jalur kilat berbayar suap (**fast-track bribery**) merupakan **tindak pidana korupsi yang melanggar nilai Pelayanan**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah skenario praktik pungutan liar dan diskriminasi pelayanan yang bertentangan secara frontal dengan definisi nilai Pelayanan dalam PMK 190/PMK.01/2018. Secara undang-undang pelayanan publik dan kode etik kementerian keuangan, seluruh masyarakat berhak atas kecepatan dan kepastian layanan yang setara tanpa diskriminasi biaya gelap, sehingga menjual jalur cepat demi uang suap pejabat merupakan tindak pidana korupsi gratifikasi yang mencederai prinsip transparansi dan keadilan publik. Laporan pengawasan kepatuhan internal membuktikan bahwa loket jalur khusus berbayar liar langsung ditindak tegas dan oknum pelakunya dipecat dari dinas kepegawaian. Oleh karenanya, menyediakan jalur percepatan berbayar suap jelas bukan nilai Pelayanan melainkan kejahatan birokrasi.</p><p>Jawaban yang sesuai adalah <strong>A. Menyediakan jalur percepatan berkas khusus bagi pemohon yang bersedia membayar uang pelicin ekstra kepada kepala seksi pelayanan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Merupakan wujud nyata prinsip cepat dan akurat dalam menepati janji batas waktu pelayanan publik secara profesional.</li><li><strong>C</strong>: Merupakan cerminan prinsip aman dalam menjaga kerahasiaan data wajib pajak dari ancaman kebocoran dan kejahatan siber.</li><li><strong>D</strong>: Merupakan manifestasi prinsip melayani dengan sepenuh hati yang tulus dan berorientasi pada kepuasan pemangku kepentingan.</li><li><strong>E</strong>: Merupakan penerapan prinsip transparan yang memberikan kepastian hukum dan ketiadaan biaya pungutan liar kepada masyarakat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Evaluatif", "question": "Nilai Kesempurnaan dimaknai sebagai senantiasa melakukan upaya perbaikan di segala bidang untuk menjadi dan memberikan yang terbaik. Seorang kepala seksi pengawasan perbendaharaan mendapati bahwa meskipun laporan penyerapan anggaran kantor sudah tepat waktu, sistem rekonsiliasi masih mengandalkan entri data ganda yang rawan human error. Pimpinan memutuskan untuk mengembangkan fitur validasi otomatis antarsistem. Penilaian yang paling tepat terhadap keputusan pimpinan tersebut adalah...", "options": ["Tindakan yang keliru karena perbaikan sistem hanya boleh dilakukan apabila kantor telah mengalami teguran resmi dari menteri keuangan.", "Langkah yang membuang waktu dinas karena entri ganda manual dipandang sangat bagus untuk melatih ketahanan otot jari pegawai kantor.", "Kebijakan yang tidak bijaksana karena pimpinan kantor seharusnya membiarkan potensi kesalahan terjadi agar ada staf yang dapat disalahkan.", "Keputusan yang sangat tepat karena mencerminkan penghayatan nilai Kesempurnaan untuk terus berbenah memberikan yang terbaik bagi negara.", "Tindakan yang melanggar aturan hukum dinas karena perbaikan teknologi komputer kantor harus menunggu persetujuan sidang parlemen DPR."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai **Kesempurnaan** menuntut aparatur untuk **tidak cepat berpuas diri** (**avoiding complacency**) dan **senantiasa melakukan inovasi perbaikan berkelanjutan** (**continuous improvement**) demi efisiensi dan keandalan tata kelola perbendaharaan negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D memberikan penilaian evaluatif yang paling tepat, progresif, dan selaras dengan doktrin nilai Kesempurnaan dalam PMK 190/PMK.01/2018. Secara manajemen mutu modern (Total Quality Management), semangat kesempurnaan menolak rasa puas diri atas capaian yang sudah ada (status quo), melainkan terus mencari ruang penyempurnaan (gap analysis) untuk memangkas risiko kesalahan manusiawi (human error) melalui otomasi teknologi yang andal demi mengawal uang rakyat. Rekam jejak inovasi di kementerian keuangan membuktikan bahwa continuous improvement pada aplikasi perbendaharaan sukses menghapus anomali salah catat hingga mendekati nol persen. Oleh karena itu, inisiatif validasi otomatis merupakan cerminan sejati nilai Kesempurnaan.</p><p>Jawaban yang sesuai adalah <strong>D. Keputusan yang sangat tepat karena mencerminkan penghayatan nilai Kesempurnaan untuk terus berbenah memberikan yang terbaik bagi negara.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena perbaikan berkelanjutan bersifat proaktif preventif, bukan menunggu krisis teguran menteri baru mulai berbenah.</li><li><strong>B</strong>: Salah karena melatih otot jari dengan entri ganda manual yang rawan salah merupakan kesesatan berpikir dalam efisiensi birokrasi.</li><li><strong>C</strong>: Salah karena sengaja membiarkan potensi kesalahan demi mencari kambing hitam bawahan merupakan kezaliman etika kepemimpinan.</li><li><strong>E</strong>: Kurang tepat karena perbaikan fitur teknis aplikasi operasional kantor merupakan kewenangan fungsional kementerian pembina teknis.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Aplikasi", "question": "Perilaku utama dari nilai Integritas mencakup bersikap jujur, tulus, dan dapat dipercaya, serta menjaga martabat dan tidak melakukan hal-hal tercela. Ketika seorang staf perbendaharaan menemukan amplop berisikan uang tunai tertinggal di kursi tunggu loket oleh seorang bendahara satuan kerja mitra, tindakan yang paling mencerminkan perilaku utama Integritas adalah...", "options": ["Mengambil amplop tersebut secara diam-diam dan memasukkannya ke dalam saku celana pribadi sebagai rezeki tak terduga dinas.", "Membagikan uang tunai di dalam amplop tersebut kepada seluruh rekan kerja satu seksi kantor untuk ditraktir makan siang bersama.", "Mengamankan amplop bersama petugas keamanan, mendokumentasikan isinya, dan menghubungi bendahara satuan kerja untuk dikembalikan utuh.", "Membuang amplop tersebut ke saluran pembuangan air kotor di belakang kantor agar tidak menimbulkan kecurigaan sesama rekan dinas.", "Menyimpan amplop tersebut di bawah taplak meja kerja selama lima tahun hingga bendahara satuan kerja lupa pernah kehilangan uang."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku utama **Integritas** mewajibkan aparatur untuk **bersikap jujur, tulus, dapat dipercaya, dan menjaga martabat**, dengan segera **mengamankan barang temuan secara transparan dan mengembalikannya kepada pemilik sah** secara utuh.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah tindakan yang paling lurus, jujur, dan berintegritas tinggi sesuai perilaku utama nilai Integritas. Secara etika profesi dan hukum perdata perbendaharaan, uang tertinggal milik pihak mitra bukanlah hak milik aparatur atau kantor, sehingga mengamankan temuan bersama saksi keamanan dinas, membuat berita acara pencatatan, dan segera menghubungi pemiliknya membuktikan bahwa aparatur memegang teguh kejujuran nurani batiniah dan dapat dipercaya menjaga hak orang lain. Pengalaman di berbagai kantor pelayanan kementerian membuktikan bahwa kejujuran mengembalikan barang tertinggal menuai apresiasi luar biasa dari masyarakat dan mengangkat marwah institusi. Maka dari itu, mengamankan dan mengembalikan uang secara utuh mencerminkan perilaku utama Integritas sejati.</p><p>Jawaban yang sesuai adalah <strong>C. Mengamankan amplop bersama petugas keamanan, mendokumentasikan isinya, dan menghubungi bendahara satuan kerja untuk dikembalikan utuh.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mengantongi uang temuan merupakan tindak pidana pencurian atau penggelapan barang temuan yang melanggar hukum.</li><li><strong>B</strong>: Salah karena membagikan uang milik orang lain untuk makan siang kantor merupakan bentuk persekongkolan kejahatan penggelapan dinas.</li><li><strong>D</strong>: Salah karena membuang uang negara ke saluran pembuangan air merupakan tindakan perusakan aset keuangan dan kelalaian moral parah.</li><li><strong>E</strong>: Salah karena menimbun amplop hingga pemilik lupa mencerminkan niat jahat penguasaan ilegal yang bertentangan dengan kejujuran.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Aplikasi", "question": "Perilaku utama nilai Profesionalisme menuntut aparatur mempunyai keahlian dan pengetahuan yang luas serta bekerja dengan hati. Seorang fungsional pemeriksa pajak ditugaskan memeriksa perusahaan teknologi informasi yang menggunakan skema transaksi aset digital kripto yang sangat rumit. Sikap yang paling mencerminkan perilaku utama Profesionalisme dari pemeriksa tersebut adalah...", "options": ["Menolak memeriksa perusahaan tersebut dan meminta dipindahkan ke seksi perpajakan warung kelontong tradisional yang mudah dihitung.", "Menetapkan surat ketetapan pajak kurang bayar secara asal tebak tanpa melakukan telaah basis data transaksi kripto perusahaan.", "Meminta uang suap sebesar satu miliar rupiah kepada direktur perusahaan teknologi sebagai biaya pembatalan surat perintah audit.", "Menyuruh auditor swasta asing untuk melakukan pemeriksaan dengan membagikan seluruh basis data rahasia perpajakan nasional kantor.", "Mempelajari regulasi dan forensik digital aset kripto secara tekun, menganalisis data secara akurat, dan menuntaskan audit berintegritas."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku utama **Profesionalisme** mewajibkan aparatur untuk **mempunyai keahlian dan pengetahuan yang luas** (**deep domain expertise**) serta **bekerja tuntas dan akurat dengan hati**, gigih menguasai forensik digital baru demi mengamankan penerimaan pajak negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah penerapan profesionalisme keahlian yang paling tepat, berbobot, dan mencerminkan jiwa pembelajar tangguh. Secara metodologi pemeriksaan pajak modern, disrupsi transaksi aset digital dan kripto menuntut pemeriksa untuk terus memperbarui kompetensi analitisnya di bidang forensik digital dan regulasi pajak transaksi elektronik, sehingga ketekunan membedah data rantai blok (blockchain) secara akurat menjamin bahwa hak penerimaan negara dihitung secara sah dan berkeadilan. Keberhasilan Ditjen Pajak membongkar penghindaran pajak digital membuktikan bahwa keahlian profesional mendalam sukses menyelamatkan potensi penerimaan triliunan rupiah. Oleh karena itu, belajar tekun dan menuntaskan audit akurat mencerminkan perilaku utama Profesionalisme.</p><p>Jawaban yang sesuai adalah <strong>E. Mempelajari regulasi dan forensik digital aset kripto secara tekun, menganalisis data secara akurat, dan menuntaskan audit berintegritas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena lari dari kasus rumit mencerminkan ketidakmampuan profesional dan kemalasan birokrasi yang merugikan penerimaan negara.</li><li><strong>B</strong>: Salah karena menetapkan pajak secara tebak-tebakan melanggar asas kepastian hukum perpajakan dan pasti dibatalkan pengadilan pajak.</li><li><strong>C</strong>: Salah karena memeras perusahaan teknologi merupakan tindak pidana korupsi pemerasan dalam jabatan yang diancam pidana penjara.</li><li><strong>D</strong>: Salah karena membagikan data rahasia kepada pihak asing melanggar undang-undang kerahasiaan jabatan dan kedaulatan informasi negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Analitis", "question": "Lima Nilai Kementerian Keuangan (Integritas, Profesionalisme, Sinergi, Pelayanan, dan Kesempurnaan) merupakan satu kesatuan filosofi kerja yang tidak dapat dipisahkan. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai hubungan fungsional kelima nilai tersebut?", "options": ["Integritas tanpa profesionalisme dapat melahirkan aparatur yang jujur namun tidak kompeten dalam menyelesaikan urusan perbendaharaan.", "Aparatur diperbolehkan mengorbankan nilai Integritas demi mencapai nilai Kesempurnaan angka penerimaan pajak yang ditargetkan pimpinan.", "Sinergi menjadi jembatan kerja sama produktif yang menghubungkan kompetensi individu menjadi kekuatan kolektif institusi kementerian.", "Pelayanan dan kesempurnaan memastikan bahwa output kerja kementerian selalu berorientasi pada kepuasan publik dan perbaikan mutu tiada henti.", "Profesionalisme tanpa integritas melahirkan bahaya intelektual di mana aparatur yang cerdas justru memanipulasi celah anggaran negara."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kelima Nilai Kementerian Keuangan adalah **kesatuan utuh yang saling mengunci** (**integrated ecosystem**). Nilai **Integritas adalah fondasi mutlak yang tidak boleh dikorbankan** demi mengejar target apa pun, termasuk nilai Kesempurnaan angka penerimaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah simpulan yang salah, menyesatkan, dan merusak fondasi moralitas Kementerian Keuangan. Secara doktrin kelembagaan (PMK 190/PMK.01/2018), Integritas menempati urutan pertama sebagai fondasi moral yang menyangga seluruh nilai lainnya, sehingga pencapaian target penerimaan yang tinggi (Kesempurnaan) tidak ada artinya dan menjadi haram apabila dicapai dengan mengorbankan kejujuran, melakukan pemerasan, atau manipulasi pembukuan (melanggar Integritas). Pernyataan resmi menteri keuangan secara konsisten menegaskan bahwa tidak ada kompromi pada integritas demi mengejar target penerimaan kuantitatif semata. Oleh karena itu, membenarkan pengorbanan integritas demi kesempurnaan angka target merupakan kekeliruan moral yang sangat fatal.</p><p>Jawaban yang sesuai adalah <strong>B. Aparatur diperbolehkan mengorbankan nilai Integritas demi mencapai nilai Kesempurnaan angka penerimaan pajak yang ditargetkan pimpinan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena kejujuran tanpa keahlian teknis (profesionalisme) melahirkan inefisiensi administrasi dinas.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena sinergi memang berfungsi meleburkan ego sektoral menjadi kekuatan kolektif kelembagaan.</li><li><strong>D</strong>: Merupakan pernyataan yang benar karena pelayanan dan kesempurnaan memang berfokus pada keunggulan layanan dan inovasi tiada henti.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena kecerdasan tanpa moralitas integritas melahirkan koruptor intelek yang sangat berbahaya bagi negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Evaluatif", "question": "Seorang kepala kantor perbendaharaan mendapati bahwa stafnya sangat ahli dan bekerja tuntas (Profesional), ramah kepada satuan kerja mitra (Pelayanan), dan selalu berinovasi (Kesempurnaan), namun terdapat persaingan tidak sehat antarseksi yang menolak berbagi data transaksi kas (kurang Sinergi). Langkah evaluatif kepemimpinan yang paling tepat dilakukan oleh kepala kantor adalah...", "options": ["Membiarkan sekat pemisah antarseksi tetap berlangsung asalkan masing-masing seksi mampu mencapai target serapan anggaran bulanan.", "Memecat seluruh kepala seksi yang berselisih dan menggantikannya dengan tenaga alih daya keamanan gedung kantor perbendaharaan.", "Memberikan sanksi pemotongan tunjangan kinerja kepada seluruh staf tanpa memberikan arahan pembinaan kerja sama tim yang jelas.", "Membangun forum dialog lintas seksi, menyelaraskan target data terintegrasi, dan menanamkan bahwa Sinergi adalah pilar mutlak keberhasilan.", "Mewajibkan seluruh staf saling melapor ke kepolisian atas dugaan persaingan curang antarseksi di lingkungan kantor perbendaharaan."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kepemimpinan bertugas **menjaga keseimbangan ekosistem 5 Nilai Kemenkeu**. Ketika pilar Sinergi lemah akibat ego sektoral (*silo mentality*), pimpinan wajib **membangun integrasi data dan merajut kolaborasi lintas seksi** demi keselamatan kinerja organisasi.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D memberikan langkah evaluatif kepemimpinan yang paling tepat, konstruktif, dan berlandaskan manajemen keunggulan organisasi. Secara teori dinamika keorganisasian, kelemahan pada salah satu pilar nilai—seperti ketiadaan sinergi antarseksi—akan menjadi titik rapuh yang menggagalkan keandalan sistem perbendaharaan secara keseluruhan, sehingga pimpinan harus aktif memfasilitasi integrasi basis data bersama dan mengedukasi jajaran bahwa keberhasilan kantor adalah hasil karya tim kolektif, bukan prestasi soliter satu seksi. Praktik terbaik kepemimpinan di kementerian membuktikan bahwa penanaman nilai Sinergi berhasil meruntuhkan sekat ego dan melipatgandakan kecepatan layanan. Oleh karenanya, membangun dialog dan integrasi data merupakan putusan manajerial terbaik.</p><p>Jawaban yang sesuai adalah <strong>D. Membangun forum dialog lintas seksi, menyelaraskan target data terintegrasi, dan menanamkan bahwa Sinergi adalah pilar mutlak keberhasilan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membiarkan silo ego sektoral merusak arus informasi kas negara dan membahayakan akuntabilitas laporan perbendaharaan.</li><li><strong>B</strong>: Salah karena memecat pimpinan teknis dan menggantinya dengan satpam melumpuhkan keahlian fungsional akuntansi perbendaharaan.</li><li><strong>C</strong>: Salah karena pemotongan tunjangan tanpa pembinaan akar masalah hanya memicu demotivasi dan kemarahan emosional staf kantor.</li><li><strong>E</strong>: Salah karena dinamika ego koordinasi internal adalah ranah pembinaan manajerial dinas, bukan tindak pidana kepolisian.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 20", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan tabel Nilai-Nilai Kementerian Keuangan dalam PMK 190/PMK.01/2018, seorang aparatur fiskal dihadapkan pada situasi krisis penerimaan negara di tengah bencana alam yang melanda wilayah kerjanya. Desain respons terpadu yang paling mencerminkan pengamalan paripurna kelima nilai secara serentak adalah...", "options": ["Menutup kantor pelayanan secara permanen dan membagikan seluruh kas penerimaan negara kepada kelompok kroni terdekat pejabat.", "Memadukan kejujuran kas dinas, verifikasi data teliti, sinergi lintas instansi, pemulihan layanan, dan mitigasi krisis berkelanjutan.", "Menyalahkan warga korban bencana yang belum membayar pajak dan menyita seluruh harta benda bantuan sosial logistik yang masuk.", "Meminta kenaikan gaji pokok sebesar lima kali lipat kepada presiden sebagai syarat kesediaan aparatur masuk bekerja saat masa bencana alam.", "Membakar seluruh dokumen fisik wajib pajak di halaman kantor dengan alasan darurat bencana alam agar terbebas dari tanggung jawab audit."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 20", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 20</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Pengamalan paripurna **5 Nilai Kementerian Keuangan** dalam krisis bencana memadukan: **kejujuran penjagaan kas** (*Integritas*), **keahlian pemulihan data akurat** (*Profesionalisme*), **koordinasi logistik kemanusiaan** (*Sinergi*), **kesiapsiagaan melayani masyarakat terdampak** (*Pelayanan*), dan **evaluasi inovasi mitigasi bencana berkelanjutan** (*Kesempurnaan*).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B menyajikan sintesis kepemimpinan dan etika pelayanan publik yang paling paripurna, mulia, dan selaras dengan mandat lima Nilai Kementerian Keuangan. Secara manajemen kebencanaan publik, situasi krisis justru menjadi ujian tertinggi bagi hidup-matinya nilai institusi: menjaga agar kas negara tidak diselewengkan di tengah kekacauan (Integritas), memastikan pencatatan bantuan akurat (Profesionalisme), berkoordinasi erat dengan BPBD dan aparat keamanan (Sinergi), sigap membuka posko pemulihan dokumen warga (Pelayanan), serta mengevaluasi sistem pengamanan data dari ancaman bencana di masa depan (Kesempurnaan). Pengalaman nyata penanganan bencana tsunami dan gempa oleh jajaran kemenkeu membuktikan bahwa keteguhan memegang kelima nilai ini berhasil memulihkan roda ekonomi rakyat secara gemilang. Maka dari itu, perpaduan kelima pilar pada opsi B merupakan sintesis terbaik penutup sub-paket ini.</p><p>Jawaban yang sesuai adalah <strong>B. Memadukan kejujuran kas dinas, verifikasi data teliti, sinergi lintas instansi, pemulihan layanan, dan mitigasi krisis berkelanjutan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menutup layanan dan membagi kas negara kepada kroni merupakan tindak pidana korupsi penjarahan aset negara di masa bencana.</li><li><strong>C</strong>: Salah karena menyita logistik bantuan korban bencana merupakan kebiadaban moral yang melanggar hukum pidana kemanusiaan internasional.</li><li><strong>D</strong>: Salah karena memeras kenaikan gaji di tengah penderitaan rakyat mencerminkan matinya empati kemanusiaan aparatur sipil negara.</li><li><strong>E</strong>: Salah karena membakar dokumen arsip wajib pajak merupakan tindak pidana penghancuran bukti negara yang diancam hukuman pidana penjara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 20.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Analitis", "question": "Integritas diartikan sebagai dorongan hati nurani untuk melaksanakan tugas dan tanggung jawab dengan tekad yang mulia. Berdasarkan perspektif etika kepegawaian publik, mengapa integritas yang bersumber dari dorongan hati nurani batiniah memiliki daya cegah korupsi yang jauh lebih ampuh dibanding ancaman sanksi fisik hukum?", "options": ["Karena hati nurani pegawai secara otomatis dapat menyetrum tubuh apabila tangan hendak mengambil uang suap dari rekanan kantor.", "Karena sanksi pidana penjara di indonesia telah dihapuskan sepenuhnya bagi seluruh aparatur sipil negara yang beragama taat.", "Kesadaran nurani beroperasi otonom menjaga moralitas di ruang sepi tanpa pengawasan, sementara sanksi luar hanya bekerja saat terlihat.", "Karena aparatur yang memiliki hati nurani diizinkan oleh undang-undang untuk memungut sumbangan dana sukarela dari wajib pajak.", "Karena dorongan batiniah menghapuskan kewajiban audit laporan keuangan oleh aparat fungsional pemeriksa internal kementerian."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas sebagai **dorongan hati nurani** (**internal moral compass**) bekerja secara otonom dari dalam diri aparatur, memandu keputusan etis bahkan **dalam kesunyian tanpa kehadiran pimpinan, kamera pengawas, atau ancaman audit fisik** (**acting ethically when no one is watching**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah analisis psikologi moral yang paling tepat mengenai keunggulan integritas berbasis hati nurani. Secara teori integritas kelembagaan, kepatuhan yang semata-mata bersandar pada sanksi hukum eksternal (compliance-based) bersifat rentan dan manipulatif karena pegawai akan mencari celah hukum saat pengawas lengah, sedangkan integritas batiniah (values-based) berakar pada kesadaran tekad mulia dan rasa takut kepada Tuhan sehingga menolak suap secara konsisten di ruang mana pun. Kajian pencegahan fraud kementerian membuktikan bahwa penanaman integritas nurani berhasil membasmi korupsi transaksional di ruang kerja mandiri. Oleh sebab itu, otonomi moral nurani dalam kesunyian merupakan alasan utama keampuhan integritas sejati.</p><p>Jawaban yang sesuai adalah <strong>C. Kesadaran nurani beroperasi otonom menjaga moralitas di ruang sepi tanpa pengawasan, sementara sanksi luar hanya bekerja saat terlihat.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena dorongan hati nurani bekerja melalui pertimbangan akal budi kognitif afektif, bukan fenomena biologis kejut listrik fisik.</li><li><strong>B</strong>: Salah karena hukum pidana tipikor tetap berlaku mutlak dan menjatuhkan sanksi berat bagi aparatur tanpa memandang status agamanya.</li><li><strong>D</strong>: Salah karena integritas nurani justru melarang segala bentuk pungutan liar berkedok sumbangan sukarela masyarakat di loket.</li><li><strong>E</strong>: Salah karena audit kepatuhan keuangan negara tetap wajib dilaksanakan secara berkala demi menjamin transparansi hukum perbendaharaan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Analitis", "question": "Menurut Kamus Besar Bahasa Indonesia (KBBI), integritas berarti mutu, sifat, atau keadaan yang menunjukkan kesatuan yang utuh sehingga memiliki potensi dan kemampuan yang memancarkan kewibawaan dan kejujuran. Unsur mendasar dari definisi KBBI yang menjelaskan lahirnya 'kewibawaan' pada diri seorang pejabat fiskal adalah...", "options": ["Kesatuan utuh antara kejujuran moral batiniah dengan ketegasan sikap nyata yang melahirkan rasa hormat dan kepercayaan publik.", "Tingginya nada bentakan suara pejabat saat memarahi bawahan di lobi kantor yang membuat seluruh pegawai merasa gemetar takut.", "Kepemilikan mobil dinas mewah buatan jerman yang dikawal oleh sirene patroli polisi lalu lintas sepanjang jalan protokol ibu kota.", "Ketebalan berkas surat teguran pajak yang ditandatangani pejabat untuk mengancam penyitaan aset seluruh pengusaha di wilayahnya.", "Banyaknya cincin batu akik mahal dan tongkat komando kayu bertuah yang dibawa pejabat saat memimpin rapat pembahasan anggaran dinas."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Menurut KBBI, **integritas** adalah kesatuan utuh yang **memancarkan kewibawaan dan kejujuran**. Kewibawaan sejati (**authentic authority**) lahir dari **konsistensi moral dan ketegasan integritas**, bukan dari kemewahan fasilitas atau arogansi kekuasaan semu.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A menyajikan analisis makna kewibawaan sesuai definisi KBBI secara paling tepat, elegan, dan ilmiah. Secara sosiologi kepemimpinan, wibawa yang sejati (authoritas) tidak dapat dibeli dengan mobil mewah atau dibangun lewat intimidasi bentakan, melainkan memancar secara alami dari keluhuran karakter seorang pejabat yang jujur, bersih dari suap, dan adil dalam menegakkan regulasi keuangan negara. Tokoh-tokoh negarawan pengelola fiskal Indonesia membuktikan bahwa kesederhanaan hidup yang dipadukan dengan integritas baja melahirkan wibawa moral yang disegani oleh kawan maupun lawan bisnis di dunia internasional. Oleh karena itu, kesatuan utuh kejujuran dan ketegasan sikap merupakan sumber sejati kewibawaan aparatur.</p><p>Jawaban yang sesuai adalah <strong>A. Kesatuan utuh antara kejujuran moral batiniah dengan ketegasan sikap nyata yang melahirkan rasa hormat dan kepercayaan publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena membentak bawahan mencerminkan ketidakmatangan emosi dan arogansi kekuasaan yang justru menghancurkan wibawa moral.</li><li><strong>C</strong>: Salah karena fasilitas mobil mewah dan sirene hanyalah atribut prestise luar yang tidak mencerminkan integritas kejujuran batiniah.</li><li><strong>D</strong>: Salah karena ancaman penyitaan membabi buta tanpa prosedur hukum mencerminkan arogansi birokrasi yang melanggar kepastian hukum.</li><li><strong>E</strong>: Salah karena atribut mistis cincin dan tongkat komando tidak relevan dengan standar rasionalitas dan integritas birokrasi modern.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Aplikasi", "question": "Nilai Integritas menuntut aparatur memiliki tekad mulia dan memancarkan kejujuran dalam setiap pelaksanaan tugas. Di antara perilaku aparatur berikut, manakah tindakan yang BUKAN merupakan cerminan dari integritas dan tekad mulia di lingkungan kerja kementerian keuangan?", "options": ["Menolak secara santun dan tegas pemberian cinderamata emas batangan dari direktur perusahaan yang sedang diperiksa pajaknya.", "Mencatat setiap mutasi penerimaan bea masuk pelabuhan secara presisi ke dalam sistem pembukuan kas negara resmi dinas kantor.", "Mengembalikan laptop dinas kantor dalam kondisi bersih dan baik saat pejabat bersangkutan dimutasikan ke satuan kerja yang lain.", "Memberikan asistensi perpajakan secara tulus kepada pengusaha kecil perintis tanpa memungut imbalan uang saku sepeser pun juga.", "Membuat nota pencairan anggaran dinas fiktif untuk membelikan hadiah cinderamata perpisahan kepala kantor yang dipindahtugaskan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menuntut **kejujuran mutlak dalam tata kelola anggaran**. Membuat nota pencairan anggaran fiktif (**fraudulent expense**) demi hadiah pejabat merupakan **tindak pidana korupsi yang melanggar nilai Integritas**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah skenario tindak pidana korupsi administratif yang bertolak belakang secara mutlak dengan hakikat integritas dan tekad mulia. Secara hukum perbendaharaan negara, mencairkan uang kas negara dengan kuitansi fiktif—meskipun dengan dalih solidaritas membeli cinderamata perpisahan pimpinan kantor—merupakan delik pidana korupsi pengeluaran anggaran negara palsu yang merugikan keuangan negara dan mencederai sumpah jabatan. Hasil audit BPK dan inspektorat jenderal menegaskan bahwa tradisi patungan dana fiktif untuk pejabat mutasi adalah bentuk gratifikasi terlarang yang dijatuhi hukuman disiplin berat. Oleh sebab itu, membuat nota pencairan fiktif jelas bukan cerminan integritas melainkan kejahatan korupsi.</p><p>Jawaban yang sesuai adalah <strong>E. Membuat nota pencairan anggaran dinas fiktif untuk membelikan hadiah cinderamata perpisahan kepala kantor yang dipindahtugaskan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan penerapan integritas tingkat tinggi dalam menolak suap barang berharga bernilai puluhan juta dari auditee pajak.</li><li><strong>B</strong>: Merupakan wujud nyata kejujuran dan ketelitian perbendaharaan dalam mengamankan setiap rupiah penerimaan devisa negara.</li><li><strong>C</strong>: Merupakan cerminan tanggung jawab akuntabilitas dalam mengamankan barang milik negara saat terjadi pergeseran penugasan dinas.</li><li><strong>D</strong>: Merupakan manifestasi ketulusan pelayanan publik yang berdedikasi membantu kebangkitan usaha rakyat tanpa pamrih pungli.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf pemeriksa pajak didatangi oleh pimpinan unit kerjanya yang meminta agar nilai penetapan kurang bayar pajak perusahaan milik sahabat pimpinan diturunkan sebesar lima puluh persen secara informal. Mengacu pada hakikat integritas sebagai dorongan hati nurani dan tekad mulia, tindakan yang wajib diambil oleh pemeriksa tersebut adalah...", "options": ["Menyetujui permintaan pimpinan asalkan dirinya dijanjikan promosi menduduki jabatan kepala seksi pemeriksaan pada tahun depan.", "Menolak secara santun dan tegas permintaan intervensi tersebut, serta tetap menetapkan nilai pajak sesuai data temuan audit objektif.", "Menghapus seluruh berkas pemeriksaan perusahaan sahabat pimpinan tersebut agar tidak meninggalkan jejak digital di sistem kementerian.", "Meminta uang suap tambahan kepada sahabat pimpinan sebagai tanda kompromi penyelesaian berkas pajak yang sedang ditangani.", "Mengundurkan diri secara mendadak dari pegawai negeri sipil dan membocorkan data rahasia wajib pajak tersebut ke media massa asing."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menuntut **keberanian moral** (**moral courage**) untuk **menolak intervensi tidak sah dari atasan** dan tetap **menegakkan penetapan pajak secara objektif sesuai bukti hukum yang sah** (**independent and objective audit**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah tindakan yang paling berani, berintegritas, dan memenuhi standar profesionalisme pemeriksa pajak negara. Secara hukum perpajakan dan kode etik pegawai, penetapan besaran pajak wajib disandarkan pada bukti transaksi pembukuan riil yang terverifikasi secara objektif, di mana perintah lisan atasan untuk menurunkan ketetapan pajak demi kepentingan kroni merupakan perintah ilegal (unlawful order) yang wajib ditolak oleh pemeriksa berintegritas. Pengalaman penegakan kepatuhan internal membuktikan bahwa pemeriksa yang teguh menolak intervensi pimpinan dilindungi oleh saluran pengaduan rahasia (whistleblowing) kementerian. Oleh karena itu, menolak intervensi dan menetapkan pajak berbasis bukti objektif mencerminkan integritas sejati.</p><p>Jawaban yang sesuai adalah <strong>B. Menolak secara santun dan tegas permintaan intervensi tersebut, serta tetap menetapkan nilai pajak sesuai data temuan audit objektif.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena berkompromi demi imbalan promosi jabatan merupakan tindak pidana korupsi kolusi dan suap jabatan yang sangat kotor.</li><li><strong>C</strong>: Salah karena menghapus berkas audit pajak negara merupakan tindak pidana perusakan barang bukti dan pengkhianatan kedaulatan fiskal.</li><li><strong>D</strong>: Salah karena meminta uang suap kompromi merupakan tindak pidana korupsi pemerasan dalam jabatan yang diancam pidana penjara.</li><li><strong>E</strong>: Salah karena melarikan diri dan membocorkan rahasia negara melanggar sumpah jabatan kepegawaian dan merusak kepastian hukum publik.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Evaluatif", "question": "Sebuah kantor wilayah pelayanan fiskal dipimpin oleh kepala kantor yang hidup sederhana, menolak menerima fasilitas mewah dari rekanan swasta, dan selalu transparan dalam memimpin rapat dinas. Seluruh staf merasa segan dan tidak ada satu pun pegawai yang berani melakukan pungutan liar di loket. Penilaian evaluatif yang paling tepat terhadap kepemimpinan kepala kantor tersebut adalah...", "options": ["Kepemimpinan yang keliru karena seorang kepala kantor wilayah seharusnya memamerkan kemewahan harta demi menjaga gengsi korps dinas.", "Tindakan yang merugikan pegawai karena ketegasan menolak fasilitas rekanan menutup peluang staf kantor untuk menikmati jamuan gratis.", "Langkah yang membuang waktu dinas karena kejujuran pimpinan tidak akan mampu memengaruhi perilaku moral staf pelaksana di loket kantor.", "Kepemimpinan teladan yang membuktikan bahwa kesatuan utuh integritas secara nyata memancarkan kewibawaan yang mendisiplinkan lingkungan.", "Kebijakan yang tidak bijaksana karena pimpinan kantor seharusnya mengizinkan pungli kecil di loket guna menambah uang saku pegawai."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Definisi KBBI bahwa integritas memancarkan **kewibawaan dan kejujuran** terbukti dalam praktik kepemimpinan keteladanan (**authentic leadership**): kesederhanaan dan kejujuran pimpinan memancarkan **kewibawaan moral yang menekan penyimpangan di seluruh penjuru kantor**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D memberikan penilaian evaluatif yang paling tepat, apresiatif, dan berlandaskan teori kepemimpinan nilai. Secara sosiologi kekuasaan, kewibawaan yang membuat bawahan segan dan patuh tidak lahir dari ancaman kemarahan fisik, melainkan bersumber dari kebersihan rekam jejak moral pimpinan yang tidak dapat disuap dan konsisten hidup bersahaja (tone at the top), sehingga staf merasa malu dan takut melakukan korupsi di bawah kepemimpinannya. Kajian efektivitas zona integritas membuktikan bahwa figur pimpinan yang berwibawa moral berhasil mewujudkan unit kerja bebas pungli 100% tanpa perlu kekerasan fisik. Oleh sebab itu, kepemimpinan teladan kepala kantor tersebut merupakan bukti nyata bekerjanya kewibawaan integritas.</p><p>Jawaban yang sesuai adalah <strong>D. Kepemimpinan teladan yang membuktikan bahwa kesatuan utuh integritas secara nyata memancarkan kewibawaan yang mendisiplinkan lingkungan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena memamerkan kemewahan hedonistik justru merusak marwah institusi pengelola keuangan negara di hadapan rakyat pembayar pajak.</li><li><strong>B</strong>: Salah karena menikmati jamuan gratis rekanan merupakan bentuk gratifikasi terselubung yang meruntuhkan independensi aparatur.</li><li><strong>C</strong>: Salah karena fakta membuktikan keteladanan nyata pimpinan puncak memiliki daya tular moral yang sangat dahsyat bagi seluruh staf.</li><li><strong>E</strong>: Salah karena menoleransi pungli kecil merupakan bibit korupsi sistemik yang menghancurkan integritas birokrasi dan melanggar hukum.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan konsepsi integritas sebagai dorongan hati nurani dan tekad mulia, sebuah inspektorat kementerian berniat merancang program pembinaan integritas preventif bagi seluruh pegawai. Rancangan modul intervensi etika yang paling komprehensif untuk menyentuh kesadaran hati nurani aparatur adalah...", "options": ["Refleksi spiritualitas kerja bermakna, bedah dilema integritas riil tanpa penghakiman, konseling etika, dan apresiasi keteladanan moral.", "Mewajibkan pegawai meminum air sumpah keramat di depan gedung kantor pada setiap malam bulan purnama di bawah ancaman kutukan gaib.", "Memasang alat penyadap suara di dalam rumah kediaman pribadi seluruh keluarga pegawai guna memantau obrolan domestik rumah tangga.", "Mewajibkan seluruh staf pelaksana menghafalkan seluruh isi kamus bahasa daerah tanpa diberikan pemahaman regulasi perbendaharaan dinas.", "Menyuruh seluruh aparatur menandatangani surat pernyataan bersedia dihukum mati di lapangan terbuka apabila datang terlambat apel pagi."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Menyentuh kesadaran hati nurani menuntut **pendekatan reflektif humanis** (**reflective ethical conditioning**): **refleksi makna spiritualitas kerja sebagai ibadah**, **pembedahan studi kasus dilema etika**, **layanan konseling integritas**, serta **penghargaan atas keteladanan moral**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A menyajikan sintesis metodologi pembinaan etika yang paling ilmiah, luhur, dan menyentuh kedalaman nurani batiniah aparatur. Secara psikologi transpersonal dan etika publik, dorongan hati nurani tidak dapat dibangkitkan lewat ancaman mistis atau teror penyadapan, melainkan melalui ruang perenungan batiniah yang mengaitkan tugas mengelola uang rakyat dengan pertanggungjawaban kepada Sang Pencipta, didukung diskusi terbuka mengenai benturan moral di lapangan dan konseling yang solutif. Implementasi program Bimbingan Mental dan Budaya di Kementerian Keuangan membuktikan bahwa pendekatan humanis reflektif ini berhasil mengokohkan ketahanan integritas aparatur secara berkelanjutan. Oleh karena itu, refleksi spiritual, bedah dilema, konseling, dan apresiasi merupakan formula sintesis terbaik.</p><p>Jawaban yang sesuai adalah <strong>A. Refleksi spiritualitas kerja bermakna, bedah dilema integritas riil tanpa penghakiman, konseling etika, dan apresiasi keteladanan moral.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena ritual mistis air sumpah keramat merupakan kebodohan takhayul yang bertentangan dengan rasionalitas aparatur sipil negara.</li><li><strong>C</strong>: Salah karena menyadap rumah tangga pribadi melanggar hak asasi privasi keluarga konstitusional dan menciptakan iklim kerja paranoid.</li><li><strong>D</strong>: Salah karena menghafal kamus daerah tanpa pemahaman regulasi merupakan pemborosan waktu yang tidak membangun integritas keuangan dinas.</li><li><strong>E</strong>: Salah karena ancaman hukuman mati atas keterlambatan apel merupakan kebiadaban hukum yang bertentangan dengan perundang-undangan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Aplikasi", "question": "Pada saat proses serah terima hasil pekerjaan renovasi gedung kantor pelayanan perbendaharaan, pihak kontraktor menyerahkan sebuah amplop tebal berisikan uang tunai kepada pejabat penerima hasil pekerjaan sebagai 'uang bensin dan tanda terima kasih'. Sikap yang paling mencerminkan dorongan tekad mulia nilai Integritas adalah...", "options": ["Menerima uang tunai tersebut dan menggunakannya untuk mentraktir makan malam seluruh pejabat eselon kementerian keuangan di hotel.", "Meminta kontraktor mentransfer uang tersebut ke rekening kas penampung yayasan panti asuhan milik keluarga pejabat penerima.", "Menyimpan uang amplop tersebut di dalam laci meja dinas hingga masa garansi pemeliharaan gedung selesai selama enam bulan ke depan.", "Menolak secara tegas amplop uang tersebut, menegaskan bahwa serah terima adalah kewajiban dinas gratis, dan membuat berita acara penolakan.", "Menyuruh kontraktor membelikan tiket liburan ke luar negeri bersama keluarga sebagai pengganti pemberian uang tunai di kantor dinas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menuntut **penolakan tegas terhadap segala bentuk gratifikasi** (**zero gratification policy**). Serah terima pekerjaan adalah **kewajiban dinas yang telah dibiayai APBN**, sehingga menerima uang tanda terima kasih merupakan tindak pidana korupsi suap.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah tindakan yang paling profesional, bermoral, dan patuh hukum tindak pidana korupsi. Secara regulasi pengadaan barang dan jasa serta undang-undang tipikor, pejabat penerima hasil pekerjaan telah digaji oleh negara untuk memeriksa kelayakan bangunan secara objektif, sehingga menerima uang terima kasih dari kontraktor merupakan suap yang berpotensi meloloskan bangunan cacat mutu dan membahayakan keselamatan pengguna gedung. Ketegasan menolak dan mendokumentasikan penolakan membuktikan bahwa pejabat tersebut memegang teguh sumpah jabatan dan tekad mulia menjaga integritas kas negara. Maka dari itu, menolak tegas dan membuat berita acara penolakan mencerminkan integritas sejati.</p><p>Jawaban yang sesuai adalah <strong>D. Menolak secara tegas amplop uang tersebut, menegaskan bahwa serah terima adalah kewajiban dinas gratis, dan membuat berita acara penolakan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menerima uang suap kontraktor untuk traktiran pejabat tetap merupakan tindak pidana korupsi penerimaan gratifikasi dinas.</li><li><strong>B</strong>: Salah karena mengalihkan suap ke yayasan keluarga merupakan modus pencucian uang korupsi terselubung yang melanggar hukum.</li><li><strong>C</strong>: Salah karena menimbun amplop di laci mencerminkan keraguan moral dan penampungan gratifikasi jabatan yang diancam pidana penjara.</li><li><strong>E</strong>: Salah karena meminta tiket liburan luar negeri merupakan tindak pidana korupsi pemerasan dan penerimaan fasilitas ilegal pejabat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Analitis", "question": "Integritas menghasilkan kesatuan utuh yang memancarkan kejujuran dan kewibawaan aparatur negara. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai keterkaitan antara integritas dan kewibawaan institusi birokrasi?", "options": ["Kewibawaan institusi perpajakan lahir dari kepastian hukum dan kejujuran aparatur dalam menetapkan besaran pajak yang berkeadilan.", "Integritas yang kokoh pada jajaran perbendaharaan negara melahirkan kepercayaan perbankan internasional terhadap APBN Indonesia.", "Kewibawaan aparat kepabeanan di perbatasan terbangun dari keteguhan menolak suap penyelundup dan konsistensi penegakan hukum.", "Integritas yang terinternalisasi secara utuh membuat aparatur memiliki ketegasan moral dalam menolak segala bentuk kompromi ilegal.", "Kewibawaan aparatur kementerian keuangan diukur dari seberapa sering pejabat memamerkan saldo rekening bank pribadinya di media sosial."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kewibawaan integritas lahir dari **keluhuran etika, profesionalitas, dan kesahajaan moral** (**moral stature and humility**). Memamerkan saldo rekening kekayaan di media sosial (**flexing**) mencerminkan **degradasi integritas dan perilaku hedonistik yang merusak wibawa institusi**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merupakan simpulan yang salah, memalukan, dan bertolak belakang dengan etika aparatur sipil negara pengelola keuangan negara. Secara kode etik dan surat edaran menteri keuangan mengenai pola hidup sederhana, memamerkan harta kekayaan (flexing) di ruang publik mencerminkan ketiadaan empati sosial kepada rakyat kecil, memicu kecurigaan publik atas asal-usul kekayaan aparatur, serta menghancurkan kewibawaan Kementerian Keuangan yang selama bertahun-tahun dibangun dengan integritas. Surat Edaran Penegakan Disiplin menegaskan bahwa aparatur yang bergaya hidup hedonis di media sosial dijatuhi hukuman disiplin dan diperiksa harta kekayaannya oleh KPK dan Itjen. Oleh sebab itu, menyatakan pamer saldo sebagai ukuran kewibawaan adalah kekeliruan moral yang sangat fatal.</p><p>Jawaban yang sesuai adalah <strong>E. Kewibawaan aparatur kementerian keuangan diukur dari seberapa sering pejabat memamerkan saldo rekening bank pribadinya di media sosial.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena kepastian hukum dan kejujuran aparatur memang menjadi pilar legitimasi kewibawaan perpajakan.</li><li><strong>B</strong>: Merupakan pernyataan yang benar karena akuntabilitas perbendaharaan terbukti meningkatkan credit rating kedaulatan fiskal Indonesia.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena ketegasan menolak kompromi penyelundupan merupakan sumber wibawa penjaga batas negara.</li><li><strong>D</strong>: Merupakan pernyataan yang benar karena kesatuan integritas utuh memang membekali aparatur dengan keteguhan moral menolak suap.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Evaluatif", "question": "Sebuah satuan kerja kantor pelayanan lelang negara menghadapi kasus di mana salah satu stafnya tertangkap basah menerima uang pelicin dari peserta lelang di sebuah kedai kopi di luar jam kantor. Kepala kantor segera menerbitkan surat penonaktifan tugas staf tersebut, melaporkannya ke aparat penegak hukum, dan membuka akses seluas-luasnya bagi penyelidikan investigasi. Penilaian yang paling tepat terhadap langkah kepala kantor tersebut adalah...", "options": ["Tindakan yang keliru karena pimpinan seharusnya menutupi kasus penyuapan tersebut demi menjaga reputasi kantor agar tetap dinilai bersih.", "Keputusan yang sangat tepat dan berani karena menunjukkan komitmen nol toleransi integritas yang menyelamatkan kehormatan institusi.", "Langkah yang merugikan pegawai karena pimpinan kantor seharusnya membela stafnya yang tertangkap suap hingga persidangan usai.", "Kebijakan yang membuang waktu dinas karena penerimaan uang pelicin di luar jam kantor dipandang sebagai urusan bisnis privat staf.", "Tindakan yang melanggar hukum dinas karena kepala kantor seharusnya meminta bagian separuh dari uang suap yang diterima oleh staf."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Menjaga integritas institusi menuntut **ketegasan tanpa kompromi** (**zero tolerance to corruption**). Menindak tegas oknum yang tertangkap tangan dan bersikap kooperatif dengan penegak hukum merupakan bukti nyata komitmen menjaga kesucian kewibawaan dan kejujuran kementerian.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B menyajikan penilaian evaluatif yang paling tepat, berani, dan berintegritas tinggi sesuai mandat reformasi kelembagaan. Secara manajemen krisis etika publik, upaya menutup-nutupi kejahatan suap demi reputasi semu justru akan menghancurkan kepercayaan publik secara permanen saat kasus tersebut terbongkar keluar, sedangkan tindakan cepat menonaktifkan pelaku dan menyerahkannya ke ranah hukum membuktikan bahwa institusi menolak melindungi oknum korup dan berkomitmen total pada tata kelola bersih. Praktik transparansi penegakan hukum di kementerian keuangan membuktikan bahwa ketegasan pimpinan menuai apresiasi tinggi dari masyarakat dan aparat penegak hukum. Maka dari itu, langkah kepala kantor tersebut merupakan teladan integritas sejati.</p><p>Jawaban yang sesuai adalah <strong>B. Keputusan yang sangat tepat dan berani karena menunjukkan komitmen nol toleransi integritas yang menyelamatkan kehormatan institusi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menutupi kejahatan suap merupakan permufakatan jahat perintangan hukum (obstruction of justice) yang memperparah skandal.</li><li><strong>C</strong>: Salah karena membela oknum penyuapan secara buta mencederai rasa keadilan masyarakat dan merusak sumpah jabatan aparatur negara.</li><li><strong>D</strong>: Salah karena suap terkait jabatan publik tetap merupakan tindak pidana korupsi tanpa memandang apakah terjadi di dalam atau luar jam dinas.</li><li><strong>E</strong>: Salah karena meminta bagian uang suap merupakan tindak pidana pemerasan dan penerimaan suap bersama-sama yang sangat memalukan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 21", "difficulty": "HOTS • Aplikasi", "question": "Seorang bendahara pengeluaran kantor dinas baru saja menyelesaikan pembayaran tagihan pengadaan komputer kepada sebuah vendor rekanan. Seminggu kemudian, pihak vendor mengirimkan paket kiriman telepon pintar terbaru seharga dua puluh juta rupiah ke alamat rumah pribadi bendahara tersebut sebagai hadiah ulang tahun pribadi. Berdasarkan tekad mulia nilai Integritas, tindakan yang wajib diambil oleh bendahara adalah...", "options": ["Menggunakan telepon pintar tersebut untuk keperluan pribadi dan mengunggah fotonya ke media sosial sebagai bukti rezeki yang halal.", "Menjual telepon pintar tersebut ke gerai elektronik dan membagikan seluruh uang hasil penjualannya kepada sanak kerabat keluarga.", "Melaporkan penerimaan barang tersebut kepada Unit Pengendalian Gratifikasi (UPG) dalam batas waktu resmi untuk diserahkan ke KPK.", "Menyimpan telepon pintar di dalam lemari pakaian selama sepuluh tahun hingga model telepon pintar tersebut dinyatakan usang di pasaran.", "Meminta vendor mengirimkan sepuluh unit telepon pintar tambahan untuk dibagikan kepada seluruh staf seksi perbendaharaan kantor."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 21", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 21</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menuntut ketaatan pada regulasi gratifikasi. Penerimaan hadiah dari vendor rekanan kerja yang dikirimkan ke rumah pribadi merupakan **gratifikasi yang wajib dilaporkan ke Unit Pengendalian Gratifikasi (UPG)** dalam waktu **maksimal 30 hari kerja** guna melepaskan jeratan pidana suap.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah tindakan yang paling berintegritas, jujur, dan patuh regulasi pencegahan korupsi perbendaharaan negara. Secara yuridis (Undang-Undang Tindak Pidana Korupsi Pasal 12B), setiap hadiah yang diberikan oleh pihak yang memiliki hubungan kerja atau kepentingan bisnis kedinasan dianggap sebagai gratifikasi suap yang berpotensi memengaruhi objektivitas jabatan di masa depan, sehingga satu-satunya cara sah dan terhormat adalah melaporkan penerimaan tersebut ke UPG/KPK untuk ditetapkan status kepemilikannya oleh negara. Rekam jejak kepatuhan bendahara di kementerian membuktikan bahwa pelaporan gratifikasi barang mewah melindungi aparatur dari jerat hukum pidana. Oleh sebab itu, melapor ke UPG merupakan wujud sejati dari kejujuran hati nurani penutup sub-paket ini.</p><p>Jawaban yang sesuai adalah <strong>C. Melaporkan penerimaan barang tersebut kepada Unit Pengendalian Gratifikasi (UPG) dalam batas waktu resmi untuk diserahkan ke KPK.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menguasai ponsel pemberian rekanan merupakan tindak pidana korupsi penerimaan gratifikasi ilegal yang diancam pidana.</li><li><strong>B</strong>: Salah karena menjual barang hasil gratifikasi jabatan merupakan tindak pidana pencucian uang dan penjualan barang haram gratifikasi.</li><li><strong>D</strong>: Salah karena menyembunyikan ponsel di lemari pakaian mencerminkan niat penimbunan gratifikasi jabatan yang melanggar hukum.</li><li><strong>E</strong>: Salah karena meminta unit tambahan merupakan tindak pidana pemerasan dalam jabatan yang diancam hukuman pidana penjara maksimal.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 21.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Analitis", "question": "Seseorang dikatakan mempunyai integritas apabila tindakannya sesuai dengan nilai, keyakinan, dan prinsip yang dipegangnya. Dalam praktik manajemen publik, mengapa keselarasan antara keyakinan batiniah dengan tindakan nyata di loket pelayanan menjadi penentu utama legitimasi moral aparatur?", "options": ["Karena masyarakat pada umumnya sangat menyukai pejabat yang pandai bersandiwara di depan panggung pidato peringatan hari nasional.", "Keselarasan tindakan membuktikan keaslian moral aparatur sehingga masyarakat yakin bahwa kebijakan fiskal dijalankan secara adil.", "Agar kementerian keuangan dapat menghemat anggaran pembinaan etika dengan memecat seluruh staf pengawas kepatuhan internal kantor.", "Karena aparatur yang selaras kata dan perbuatannya secara otomatis kebal dari kewajiban menyampaikan laporan harta kekayaan LHKPN.", "Karena keselarasan tindakan membebaskan aparatur dari kewajiban mematuhi standar operasional prosedur pemeriksaan pajak negara."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Seseorang berintegritas apabila **tindakannya selaras dengan nilai, keyakinan, dan prinsip** (**action-value congruence**), membuktikan keaslian moral dan memberikan kepastian kepada masyarakat bahwa pemungutan uang negara dijalankan secara bersih dan berkeadilan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah analisis aksiologi dan etika pemerintahan yang paling mendalam mengenai makna integritas tindakan. Secara sosiologi hukum publik, kepercayaan sukarela wajib pajak (voluntary tax compliance) lahir ketika masyarakat menyaksikan bahwa para pengelola pajak bukan hanya berkhotbah tentang kejujuran, melainkan secara nyata bertindak lurus, menolak suap, dan tidak menyalahgunakan wewenangnya demi kekayaan pribadi. Riset kepatuhan perpajakan global membuktikan bahwa keselarasan nilai dan tindakan aparatur berkorelasi positif paling tinggi dengan kesediaan rakyat membayar pajak. Oleh karena itu, pembuktian keaslian moral yang melahirkan kepercayaan publik merupakan esensi utama legitimasi integritas aparatur.</p><p>Jawaban yang sesuai adalah <strong>B. Keselarasan tindakan membuktikan keaslian moral aparatur sehingga masyarakat yakin bahwa kebijakan fiskal dijalankan secara adil.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena masyarakat sangat membenci kemunafikan sandiwara pejabat dan menuntut kejujuran nyata dalam pelayanan publik.</li><li><strong>C</strong>: Salah karena keselarasan nilai justru membutuhkan penguatan sistem kepatuhan internal yang berkelanjutan guna menjaga konsistensi.</li><li><strong>D</strong>: Salah karena setiap pejabat publik tetap wajib melaporkan harta kekayaan LHKPN secara transparan dan akuntabel kepada KPK.</li><li><strong>E</strong>: Salah karena keselarasan nilai menuntut kepatuhan yang semakin ketat terhadap SOP, bukan membebaskan dari aturan prosedur hukum.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Analitis", "question": "Salah satu ciri utama seseorang yang berintegritas adalah bersatunya kata dan perbuatan (walk the talk), bukan tipe manusia dengan banyak wajah yang penampilannya disesuaikan dengan motif dan kepentingan pribadinya. Bahaya laten paling destruktif bagi iklim kerja kantor pelayanan apabila seorang pimpinan memiliki karakter 'banyak wajah' (bermuka dua) adalah...", "options": ["Pendingin ruangan kantor pelayanan akan mengeluarkan suara mendesis yang mengganggu ketenangan tidur siang para staf loket dinas.", "Seluruh tanaman hias di halaman depan kantor dinas akan mengalami layu daun secara serentak dalam waktu kurang dari satu hari dinas.", "Cat dinding lobi kantor pelayanan perpajakan akan berubah warna menjadi hitam pekat secara misterius pada saat tengah malam hari.", "Hancurnya rasa saling percaya, lahirnya budaya penjilat, dan hilangnya kepastian standar kebenaran etika di seluruh jajaran kantor.", "Masyarakat pengguna layanan akan menolak menaiki angkutan umum kota saat hendak bepergian mengurus berkas perizinan ke kantor."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menolak manusia bertopeng (**many-faced/hypocrite**). Pemimpin yang bermuka dua (kata tidak selaras perbuatan) akan **menghancurkan rasa saling percaya** (**eroding organizational trust**), menumbuhkan **budaya penjilat** (*sycophancy*), dan memicu kebingungan moral aparatur.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merangkum dampak destruktif dari kemunafikan kepemimpinan bermuka dua secara paling tepat, ilmiah, dan berbasis teori psikologi organisasi. Ketika pimpinan berpidato garang menolak suap namun di belakang layar menerima gratifikasi rekanan dan menuntut bawahan melayaninya, organisasi akan terjangkit racun kultural di mana kejujuran dianggap kebodohan, budaya menjilat demi keselamatan jabatan tumbuh subur, dan seluruh staf kehilangan kompas kepatutan etika kerja. Kajian reformasi birokrasi menegaskan bahwa ketidakselarasan kata dan perbuatan pimpinan merupakan pemicu nomor satu runtuhnya integritas unit kerja. Maka dari itu, kehancuran rasa saling percaya dan suburnya budaya penjilat merupakan dampak paling destruktif dari pemimpin bermuka dua.</p><p>Jawaban yang sesuai adalah <strong>D. Hancurnya rasa saling percaya, lahirnya budaya penjilat, dan hilangnya kepastian standar kebenaran etika di seluruh jajaran kantor.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mendesisnya pendingin udara merupakan gangguan teknis freon mesin, bukan representasi ilmiah kerusakan etika budaya.</li><li><strong>B</strong>: Salah karena layunya tanaman hias adalah fenomena biologis fotosintesis dan penyiraman air, bukan konsekuensi moralitas kepemimpinan.</li><li><strong>C</strong>: Salah karena perubahan warna cat dinding adalah fiksi mistis konyol yang tidak relevan dengan kajian tata kelola perilaku organisasi.</li><li><strong>E</strong>: Salah karena keputusan warga menaiki angkutan umum tidak berhubungan secara kausalitas dengan kepemimpinan bermuka dua di kantor dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Aplikasi", "question": "Seorang kepala kantor perbendaharaan baru saja menandatangani komitmen bersama pembangunan Zona Integritas menuju Wilayah Bebas dari Korupsi (WBK) di hadapan media dan tokoh masyarakat. Penerapan prinsip bersatunya kata dan perbuatan yang wajib ditunjukkan oleh kepala kantor tersebut pada hari kerja berikutnya adalah...", "options": ["Konsisten hadir tepat waktu, menolak seluruh pemberian cinderamata rekanan, dan mengevaluasi loket pelayanan secara transparan.", "Memanggil seluruh rekanan pengadaan barang kantor dan meminta uang komisi khusus sebagai biaya sukses penandatanganan piagam WBK.", "Mengunci pintu ruang kerjanya rapat-rapat dan bermain permainan daring sepanjang hari dinas tanpa melayani berkas perbendaharaan.", "Memerintahkan seluruh staf loket untuk meminta sumbangan sukarela kepada pemohon layanan guna membiayai pesta syukuran piagam.", "Mencopot kembali spanduk komitmen Zona Integritas dari pagar kantor dinas karena menganggap seremonial di hadapan media telah usai."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Prinsip **bersatunya kata dan perbuatan** (**walk the talk**) mewajibkan pimpinan untuk **membuktikan ikrar integritas melalui perilaku nyata harian**: keteladanan disiplin jam kerja, ketegasan menolak gratifikasi rekanan, dan transparansi pengawasan loket publik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah tindakan yang paling lurus, konsisten, dan memenuhi amanat deklarasi integritas aparatur sipil negara. Secara manajemen integritas kelembagaan, penandatanganan piagam Zona Integritas bukanlah akhir seremonial untuk konsumsi pemberitaan media, melainkan ikrar janji suci di hadapan Tuhan dan rakyat yang wajib dibuktikan esok harinya melalui disiplin waktu hadir di kantor, penolakan mutlak atas segala bingkisan rekanan, serta pemantauan langsung terhadap kebersihan loket perbendaharaan dari pungli. Fakta penilaian zona integritas oleh KemenPANRB membuktikan bahwa konsistensi keteladanan pimpinan merupakan kriteria kelulusan utama meraih predikat WBK. Oleh karena itu, keteladanan hadir tepat waktu dan menolak cinderamata mencerminkan bersatunya kata dan perbuatan.</p><p>Jawaban yang sesuai adalah <strong>A. Konsisten hadir tepat waktu, menolak seluruh pemberian cinderamata rekanan, dan mengevaluasi loket pelayanan secara transparan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena meminta komisi lelang pasca-deklarasi merupakan tindak pidana korupsi penyuapan dan puncak kemunafikan birokrasi.</li><li><strong>C</strong>: Salah karena bermalas-malasan bermain gim di ruang terkunci merupakan kelalaian tugas berat yang mencoreng komitmen WBK dinas.</li><li><strong>D</strong>: Salah karena memungut sumbangan sukarela perayaan merupakan pungutan liar ilegal yang melanggar esensi zona bebas korupsi.</li><li><strong>E</strong>: Salah karena mencopot spanduk membuktikan bahwa komitmen integritas hanyalah sandiwara sesaat yang membohongi masyarakat publik.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Analitis", "question": "Panduan perilaku utama nilai Integritas Kementerian Keuangan menegaskan kewajiban menjaga martabat dan tidak melakukan hal-hal tercela. Di antara perilaku aparatur berikut, manakah tindakan yang BUKAN merupakan cerminan dari menjaga martabat dan kehormatan korps kementerian?", "options": ["Mengenakan pakaian dinas resmi secara rapi, bersih, dan sesuai dengan ketentuan peraturan tata tertib berseragam kementerian.", "Bertutur kata secara santun, tidak menyebarkan fitnah atau ujaran kebencian, serta menjaga etika pergaulan di ruang publik nyata dan daring.", "Menjaga keharmonisan rumah tangga, membina keluarga secara rukun, dan tidak melakukan perbuatan asusila yang melanggar hukum etika.", "Menggunakan fasilitas mobil dinas operasional kantor untuk kepentingan penugasan pengawasan lapangan penerimaan fiskal negara.", "Terlibat dalam pertengkaran fisik dan perjudian daring ilegal menggunakan fasilitas komputer inventaris ruangan kantor dinas."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Menjaga martabat dan tidak melakukan hal tercela menuntut **penjagaan kehormatan moral di ruang publik dan privat**. Terlibat pertengkaran fisik dan perjudian daring (**online gambling and brawling**) menggunakan aset dinas merupakan **pelanggaran etika berat dan tindak pidana**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E merupakan contoh tindakan tercela yang meruntuhkan martabat pribadi dan mencemarkan nama baik institusi kementerian di mata publik. Secara hukum disiplin kepegawaian (Peraturan Pemerintah tentang Disiplin PNS) dan kode etik kementerian keuangan, aparatur dilarang keras terlibat dalam perjudian apa pun, perkelahian fisik, maupun penyalahgunaan fasilitas komputer kantor untuk kegiatan melanggar hukum pidana. Keputusan Menteri Keuangan secara tegas menjatuhkan sanksi hukuman disiplin berat hingga pemecatan tidak dengan hormat bagi aparatur yang terlibat perjudian daring. Oleh sebab itu, bermain judi daring dan berkelahi jelas merupakan perbuatan tercela yang melanggar nilai Integritas.</p><p>Jawaban yang sesuai adalah <strong>E. Terlibat dalam pertengkaran fisik dan perjudian daring ilegal menggunakan fasilitas komputer inventaris ruangan kantor dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan penerapan disiplin berbusana dinas yang rapi dan profesional dalam mencerminkan kehormatan fisik institusi negara.</li><li><strong>B</strong>: Merupakan cerminan kesantunan moral dan kedewasaan etika dalam menjaga martabat korps di ruang percakapan sosial dan digital.</li><li><strong>C</strong>: Merupakan wujud keteladanan moral aparatur dalam menjaga keutuhan rumah tangga dan menjauhi perbuatan asusila yang memalukan.</li><li><strong>D</strong>: Merupakan pemanfaatan barang milik negara yang tepat sasaran dan akuntabel sesuai peruntukan dinas penugasan pengawasan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat pemeriksa cukai mendapati seorang staf pelaksana fungsional selalu menunjukkan sikap manis dan memuji pimpinan di ruang rapat dinas, namun secara rahasia kerap memeras pengusaha pabrik rokok rumahan dengan mengancam akan menyita pita cukai mereka. Langkah evaluasi dan tindakan manajerial yang paling tepat dilakukan oleh pejabat pemeriksa cukai tersebut adalah...", "options": ["Mendiamkan tindakan staf tersebut karena staf tersebut selalu bersikap sangat sopan dan menyenangkan hati para pejabat eselon kantor.", "Meminta staf tersebut membagi sebagian hasil uang pemerasan pabrik rokok kepada pejabat pemeriksa agar keduanya sama-sama untung.", "Mengumpulkan bukti pemerasan secara objektif, menindak tegas staf bermuka dua tersebut, dan melindung pengusaha pabrik rokok dari pungli.", "Menutup pabrik rokok rumahan tersebut secara sepihak tanpa proses pemeriksaan hukum demi melindungi identitas staf kantor dinas.", "Menaikkan pangkat staf tersebut menjadi kepala seksi penindakan karena dianggap memiliki kecerdasan ganda dalam berbirokrasi."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Menolak aparatur bertopeng (**eliminating hypocrisy**) menuntut **penindakan tegas berbasis bukti hukum objektif** terhadap oknum yang bermuka manis di depan atasan namun melakukan pemerasan di lapangan, serta **memberikan perlindungan hukum kepada dunia usaha** (**protecting honest taxpayers**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C menyajikan langkah evaluasi kepemimpinan yang paling tepat, berintegritas, dan menjunjung tinggi keadilan hukum. Secara hukum administrasi negara dan pemberantasan korupsi, sikap sopan di depan atasan tidak boleh menjadi tameng pemaaf bagi tindakan kriminal pemerasan terhadap pengusaha kecil di lapangan, sehingga pejabat pengawas berkewajiban mengumpulkan bukti rekaman transaksi, memproses sanksi pemecatan disiplin terhadap staf bermuka dua tersebut, dan mengamankan hak berusaha pengusaha rokok yang taat aturan. Fakta penindakan di kementerian membuktikan bahwa ketegasan membongkar oknum bermuka dua berhasil menyelamatkan wibawa cukai dan iklim investasi industri tembakau. Oleh karenanya, menindak staf munafik dan membela hak pengusaha merupakan perwujudan integritas sejati.</p><p>Jawaban yang sesuai adalah <strong>C. Mengumpulkan bukti pemerasan secara objektif, menindak tegas staf bermuka dua tersebut, dan melindung pengusaha pabrik rokok dari pungli.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membiarkan pemerasan demi kenyamanan pujian staf mencerminkan kepemimpinan narsistik korup yang berkhianat pada hukum.</li><li><strong>B</strong>: Salah karena meminta bagi hasil pemerasan merupakan tindak pidana korupsi kolusi pemerasan bersama-sama yang diancam pidana penjara.</li><li><strong>D</strong>: Salah karena menutup pabrik tanpa kesalahan hukum merupakan kesewenang-wenangan birokrasi yang mematikan mata pencaharian warga.</li><li><strong>E</strong>: Salah karena mempromosikan staf korup bermuka dua merupakan penghancuran sistem meritokrasi yang melegalkan kejahatan jabatan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf pengelola kas perbendaharaan mendapati dirinya secara tidak sengaja melakukan kesalahan pengetikan digit angka transfer kelebihan pembayaran tagihan belanja kantor sebesar lima puluh juta rupiah ke rekening sebuah rekanan rekan kerja. Rekanan tersebut belum menyadari adanya kelebihan transfer. Sikap yang paling mencerminkan perilaku utama bersikap jujur, tulus, dan dapat dipercaya adalah...", "options": ["Segera mengakui kekeliruan kepada atasan, menghubungi rekanan secara resmi, dan mengurus pengembalian kelebihan kas negara ke rekening kas umum.", "Mendiamkan kekeliruan tersebut dan memanipulasi buku kas harian agar selisih lima puluh juta rupiah ditutupi dari pos belanja lain.", "Menghubungi rekanan secara pribadi dan meminta uang lima puluh juta rupiah tersebut dibagi dua secara rahasia sebagai uang tutup mulut.", "Menghapus riwayat transaksi perbankan dari komputer dinas kantor agar auditor BPK tidak dapat menemukan jejak kesalahan transfer kas.", "Menyalahkan petugas operator komputer sif sebelumnya atas kesalahan transfer tersebut dan memintanya mengganti dengan uang pribadi."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku utama **Jujur, Tulus, dan Dapat Dipercaya** menuntut aparatur untuk **berani mengakui kesalahan administrasi secara terbuka**, bertanggung jawab penuh, dan **segera melakukan tindakan korektif pengembalian dana kas negara** tanpa manipulasi.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah tindakan yang paling berintegritas, ksatria, dan memenuhi standar pertanggungjawaban perbendaharaan negara. Secara hukum keuangan negara, kesalahan pengetikan mutasi (human error) adalah risiko operasional yang wajar terjadi, di mana integritas seseorang diuji pada kejujurannya mengakui kekeliruan sejak dini kepada pimpinan dan secara terbuka meminta bank serta rekanan untuk memproses retur mutasi kas negara kembali ke kas umum secara sah. Rekam jejak tata kelola perbendaharaan membuktikan bahwa keterbukaan pelaporan salah transfer yang ditindaklanjuti secara cepat berhasil menyelamatkan 100% uang negara tanpa menimbulkan kerugian keuangan negara. Maka dari itu, mengakui kekeliruan dan mengurus retur kas mencerminkan kejujuran nurani sejati.</p><p>Jawaban yang sesuai adalah <strong>A. Segera mengakui kekeliruan kepada atasan, menghubungi rekanan secara resmi, dan mengurus pengembalian kelebihan kas negara ke rekening kas umum.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena memanipulasi buku kas demi menutupi kesalahan transfer merupakan tindak pidana pemalsuan pembukuan keuangan negara.</li><li><strong>C</strong>: Salah karena meminta bagi hasil uang salah transfer merupakan tindak pidana korupsi penggelapan dana kas negara dan pemerasan.</li><li><strong>D</strong>: Salah karena menghapus jejak digital perbankan merupakan tindak pidana perusakan data elektronik perbendaharaan yang melanggar hukum.</li><li><strong>E</strong>: Salah karena melempar kesalahan kepada rekan kerja mencerminkan kepengecutan moral yang melanggar kode etik kejujuran dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan prinsip bersatunya kata dan perbuatan (walk the talk) dan penolakan manusia bermuka dua, sebuah kantor wilayah kementerian keuangan berniat menyusun 'Pakta Keteladanan Perilaku Terpadu'. Desain instrumen kelembagaan yang paling efektif untuk memastikan bahwa komitmen nilai dihayati secara nyata dalam tindakan harian adalah...", "options": ["Mewajibkan pegawai membawa cermin kaca besar ke meja kerja kantor guna memeriksa apakah wajah mereka terlihat bermuka dua setiap jam.", "Memasang pengeras suara otomatis di toilet kantor yang membacakan ancaman siksa neraka bagi pegawai yang tidak jujur sepanjang hari.", "Mengintegrasikan komitmen perilaku ke dalam kontrak kinerja individu, penilaian perilaku 360 derajat, dan audit integritas berkala.", "Melarang seluruh staf berbicara satu sama lain di lingkungan kantor agar tidak terjadi pertentangan antara perkataan dan perbuatan dinas.", "Mewajibkan pegawai menandatangani perjanjian penyerahan seluruh rumah dan tanah warisan keluarga kepada kepala kantor wilayah dinas."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Membumikan budaya **walk the talk** menuntut **pelembagaan sistemik**: pengikatan komitmen perilaku ke dalam **kontrak kinerja individu**, evaluasi perilaku berbasis **umpan balik multi-arah 360 derajat**, serta **audit kepatuhan integritas berkala** (**integrity audit**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C menyajikan sintesis kebijakan kelembagaan yang paling utuh, ilmiah, dan berdaya terap tinggi dalam manajemen sumber daya manusia aparatur. Secara teori keselarasan perilaku (behavioral integrity systems), konsistensi antara kata dan perbuatan tidak dapat diserahkan hanya pada imbauan moral pasif, melainkan harus diikat dalam instrumen pengukuran terstruktur: kontrak kinerja perilaku yang jelas, penilaian perilaku oleh atasan, rekan sejawat, dan bawahan (360-degree feedback) untuk mendeteksi perilaku bermuka dua, serta audit integritas acak oleh unit kepatuhan internal. Keberhasilan implementasi di kementerian keuangan membuktikan bahwa keterpaduan instrumen ini sukses mengikis kemunafikan birokrasi dan melahirkan aparatur yang konsisten berintegritas. Oleh sebab itu, formulasi opsi C merupakan instrumen kelembagaan terbaik.</p><p>Jawaban yang sesuai adalah <strong>C. Mengintegrasikan komitmen perilaku ke dalam kontrak kinerja individu, penilaian perilaku 360 derajat, dan audit integritas berkala.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membawa cermin besar ke meja kerja merupakan lelucon konyol yang memalukan martabat dan mengganggu konsentrasi dinas.</li><li><strong>B</strong>: Salah karena ancaman rekaman suara di toilet merupakan teror psikologis yang tidak relevan dengan metodologi pembinaan etika modern.</li><li><strong>D</strong>: Salah karena melarang komunikasi mematikan koordinasi pelayanan publik dan melanggar hak asasi komunikasi aparatur sipil negara.</li><li><strong>E</strong>: Salah karena menuntut penyerahan tanah warisan merupakan perampasan hak milik privat yang bertentangan dengan hukum perdata dan UUD 1945.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Analitis", "question": "Doktrin integritas Kementerian Keuangan secara tegas menolak tipe manusia dengan banyak wajah (bermuka dua). Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai karakteristik manusia berintegritas vs manusia bermuka banyak dalam tata kelola birokrasi?", "options": ["Manusia berintegritas memiliki keteguhan prinsip yang tidak berubah saat berada di depan pimpinan maupun saat berada di ruang tertutup.", "Manusia bermuka banyak menyesuaikan ucapannya semata-mata demi menyenangkan pimpinan dan mengamankan kepentingan pragmatis pribadi.", "Manusia berintegritas berani menyampaikan kebenaran data faktual meskipun berisiko tidak disukai oleh pihak yang berkuasa di kantor.", "Manusia bermuka banyak menampilkan citra kesalehan dan kejujuran di media sosial namun mempraktikkan pemerasan suap di loket kantor.", "Manusia berintegritas adalah individu yang kaku dan menolak bersikap ramah kepada masyarakat pemohon karena takut dianggap bermuka manis."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menuntut **keteguhan prinsip dan kejujuran nurani yang tulus**, serta **selalu bersikap ramah dan santun** (**friendly and respectful**). Bersikap kaku, kasar, atau judes bukan tanda integritas melainkan **kegagalan etika pelayanan publik**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E merupakan simpulan yang salah, menyesatkan, dan mereduksi integritas menjadi sikap arogan yang tidak ramah. Secara etika aparatur sipil negara, manusia berintegritas sejati memadukan ketegasan prinsip menolak korupsi dengan kehangatan keramahan melayani masyarakat secara tulus (compassionate integrity), di mana senyuman dan kesantunan di loket pelayanan publik bukanlah kepura-puraan bermuka manis melainkan wujud rasa hormat kepada sesama warga negara. Hasil survei pelayanan prima kementerian menegaskan bahwa petugas loket berintegritas tertinggi adalah mereka yang paling ramah dan sabar membantu warga. Oleh sebab itu, menganggap sikap kaku dan menolak ramah sebagai tanda integritas adalah kekeliruan konsep yang fatal.</p><p>Jawaban yang sesuai adalah <strong>E. Manusia berintegritas adalah individu yang kaku dan menolak bersikap ramah kepada masyarakat pemohon karena takut dianggap bermuka manis.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena konsistensi moral melintasi ruang publik dan ruang sepi adalah ciri hakiki integritas sejati.</li><li><strong>B</strong>: Merupakan pernyataan yang benar karena oportunisme penjilat demi kepentingan pribadi merupakan esensi dari manusia bermuka dua.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena keberanian moral menyampaikan kebenaran objektif (speaking truth to power) adalah pilar integritas.</li><li><strong>D</strong>: Merupakan pernyataan yang benar karena jurang antara pencitraan saleh luar dengan praktik suap loket adalah definisi manusia bertopeng.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Evaluatif", "question": "Dalam penegakan disiplin jam kerja di sebuah kantor pelayanan pajak, kepala kantor selalu menjatuhkan pemotongan tunjangan kinerja kepada staf pelaksana yang terlambat lima menit, namun membiarkan rekan akrabnya sesama pejabat eselon yang kerap datang terlambat satu jam setiap hari. Penilaian evaluatif yang paling tepat terhadap perilaku kepala kantor tersebut adalah...", "options": ["Langkah kepemimpinan yang sangat tepat karena pejabat eselon memang memiliki hak prerogatif untuk masuk kantor sesuka hati pribadinya.", "Tindakan yang patut dipuji karena menjaga keharmonisan pertemanan antarpejabat eselon jauh lebih penting dibanding menegakkan aturan.", "Keputusan yang bijaksana karena staf pelaksana rendahan memang harus dididik keras dengan sanksi uang agar memiliki ketahanan fisik.", "Perilaku standar ganda yang mencerminkan hilangnya integritas kepemimpinan dan menghancurkan wibawa penegakan disiplin kantor.", "Kebijakan yang selaras dengan nilai kementerian keuangan karena aturan jam kerja dinas hanya diciptakan khusus untuk staf pelaksana."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menuntut **keadilan tanpa tebang pilih** (**consistent and impartial justice**). Menerapkan **standar ganda** (**double standards**) dengan menghukum staf bawahan namun membiarkan rekan pejabat mencerminkan **kemunafikan kepemimpinan yang menghancurkan wibawa aturan**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D memberikan penilaian evaluatif yang paling tepat, tajam, dan berakar pada prinsip keadilan penegakan etika aparatur sipil negara. Secara teori kepemimpinan nilai, keteladanan pimpinan diuji pada keberaniannya menerapkan aturan hukum secara setara dan adil tanpa memandang hierarki jabatan atau pertemanan pribadi (impartiality), di mana penegakan disiplin yang tajam ke bawah namun tumpul ke atas melahirkan ketidakadilan yang meremukkan moral kerja staf pelaksana dan memicu pemberontakan budaya bawah tanah. Laporan audit kepatuhan internal inspektorat menegaskan bahwa diskriminasi disiplin semacam ini merupakan pelanggaran berat kode etik kepemimpinan. Oleh karenanya, perilaku standar ganda tersebut merupakan cerminan hilangnya integritas pimpinan.</p><p>Jawaban yang sesuai adalah <strong>D. Perilaku standar ganda yang mencerminkan hilangnya integritas kepemimpinan dan menghancurkan wibawa penegakan disiplin kantor.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena pejabat publik terikat pada jam dinas yang sama dengan seluruh aparatur dan tidak memiliki hak istimewa terlambat.</li><li><strong>B</strong>: Salah karena pertemanan pribadi tidak boleh mengorbankan penegakan regulasi dinas negara dan sumpah jabatan kepemimpinan.</li><li><strong>C</strong>: Salah karena menghukum bawahan demi dalih mendidik keras sementara pejabat dibiarkan merupakan bentuk kezaliman birokrasi feodal.</li><li><strong>E</strong>: Salah karena regulasi jam kerja dinas mengikat seluruh jajaran aparatur dari staf terendah hingga menteri keuangan tanpa kecuali.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 22", "difficulty": "HOTS • Aplikasi", "question": "Seorang pejabat perbendaharaan sedang menyusun laporan pertanggungjawaban realisasi belanja pengadaan sarana kantor di akhir tahun anggaran. Pejabat tersebut mendapati bahwa terdapat sisa dana belanja pemeliharaan gedung sebesar sepuluh juta rupiah yang belum terserap. Penerapan keselarasan berpikir, berkata, berperilaku, dan bertindak dengan baik dan benar sesuai nilai Integritas adalah...", "options": ["Membuat kuitansi pembelian cat gedung fiktif sebesar sepuluh juta rupiah agar penyerapan anggaran kantor dinilai mencapai seratus persen.", "Mencatatkan sisa dana sepuluh juta rupiah tersebut secara transparan dan menyetorkannya kembali ke kas negara sesuai regulasi perbendaharaan.", "Menyimpan sisa dana tersebut di brankas kantor secara rahasia untuk digunakan membiayai acara rekreasi keluarga pejabat tahun depan.", "Membagikan sisa dana sepuluh juta rupiah tersebut kepada seluruh anggota panitia pengadaan sebagai bonus uang lelah kerja lembur akhir tahun.", "Mentransfer sisa dana tersebut ke rekening pribadi bendahara dengan janji akan dikembalikan pada tahun anggaran berikutnya saat diaudit."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 22", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 22</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas menuntut **keselarasan berpikir, berkata, berperilaku, dan bertindak dengan baik dan benar**: menolak rekayasa serapan anggaran fiktif, **mencatat sisa anggaran secara jujur, dan menyetorkannya kembali ke kas negara** (**returning unspent funds to state treasury**) sesuai undang-undang keuangan negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah tindakan aplikasi nilai Integritas yang paling lurus, jujur, dan patuh hukum perbendaharaan negara. Secara hukum keuangan publik (Undang-Undang Perbendaharaan Negara), sisa anggaran belanja dinas yang tidak terserap pada akhir tahun anggaran wajib disetorkan kembali ke kas negara sebagai Sisa Lebih Pembiayaan Anggaran (SiLPA) yang sah, di mana merekayasa kuitansi fiktif demi mengejar target serapan seratus persen semu merupakan tindak pidana korupsi manipulasi pembukuan negara. Kepatuhan bendahara dalam menyetorkan sisa dana kas membuktikan bahwa kejujuran batiniah memancar nyata dalam tindakan hukum yang akuntabel. Maka dari itu, mencatat transparan dan menyetor kembali ke kas negara mencerminkan integritas sejati penutup sub-paket ini.</p><p>Jawaban yang sesuai adalah <strong>B. Mencatatkan sisa dana sepuluh juta rupiah tersebut secara transparan dan menyetorkannya kembali ke kas negara sesuai regulasi perbendaharaan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena membuat kuitansi fiktif demi target serapan anggaran merupakan tindak pidana korupsi pemalsuan bukti pengeluaran negara.</li><li><strong>C</strong>: Salah karena menimbun kas negara untuk rekreasi pribadi merupakan tindak pidana korupsi penyimpangan anggaran kas negara non-bujeter.</li><li><strong>D</strong>: Salah karena membagikan sisa kas negara untuk bonus panitia merupakan tindak pidana korupsi penggelapan uang perbendaharaan dinas.</li><li><strong>E</strong>: Salah karena mentransfer kas dinas ke rekening pribadi merupakan tindak pidana penggelapan dalam jabatan dan pencucian uang negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 22.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Analitis", "question": "Dalam aplikasi sehari-hari, nilai Integritas ditunjukkan melalui ketaatan mematuhi sumpah jabatan yang diucapkan saat dilantik, di mana salah satu butir sumpah adalah tidak menerima pemberian atau menjanjikan apa pun yang terkait dengan jabatan (gratifikasi). Mengapa sumpah jabatan dipandang sebagai ikatan moral tertinggi yang melarang penerimaan gratifikasi bagi aparatur kementerian keuangan?", "options": ["Karena sumpah jabatan merupakan ikrar sakral di hadapan Tuhan Yang Maha Esa dan konstitusi yang mengikat nurani melebihi kontrak duniawi.", "Karena melanggar sumpah jabatan secara otomatis membatalkan seluruh ijazah pendidikan formal yang pernah diraih oleh aparatur dinas.", "Karena sumpah jabatan membebaskan aparatur dari kewajiban mematuhi instruksi tertulis menteri keuangan dalam pengelolaan anggaran.", "Agar instansi dapat menghemat anggaran pembinaan kepegawaian dengan meniadakan unit pengawasan kepatuhan internal kementerian.", "Karena sumpah jabatan hanya mengikat aparatur saat mengenakan seragam dinas batik dan tidak berlaku saat mengenakan kemeja putih."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sumpah jabatan adalah **ikrar sakral di hadapan Tuhan Yang Maha Esa dan bangsa** (**sacred covenant**), yang mengikat kesadaran spiritual dan moral aparatur untuk **menolak segala bentuk gratifikasi dan janji apa pun yang terkait dengan kewenangan jabatannya**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A menyajikan analisis filosofis dan yuridis yang paling tepat mengenai kedudukan sakral sumpah jabatan. Secara hukum tata negara dan etika kepegawaian (Undang-Undang ASN), pengucapan sumpah jabatan dilakukan dengan mengangkat kitab suci agama di hadapan para saksi dan Tuhan Yang Maha Esa, yang menegaskan bahwa amanah jabatan publik adalah mandat spiritual tertinggi yang tidak boleh dinodai oleh penerimaan suap, gratifikasi, atau kompromi materiil haram demi keuntungan pribadi. Rekam jejak pembinaan kepatuhan menegaskan bahwa penghayatan sumpah jabatan menjadi benteng spiritual paling kokoh dalam mencegah penyalahgunaan wewenang. Oleh sebab itu, ikrar sakral di hadapan Tuhan dan konstitusi merupakan alasan hakiki mengapa sumpah jabatan menjadi ikatan moral tertinggi.</p><p>Jawaban yang sesuai adalah <strong>A. Karena sumpah jabatan merupakan ikrar sakral di hadapan Tuhan Yang Maha Esa dan konstitusi yang mengikat nurani melebihi kontrak duniawi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena sanksi pelanggaran sumpah adalah hukuman disiplin berat dan pidana korupsi, bukan pembatalan ijazah perguruan tinggi.</li><li><strong>C</strong>: Salah karena sumpah jabatan justru mewajibkan ketaatan mutlak terhadap peraturan perundang-undangan dan instruksi sah kementerian.</li><li><strong>D</strong>: Salah karena penegakan sumpah jabatan tetap membutuhkan Unit Kepatuhan Internal yang aktif mengawasi integritas operasional dinas.</li><li><strong>E</strong>: Salah karena sumpah jabatan melekat pada jiwa raga aparatur seumur hidup masa dinasnya tanpa memandang jenis pakaian yang dikenakan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Analitis", "question": "Menaati aturan agama diakui sebagai salah satu bentuk konkret menjaga integritas aparatur kementerian keuangan. Keterkaitan teologis dan etis yang paling tepat antara ketaatan beragama dengan kejujuran pengelolaan keuangan negara adalah...", "options": ["Agama membolehkan korupsi anggaran belanja dinas asalkan sebagian uang hasil curian disumbangkan untuk membangun rumah ibadah megah.", "Ketaatan beragama menghapuskan kewajiban aparatur untuk mematuhi regulasi perbendaharaan dan undang-undang perpajakan kementerian.", "Ajaran agama mewajibkan pegawai untuk hanya melayani masyarakat pemohon yang memiliki kesamaan keyakinan akidah di loket dinas.", "Seluruh ajaran agama melarang keras kebohongan, pencurian hak publik, dan menuntut pertanggungjawaban akhir atas setiap harta negara.", "Agama memberikan kekebalan hukum bagi pemuka agama yang melakukan penyelewengan kas dana bantuan operasional sekolah di daerah."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Menaati aturan agama memperkokoh integritas karena **seluruh ajaran agama secara universal mengharamkan korupsi, kebohongan, dan pengkhianatan amanah rakyat**, serta mengajarkan bahwa **setiap rupiah kas negara akan dimintai pertanggungjawaban di hadapan Tuhan**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merangkum hubungan etika teologis dan profesionalisme perbendaharaan secara paling tepat, universal, dan selaras dengan doktrin integritas. Secara moralitas keagamaan di Indonesia, mengelola keuangan negara merupakan amanah suci yang dibiayai keringat rakyat banyak, di mana mengambil hak negara melalui manipulasi belanja atau menerima gratifikasi merupakan dosa besar pencurian hak publik yang tidak hanya dijatuhi sanksi penjara di dunia melainkan pertanggungjawaban berat di akhirat kelak. Bukti program penguatan integritas di kementerian membuktikan bahwa internalisasi nilai-nilai keagamaan yang luhur berhasil memperkuat kesadaran antikorupsi aparatur di seluruh penjuru satuan kerja. Maka dari itu, larangan universal korupsi dan pertanggungjawaban akhir di hadapan Tuhan menjelaskan kaitan agama dan integritas secara sempurna.</p><p>Jawaban yang sesuai adalah <strong>D. Seluruh ajaran agama melarang keras kebohongan, pencurian hak publik, dan menuntut pertanggungjawaban akhir atas setiap harta negara.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena seluruh agama menolak pencucian uang haram hasil korupsi dan memandangnya sebagai perbuatan keji yang terkutuk.</li><li><strong>B</strong>: Salah karena ketaatan beragama justru menuntut ketaatan pada hukum negara yang sah (taat ulil amri) dalam mengawal perbendaharaan.</li><li><strong>C</strong>: Salah karena ajaran agama menuntut keadilan sosial universal dan melarang diskriminasi primordial dalam melayani sesama manusia.</li><li><strong>E</strong>: Salah karena hukum negara berlaku setara bagi seluruh warga negara tanpa kekebalan hukum bagi pemuka agama yang korupsi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Aplikasi", "question": "Integritas dalam aplikasi sehari-hari mewajibkan aparatur untuk memanfaatkan jam kerja dinas secara produktif dan jujur. Tindakan seorang fungsional perbendaharaan yang paling mencerminkan integritas pemanfaatan jam kerja adalah...", "options": ["Mengisi daftar hadir elektronik di kantor pada pagi hari lalu pergi berbelanja di pasar swalayan hingga menjelang jam pulang dinas sore.", "Hadir tepat waktu, fokus menuntaskan verifikasi berkas perbendaharaan sepanjang jam kerja, dan menolak bermalas-malasan di meja dinas.", "Menitipkan kartu absensi elektronik kepada petugas keamanan kantor agar dirinya tetap tercatat hadir saat sedang berlibur ke luar kota.", "Mematikan sambungan telepon kantor dan mengunci pintu ruangan kerja dari dalam agar dapat tidur siang dengan tenang saat jam pelayanan.", "Menggunakan komputer dinas kantor untuk mengoperasikan bisnis toko daring pribadi dan melayani pembeli saat jam sibuk kantor dinas."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integritas jam kerja menuntut **kejujuran dan produktivitas penuh** (**productive time stewardship**): hadir tepat waktu, fokus menyelesaikan verifikasi belanja negara, serta **menolak segala bentuk korupsi waktu dan kemalasan dinas**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah tindakan yang paling berintegritas, disiplin, dan menghormati sumpah jabatan aparatur sipil negara. Secara etika kepegawaian dan hukum disiplin dinas, jam kerja operasional kantor dibiayai oleh uang rakyat melalui gaji pokok dan tunjangan kinerja, sehingga memanfaatkan waktu dinas secara fokus untuk menyelesaikan verifikasi dokumen perbendaharaan merupakan wujud nyata kejujuran menunaikan hak dan kewajiban secara halal. Hasil evaluasi penegakan kepatuhan kementerian membuktikan bahwa aparatur yang disiplin jam kerja memiliki output produktivitas tinggi dan terbebas dari sanksi pelanggaran disiplin. Oleh karenanya, hadir tepat waktu dan fokus bekerja merupakan cerminan sejati integritas jam kerja.</p><p>Jawaban yang sesuai adalah <strong>B. Hadir tepat waktu, fokus menuntaskan verifikasi berkas perbendaharaan sepanjang jam kerja, dan menolak bermalas-malasan di meja dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena keluyuran saat jam kerja dinas merupakan korupsi waktu dan pelanggaran disiplin berat yang memakan gaji buta.</li><li><strong>C</strong>: Salah karena menitipkan absensi merupakan tindak penipuan administratif dan pemalsuan data kehadiran dinas yang berakibat pemecatan.</li><li><strong>D</strong>: Salah karena tidur di ruangan terkunci saat jam kerja merupakan pemboikotan pelayanan publik yang merusak martabat birokrasi negara.</li><li><strong>E</strong>: Salah karena mengoperasikan bisnis pribadi dengan komputer dinas saat jam kerja merupakan penyalahgunaan aset dan waktu negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Analitis", "question": "Mematuhi sumpah jabatan dan menaati aturan agama membentengi aparatur dari perilaku koruptif. Di antara situasi kerja berikut, manakah skenario yang BUKAN merupakan pengamalan sumpah jabatan dan aturan agama di lingkungan kementerian keuangan?", "options": ["Petugas loket menolak dengan santun amplop uang pelicin dari wajib pajak dan menjelaskan bahwa pelayanan diberikan secara gratis.", "Auditor kepatuhan internal melaporkan secara objektif temuan pemborosan belanja dinas tanpa rasa takut menghadapi ancaman pimpinan.", "Bendahara menyalurkan seluruh dana beasiswa pendidikan anak pegawai berprestasi secara utuh tanpa memotong biaya administrasi.", "Petugas pemeriksa barang kepabeanan meneliti kontainer impor secara cermat guna mencegah masuknya komoditas haram narkotika ke tanah air.", "Pejabat pengadaan memenangkan perusahaan penyedia barang milik yayasan pribadinya dengan alasan uang keuntungannya untuk amal sedekah."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sumpah jabatan dan ajaran agama **melarang keras segala bentuk benturan kepentingan dan nepotisme**. Memenangkan perusahaan pribadi dengan dalih amal sedekah (**pious corruption/whitewashing**) merupakan **kejahatan korupsi yang melanggar sumpah jabatan dan agama**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah skenario pelanggaran berat yang mencoreng kesucian sumpah jabatan dan ajaran agama melalui kedok amal sedekah palsu. Secara hukum pengadaan barang/jasa pemerintah dan undang-undang tindak pidana korupsi, menyalahgunakan kewenangan jabatan untuk memenangkan usaha milik pribadi atau kerabat merupakan tindak pidana korupsi benturan kepentingan dalam pengadaan (conflict of interest in procurement), di mana niat amal sedekah tidak dapat membenarkan perbuatan melawan hukum yang merugikan keuangan negara dan persaingan usaha yang sehat. Fatwa dan ajaran agama secara tegas menegaskan bahwa sedekah dari harta hasil kecurangan adalah haram dan tertolak. Maka dari itu, memenangkan perusahaan sendiri demi sedekah jelas bertentangan dengan sumpah jabatan dan aturan agama.</p><p>Jawaban yang sesuai adalah <strong>E. Pejabat pengadaan memenangkan perusahaan penyedia barang milik yayasan pribadinya dengan alasan uang keuntungannya untuk amal sedekah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan penerapan nyata sumpah jabatan dalam menolak gratifikasi dan menaati ajaran agama untuk mencari rezeki yang halal.</li><li><strong>B</strong>: Merupakan bukti keberanian moral yang bersumber dari ketakutan kepada Tuhan dalam menegakkan kebenaran audit laporan keuangan.</li><li><strong>C</strong>: Merupakan wujud kejujuran dan amanah perbendaharaan dalam menyalurkan hak pendidikan anak bangsa tanpa pengurangan sepeser pun.</li><li><strong>D</strong>: Merupakan implementasi jihad kebangsaan aparatur dalam melindungi moral dan raga generasi muda bangsa dari bahaya racun narkoba.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Evaluatif", "question": "Seorang kepala kantor pelayanan perpajakan menyelenggarakan program 'Kajian Integritas dan Sumpah Jabatan' secara rutin setiap bulan yang memadukan nasihat agama antikorupsi dari pemuka agama independen dengan telaah titik rawan fraud perpajakan. Evaluasi yang paling tepat terhadap efektivitas program kepala kantor tersebut adalah...", "options": ["Program yang membuang waktu dinas karena pembinaan spiritual tidak memiliki dampak apa pun terhadap kejujuran aparatur di loket.", "Tindakan yang keliru karena urusan agama adalah hak privat yang dilarang keras dibahas di lingkungan kantor pemerintah republik indonesia.", "Langkah kepemimpinan yang sangat tepat karena memperkokoh benteng spiritual batiniah yang menopang kepatuhan sumpah jabatan dinas.", "Kebijakan yang tidak bijaksana karena pimpinan kantor seharusnya membiarkan pegawai mencari sendiri makna sumpah jabatan di internet.", "Program yang melanggar hukum kepegawaian karena pembinaan aparatur hanya boleh dilakukan melalui latihan fisik baris-berbaris militer."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Memadukan **pembinaan spiritual keagamaan independen** dengan **analisis titik rawan fraud operasional** merupakan **strategi kepemimpinan preventif yang sangat efektif** (**spiritual and operational integrity synergy**) dalam merawat kesucian sumpah jabatan aparatur.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C memberikan evaluasi manajerial yang paling tepat, bijaksana, dan selaras dengan karakteristik bangsa Indonesia yang berketuhanan Yang Maha Esa (Sila Pertama Pancasila). Secara psikologi moral, mengaitkan amanah pencegahan suap di kantor dengan nilai-nilai pertanggungjawaban spiritual di hadapan Tuhan Yang Maha Esa terbukti efektif membangkitkan rasa takut berbuat dosa dan membentengi hati nurani pegawai saat menghadapi godaan uang suap yang besar di lapangan. Evaluasi program pembangunan zona integritas membuktikan bahwa unit kerja yang menyelenggarakan pembinaan spiritual rutin mencatatkan indeks persepsi korupsi yang bersih secara konsisten. Oleh karena itu, penguatan benteng spiritual batiniah merupakan langkah kepemimpinan yang sangat brilian.</p><p>Jawaban yang sesuai adalah <strong>C. Langkah kepemimpinan yang sangat tepat karena memperkokoh benteng spiritual batiniah yang menopang kepatuhan sumpah jabatan dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena pembinaan spiritual terbukti secara ilmiah memiliki dampak pencegahan korupsi yang sangat kuat di negara religius.</li><li><strong>B</strong>: Salah karena nilai Ketuhanan Yang Maha Esa merupakan fondasi moral dasar negara yang melandasi sumpah jabatan seluruh aparatur sipil.</li><li><strong>D</strong>: Salah karena kepemimpinan bertanggung jawab memfasilitasi pembinaan moral staf, bukan menelantarkannya tanpa bimbingan dinas.</li><li><strong>E</strong>: Salah karena pembinaan aparatur modern memprioritaskan integritas karakter akal budi dan spiritual, bukan semata baris-berbaris fisik.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf kepegawaian di kantor pelayanan perbendaharaan ditugaskan mengelola mesin fotokopi dan persediaan kertas dinas. Menjelang tahun ajaran baru sekolah, kerabat keluarganya meminta staf tersebut memfotokopi ratusan lembar buku pelajaran sekolah anak menggunakan kertas dan tinta kantor. Tindakan yang paling mencerminkan kepatuhan terhadap sumpah jabatan dan nilai Integritas adalah...", "options": ["Memfotokopikan buku tersebut pada malam hari saat kantor sepi agar tidak ada rekan kerja atau petugas keamanan yang mengetahuinya.", "Menolak secara santun permintaan kerabat dan menjelaskan bahwa mesin serta kertas kantor adalah barang milik negara untuk dinas.", "Memfotokopikan buku tersebut dengan memungut biaya separuh harga pasar dari kerabat untuk dimasukkan ke dalam dompet pribadi staf.", "Memberikan satu rim kertas dinas kantor kepada kerabat tersebut untuk dibawa pulang ke rumah sebagai hadiah bantuan sosial keluarga.", "Merusak mesin fotokopi kantor secara sengaja agar kerabat tidak dapat meminta bantuan memfotokopi buku sekolah keluarganya."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sumpah jabatan mewajibkan **penjagaan barang milik negara (BMN) dari penggunaan non-dinas**. Menolak pemanfaatan fasilitas kantor untuk urusan privat keluarga (**protecting state property from private exploitation**) merupakan bukti nyata integritas sehari-hari.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah tindakan yang paling berintegritas, berani, dan mencerminkan kejujuran mengelola fasilitas negara sekecil apa pun. Secara regulasi pengelolaan BMN dan kode etik aparatur sipil negara, mesin fotokopi, tinta, dan kertas kantor dibeli menggunakan uang pajak rakyat khusus untuk keperluan pelayanan publik kedinasan, di mana memanfaatkannya untuk urusan privat keluarga—meskipun buku sekolah anak—merupakan bentuk korupsi aset kecil (petty corruption) yang mencederai sumpah jabatan aparatur. Sikap tegas menolak dan mengarahkan kerabat ke jasa fotokopi swasta membuktikan bahwa staf tersebut memiliki integritas tanpa kompromi. Oleh sebab itu, menolak secara santun dan menjelaskan aturan dinas mencerminkan kepatuhan sumpah jabatan sejati.</p><p>Jawaban yang sesuai adalah <strong>B. Menolak secara santun permintaan kerabat dan menjelaskan bahwa mesin serta kertas kantor adalah barang milik negara untuk dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mencetak sembunyi-sembunyi pada malam hari merupakan tindak pidana pencurian aset kantor dan kemunafikan dinas.</li><li><strong>C</strong>: Salah karena menjual fasilitas kantor untuk keuntungan pribadi merupakan tindak pidana korupsi penggelapan aset inventaris negara.</li><li><strong>D</strong>: Salah karena memberikan kertas dinas untuk keluarga merupakan penggelapan barang milik negara yang melanggar hukum perbendaharaan.</li><li><strong>E</strong>: Salah karena merusak mesin kantor merupakan tindak pidana perusakan aset negara (vandalism) yang merugikan operasional kantor dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan prinsip bahwa semua pegawai kementerian keuangan telah disumpah untuk tidak menerima pemberian apa pun terkait jabatan, sebuah kantor wilayah berniat merancang 'Pakta Integritas Mitra Kerja' (Vendor Integrity Compact). Klausul pengendalian yang paling komprehensif untuk mencegah gratifikasi dari pihak rekanan adalah...", "options": ["Kewajiban rekanan menandatangani larangan memberi hadiah apa pun kepada pegawai disertai sanksi pemutusan kontrak dan daftar hitam.", "Kewajiban rekanan mentransfer uang partisipasi hari raya ke rekening yayasan yang dikelola oleh istri para pejabat kantor dinas.", "Ketentuan bahwa rekanan diperbolehkan memberikan hadiah barang mewah asalkan diserahkan di luar pagar batas gedung kantor dinas.", "Klausul yang membebaskan rekanan dari audit kepatuhan pengadaan apabila telah memberikan cinderamata emas kepada kepala kantor.", "Kewajiban rekanan menyediakan mobil dinas pribadi baru bagi pejabat pembuat komitmen setiap kali memenangkan tender lelang proyek."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Pakta Integritas Mitra Kerja (**Vendor Integrity Compact**) mewajibkan komitmen dua arah: **larangan keras memberi suap/hadiah dalam bentuk apa pun**, yang ditegakkan dengan **sanksi pemutusan kontrak kerja dan sanksi daftar hitam** (**blacklisting**) bagi rekanan yang melanggar.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A menyajikan sintesis klausul pencegahan korupsi kemitraan yang paling berdaya hukum, tegas, dan berstandar internasional. Secara hukum pengadaan barang/jasa pemerintah, pemberantasan gratifikasi tidak cukup hanya menuntut integritas dari pihak aparatur negara, melainkan wajib mengikat pihak vendor swasta dengan klausul pembatalan kontrak sepihak dan penetapan daftar hitam (blacklist) selama bertahun-tahun apabila terbukti mencoba menyuap atau memberikan hadiah kepada pejabat kementerian. Fakta penegakan integritas pengadaan di kementerian keuangan membuktikan bahwa klausul daftar hitam efektif membendung inisiatif pemberian uang pelicin dari rekanan. Oleh karena itu, larangan hadiah disertai sanksi pemutusan kontrak dan blacklist merupakan rancangan terbaik.</p><p>Jawaban yang sesuai adalah <strong>A. Kewajiban rekanan menandatangani larangan memberi hadiah apa pun kepada pegawai disertai sanksi pemutusan kontrak dan daftar hitam.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena mewajibkan transfer ke rekening yayasan istri pejabat merupakan pelembagaan pemerasan gratifikasi ilegal yang korup.</li><li><strong>C</strong>: Salah karena pemberian hadiah di luar pagar kantor tetap merupakan tindak pidana korupsi penyuapan tanpa memandang lokasi serah terima.</li><li><strong>D</strong>: Salah karena membebaskan audit demi cinderamata emas merupakan permufakatan jahat tindak pidana korupsi penyuapan kelas berat.</li><li><strong>E</strong>: Salah karena mewajibkan penyediaan mobil bagi PPK merupakan tindak pidana pemerasan dalam jabatan yang diancam pidana penjara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Analitis", "question": "Kepatuhan terhadap sumpah jabatan melarang penerimaan gratifikasi yang berkaitan dengan jabatan dan bertentangan dengan kewajiban dinas. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai aturan gratifikasi di lingkungan kementerian keuangan?", "options": ["Setiap penerimaan gratifikasi yang berhubungan dengan jabatan wajib ditolak secara santun atau dilaporkan kepada UPG kementerian.", "Pemberian cinderamata dari pihak yang sedang diperiksa pajaknya dianggap sebagai gratifikasi suap yang melanggar sumpah jabatan.", "Aparatur kementerian keuangan diperbolehkan menerima uang terima kasih dari masyarakat asalkan jumlahnya di bawah batas upah minimum.", "Pelaporan gratifikasi kepada Komisi Pemberantasan Korupsi (KPK) dalam batas waktu tiga puluh hari kerja melepaskan ancaman sanksi pidana.", "Pemberian fasilitas akomodasi dan transportasi gratis dari rekanan lelang kepada panitia tender merupakan bentuk gratifikasi terlarang."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kementerian Keuangan menganut prinsip **nol toleransi terhadap gratifikasi** (**zero tolerance policy**). Menerima uang tanda terima kasih dalam jumlah berapa pun—**sekalipun di bawah upah minimum**—merupakan **pelanggaran berat terhadap sumpah jabatan dan kode etik dinas**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C adalah simpulan yang salah, menyesatkan, dan menjadi celah bagi normalisasi pungutan liar di lingkungan birokrasi. Secara regulasi pengendalian gratifikasi Kementerian Keuangan (PMK tentang Pengendalian Gratifikasi) dan Undang-Undang Tipikor, aparatur kementerian dilarang menerima uang tunai dari masyarakat pemohon layanan dalam nominal berapa pun (zero tolerance), di mana menerima uang pelicin—meskipun seratus ribu rupiah—tetap merupakan pelanggaran kode etik integritas dan tindak pidana suap. Laporan penindakan kepatuhan internal menegaskan bahwa oknum aparatur yang menerima uang terima kasih di loket langsung dijatuhi sanksi hukuman disiplin pembebasan dari jabatan. Oleh karena itu, menyatakan boleh menerima uang di bawah UMR adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>C. Aparatur kementerian keuangan diperbolehkan menerima uang terima kasih dari masyarakat asalkan jumlahnya di bawah batas upah minimum.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan pernyataan yang benar karena menolak atau melapor ke UPG merupakan standar emas kepatuhan gratifikasi kementerian.</li><li><strong>B</strong>: Merupakan pernyataan yang benar karena pemberian hadiah dari auditee saat proses pemeriksaan merupakan delik suap yang nyata.</li><li><strong>D</strong>: Merupakan ketentuan yuridis yang sah dalam Pasal 12C UU Tipikor mengenai pelepasan ancaman pidana melalui pelaporan ke KPK.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena pembiayaan akomodasi oleh vendor tender merusak independensi panitia lelang negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Evaluatif", "question": "Seorang staf pelaksana di bagian perbendaharaan melapor kepada kepala kantornya bahwa ia baru saja menerima transfer uang sebesar lima juta rupiah dari bendahara satuan kerja mitra tanpa sepengetahuannya. Kepala kantor segera mengapresiasi kejujuran staf tersebut, mendampinginya membuat laporan resmi ke Unit Pengendalian Gratifikasi (UPG), dan menginstruksikan pengembalian dana via bank. Penilaian yang paling tepat terhadap kepemimpinan kepala kantor tersebut adalah...", "options": ["Tindakan yang keliru karena pimpinan seharusnya memarahi staf tersebut yang dianggap bodoh karena menolak rezeki uang tunai cuma-cuma.", "Keputusan yang membuang waktu dinas karena uang lima juta rupiah seharusnya dibagi dua secara rahasia di dalam ruangan kepala kantor.", "Langkah yang merugikan korps dinas karena melaporkan gratifikasi ke UPG membuat kantor dinilai sebagai sarang korupsi oleh kementerian.", "Kebijakan yang tidak bijaksana karena kepala kantor seharusnya menyuruh staf membelikan tiket liburan keluarga pimpinan kantor wilayah.", "Kepemimpinan yang sangat tepat dan melindungi bawahan karena menegakkan kepatuhan hukum dan merawat integritas nurani aparatur."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kepemimpinan yang berintegritas **melindungi bawahan yang jujur** (**protective leadership**) dengan mengapresiasi pelaporan inisiatif staf, mendampingi proses pelaporan resmi ke UPG, serta memastikan pengembalian dana dilakukan secara sah dan akuntabel.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E memberikan penilaian evaluatif yang paling tepat, bijaksana, dan menjadi teladan kepemimpinan nilai yang sejati. Secara tata kelola kepegawaian dan perlindungan hukum aparatur, ketika pegawai berinisiatif jujur melaporkan transfer uang gelap yang tidak dimintanya, pimpinan berkewajiban memberikan perlindungan psikologis dan pendampingan administratif pelaporan ke UPG agar pegawai terbebas dari ancaman delik suap KPK dan sistem pembukuan kas mitra dapat diluruskan. Fakta di kementerian membuktikan bahwa dukungan aktif pimpinan terhadap pelaporan gratifikasi menumbuhkan iklim keterbukaan dan keberanian moral staf di seluruh ruangan kantor. Oleh sebab itu, kepemimpinan kepala kantor tersebut mencerminkan penegakan sumpah jabatan yang sangat terpuji.</p><p>Jawaban yang sesuai adalah <strong>E. Kepemimpinan yang sangat tepat dan melindungi bawahan karena menegakkan kepatuhan hukum dan merawat integritas nurani aparatur.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mencaci maki pegawai yang jujur mencerminkan mentalitas korup yang merusak karakter integritas generasi muda dinas.</li><li><strong>B</strong>: Salah karena membagi uang suap secara rahasia merupakan tindak pidana korupsi permufakatan jahat penyuapan perbendaharaan.</li><li><strong>C</strong>: Salah karena pelaporan gratifikasi justru membuktikan tingginya integritas kantor dan menjadi indikator keberhasilan pembangunan WBK.</li><li><strong>D</strong>: Salah karena menyalahgunakan uang gelap untuk liburan keluarga pimpinan merupakan tindak pidana korupsi pemerasan dan suap jabatan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 23", "difficulty": "HOTS • Aplikasi", "question": "Saat melakukan pemeriksaan kepatuhan fisik pada kawasan berikat industri manufaktur, seorang fungsional pemeriksa bea dan cukai ditawari oleh direktur perusahaan untuk menginap di hotel bintang lima secara gratis dan dijemput mobil mewah berfasilitas sopir pribadi selama masa penugasan audit. Sikap yang paling mencerminkan kepatuhan terhadap sumpah jabatan adalah...", "options": ["Menerima tawaran hotel mewah tersebut asalkan lobi hotel menyediakan menu makanan tradisional khas kampung halaman pemeriksa.", "Menyetujui fasilitas mobil mewah tersebut dengan syarat sopir pribadi perusahaan bersedia mengantar anggota keluarga pemeriksa berbelanja.", "Meminta direktur perusahaan mengganti fasilitas hotel mewah dengan uang tunai yang diserahkan di tempat parkir bawah tanah hotel.", "Menolak secara santun seluruh fasilitas perusahaan, menginap di hotel sederhana sesuai tarif resmi uang harian DIPA, dan menjaga independensi.", "Menerima seluruh fasilitas mewah tersebut dan berjanji dalam hati untuk tetap memeriksa pembukuan perusahaan secara adil dan jujur."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 23", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 23</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sumpah jabatan menuntut **independensi mutlak dari pengaruh auditee** (**absolute auditing independence**). Menolak fasilitas akomodasi mewah rekanan dan **menggunakan uang harian resmi dinas** (**per-diem budget**) menjaga pemeriksa dari konflik kepentingan dan jeratan gratifikasi suap.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D adalah tindakan aplikasi nilai integritas yang paling profesional, lurus, dan memenuhi standar kode etik audit kementerian keuangan. Secara standar pemeriksaan kepabeanan dan undang-undang tipikor, biaya transportasi dan akomodasi audit dinas telah dialokasikan secara sah dalam DIPA negara, sehingga menerima fasilitas akomodasi mewah dari pihak yang sedang diaudit merupakan pelanggaran independensi berat yang dapat melunakkan ketegasan temuan pelanggaran cukai. Fakta pemeriksaan membuktikan bahwa auditor yang tinggal di akomodasi resmi mandiri mampu membongkar kecurangan pajak kawasan berikat secara objektif tanpa rasa canggung atau beban utang budi. Oleh karena itu, menolak fasilitas dan menggunakan biaya resmi DIPA mencerminkan kepatuhan sumpah jabatan penutup sub-paket ini.</p><p>Jawaban yang sesuai adalah <strong>D. Menolak secara santun seluruh fasilitas perusahaan, menginap di hotel sederhana sesuai tarif resmi uang harian DIPA, dan menjaga independensi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menerima hotel mewah dengan dalih menu makanan lokal tetap merupakan penerimaan gratifikasi fasilitas yang merusak independensi.</li><li><strong>B</strong>: Salah karena memanfaatkan fasilitas mobil perusahaan untuk keluarga merupakan tindak pidana korupsi pemerasan dan gratifikasi terlarang.</li><li><strong>C</strong>: Salah karena meminta kompensasi uang tunai di tempat parkir merupakan tindak pidana korupsi pemerasan dalam jabatan penegakan hukum.</li><li><strong>E</strong>: Salah karena janji dalam hati tidak menghapuskan status yuridis penerimaan gratifikasi ilegal dan pelemahan psikologis independensi audit.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 23.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Analitis", "question": "Seorang profesional sejati ditandai dengan keinginan mengejar kualitas dan cita-cita dalam profesi, serta memiliki rasa bangga dan percaya diri akan profesi yang dipegangnya. Mengapa rasa bangga dan percaya diri terhadap profesi (professional pride) menjadi motor penggerak utama lahirnya kinerja unggul aparatur kementerian keuangan?", "options": ["Karena rasa bangga profesi membuat aparatur berhak merendahkan profesi aparat penegak hukum lain yang bertugas di perbatasan dinas.", "Karena kebanggaan profesional menghapuskan kewajiban aparatur untuk mengikuti pelatihan uji kompetensi kepegawaian berkala dinas.", "Karena rasa percaya diri yang tinggi memberikan kekebalan hukum bagi aparatur dari segala bentuk pengawasan audit inspektorat jenderal.", "Kebanggaan profesi melahirkan dedikasi batiniah untuk menjaga kehormatan korps melalui pencapaian mutu kerja terbaik tanpa cela salah.", "Karena rasa bangga profesi memungkinkan aparatur memungut tarif pelayanan publik yang jauh lebih mahal dibanding instansi daerah."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Seorang profesional memiliki **kebanggaan dan percaya diri akan profesinya** (**professional pride and confidence**), yang bertindak sebagai mesin pendorong intrinsik untuk **mengejar mutu kerja tertinggi dan menjaga kehormatan korps** pengelola fiskal negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D merangkum hubungan psikologis antara rasa bangga profesi dengan kinerja unggul aparatur secara paling tepat dan ilmiah. Secara teori motivasi kerja (intrinsic motivation), ketika seorang pegawai merasa bangga menyandang profesi mulia sebagai penjaga kedaulatan keuangan negara, ia tidak akan bekerja sekadarnya atau bersikap ceroboh, melainkan terpanggil secara moral untuk memberikan karya akuntansi atau penetapan kepabeanan yang presisi dan sempurna demi menjaga marwah kehormatan korpsnya. Hasil kajian kinerja sumber daya manusia kementerian membuktikan bahwa aparatur dengan professional pride tinggi memiliki produktivitas kerja dan ketelitian analitis yang jauh melampaui rata-rata. Oleh sebab itu, lahirnya dedikasi menjaga kehormatan korps merupakan alasan utama esensialnya kebanggaan profesi.</p><p>Jawaban yang sesuai adalah <strong>D. Kebanggaan profesi melahirkan dedikasi batiniah untuk menjaga kehormatan korps melalui pencapaian mutu kerja terbaik tanpa cela salah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena kebanggaan profesional sejati melahirkan kerendahan hati dan sinergi setara, bukan arogansi merendahkan profesi lain.</li><li><strong>B</strong>: Salah karena seorang profesional yang bangga justru haus belajar dan antusias mengikuti pembaruan kompetensi secara berkelanjutan.</li><li><strong>C</strong>: Salah karena kebanggaan profesional menjunjung tinggi akuntabilitas dan keterbukaan terhadap pengawasan audit inspektorat jenderal.</li><li><strong>E</strong>: Salah karena instansi fiskal adalah pelayan publik nirlaba yang tarif resminya diatur undang-undang dan dilarang memungut biaya liar.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Analitis", "question": "Nilai Profesionalisme dalam Kementerian Keuangan dinyatakan dengan bekerja tuntas dan akurat atas dasar kompetensi terbaik dengan penuh tanggung jawab dan komitmen yang tinggi. Keterkaitan antara 'kompetensi terbaik' dengan 'komitmen tinggi' dalam mencegah kegagalan target APBN adalah...", "options": ["Kompetensi terbaik berarti pandai berdebat di media televisi sedangkan komitmen tinggi berarti menyetujui seluruh permintaan belanja.", "Kompetensi menyediakan keahlian teknis presisi sementara komitmen memberikan daya tahan moral untuk bekerja tuntas tanpa menyerah.", "Keduanya merupakan jargon administratif seremonial yang tidak memiliki keterkaitan kausalitas dengan realisasi anggaran negara dinas.", "Komitmen tinggi hanya diwajibkan bagi staf pelaksana honorer sedangkan kompetensi terbaik merupakan monopoli pejabat pimpinan pusat.", "Kompetensi terbaik menghapuskan kewajiban aparatur untuk bekerja sama dengan rekan seksi lain dalam lingkungan kantor kementerian."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Dalam nilai **Profesionalisme**, **kompetensi terbaik** menyediakan **kapasitas teknis dan keahlian analitis presisi** (**technical capability**), sedangkan **komitmen tinggi** memberikan **daya tahan moral dan tanggung jawab pantang menyerah** (**resilience and accountability**) dalam menuntaskan target fiskal negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah analisis komparasi konseptual yang paling presisi mengenai sinergi kompetensi dan komitmen dalam definisi Profesionalisme. Secara manajemen kinerja publik, memiliki kompetensi tinggi tanpa komitmen akan melahirkan aparatur pintar yang malas dan mudah putus asa saat menghadapi kendala sistem, sebaliknya memiliki komitmen tinggi tanpa kompetensi akan melahirkan aparatur yang rajin namun menghasilkan perhitungan anggaran yang keliru dan membahayakan kas negara. Perpaduan harmonis antara keahlian teknis (kompetensi) dan kegigihan tanggung jawab (komitmen) inilah yang menjamin keberhasilan penutupan buku APBN tepat waktu tanpa anomali. Maka dari itu, keahlian teknis yang dipadukan dengan daya tahan moral mencerminkan hakikat Profesionalisme sejati.</p><p>Jawaban yang sesuai adalah <strong>B. Kompetensi menyediakan keahlian teknis presisi sementara komitmen memberikan daya tahan moral untuk bekerja tuntas tanpa menyerah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena kompetensi adalah penguasaan keahlian substansi riil, bukan kefasihan berdebat kosong di layar televisi publik.</li><li><strong>C</strong>: Salah karena sinergi kompetensi dan komitmen terbukti secara empiris menjadi faktor penentu opini Wajar Tanpa Pengecualian (WTP).</li><li><strong>D</strong>: Salah karena kompetensi terbaik dan komitmen tinggi mengikat seluruh tingkatan jabatan aparatur dari pelaksana hingga menteri.</li><li><strong>E</strong>: Salah karena profesionalisme modern menuntut kerja sama tim yang sinergis dan menolak sikap arogan menyendiri tanpa koordinasi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Analitis", "question": "Perilaku utama nilai Profesionalisme menuntut aparatur mempunyai keahlian dan pengetahuan yang luas serta bekerja dengan hati. Di antara perilaku kerja berikut, manakah tindakan yang BUKAN merupakan wujud dari bekerja dengan hati dalam konteks pelayanan publik kementerian keuangan?", "options": ["Mendengarkan keluhan wajib pajak yang sedang mengalami kesulitan likuiditas usaha secara empatik dan memberikan solusi restrukturisasi sah.", "Melakukan telaah dokumen perbendaharaan dengan teliti dan penuh dedikasi demi mengamankan dana bantuan operasional sekolah bagi anak bangsa.", "Membimbing satuan kerja daerah perbatasan dengan sabar hingga kendala teknis pencairan dana penanganan stunting balita desa teratasi.", "Membantu eksportir UMKM memahami regulasi kepabeanan secara tulus agar produk kerajinan rakyat mampu menembus pasar luar negeri.", "Bekerja secara asal-asalan, melempar berkas permohonan dinas masyarakat ke lantai loket, dan memarahi pemohon yang bertanya alur berkas."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku utama **bekerja dengan hati** (**working with heart and soul**) menuntut **empati, ketulusan, kesabaran, dan dedikasi penuh** dalam melayani masyarakat. Bersikap kasar, melempar berkas, dan memarahi warga merupakan **pelanggaran berat kode etik profesionalisme**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah contoh tindakan yang tidak bermoral dan merusak martabat nilai Profesionalisme aparatur sipil negara di hadapan rakyat pembayar pajak. Secara etika pelayanan publik, bekerja dengan hati bermakna menghadirkan rasa kemanusiaan dan kepedulian mendalam bahwa di balik setiap berkas kertas dinas terdapat hak hidup rakyat yang menggantungkan harapannya kepada negara, sehingga sikap kasar, melempar berkas, dan memarahi warga merupakan perwujudan birokrasi berhati batu yang bertentangan secara frontal dengan nilai kementerian. Hasil penindakan inspektorat kementerian membuktikan bahwa aparatur yang bersikap kasar di loket langsung dicopot dari tugas pelayanan publik. Oleh sebab itu, bekerja asal-asalan dan memarahi warga jelas bukan wujud bekerja dengan hati.</p><p>Jawaban yang sesuai adalah <strong>E. Bekerja secara asal-asalan, melempar berkas permohonan dinas masyarakat ke lantai loket, dan memarahi pemohon yang bertanya alur berkas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Merupakan penerapan nyata bekerja dengan hati dalam memberikan bimbingan solutif dan empatik kepada pelaku usaha yang kesulitan.</li><li><strong>B</strong>: Merupakan bukti dedikasi tulus aparatur perbendaharaan dalam mengamankan hak pendidikan jutaan anak sekolah di seluruh pelosok nusantara.</li><li><strong>C</strong>: Merupakan wujud nyata kemanusiaan dan kehangatan hati dalam mempercepat penyaluran gizi balita demi masa depan bangsa Indonesia.</li><li><strong>D</strong>: Merupakan manifestasi ketulusan mendampingi usaha rakyat kecil agar mampu berdaya saing mandiri di kancah perdagangan internasional.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Aplikasi", "question": "Seorang bendahara pengeluaran kantor pelayanan fiskal sedang menyusun Berita Acara Rekonsiliasi Kas pada akhir tahun anggaran. Jam dinas kantor telah berakhir pada pukul 17.00, namun bendahara menemukan adanya selisih saldo kas pembukuan sebesar dua ratus rupiah dibanding saldo fisik rekening bank. Tindakan yang paling mencerminkan prinsip bekerja tuntas dan akurat atas dasar kompetensi terbaik adalah...", "options": ["Tetap berada di kantor menelusuri mutasi transaksi pembukuan hingga selisih dua ratus rupiah ditemukan akarnya dan neraca seimbang sah.", "Menambahkan uang dua ratus rupiah dari saku celana pribadi ke dalam brankas kas dinas kantor tanpa melakukan penelusuran pembukuan.", "Menghapus lembar catatan mutasi yang berselisih dan memalsukan tanda tangan pimpinan pada lembar berita acara rekonsiliasi kas dinas.", "Menutup buku kas begitu saja dan pulang ke rumah dengan anggapan bahwa uang dua ratus rupiah adalah nominal yang sangat remeh dinas.", "Menyalahkan pihak bank persepsi atas ketidaksesuaian saldo kas dan memutus hubungan kemitraan dinas secara sepihak pada malam hari."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Prinsip **bekerja tuntas dan akurat** menuntut **ketelitian tanpa toleransi selisih** (**zero discrepancy precision**). Meskipun selisih hanya bernilai kecil (dua ratus rupiah), bendahara profesional wajib **menelusuri akar mutasi hingga tuntas secara akuntansi**, bukan menutupinya dengan uang saku pribadi.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi A adalah tindakan yang paling profesional, presisi, dan memenuhi standar akuntansi pemerintahan yang berlaku. Secara teori audit perbendaharaan negara, selisih kas—sekalipun hanya bernilai dua ratus rupiah—dapat menjadi indikasi adanya transaksi ganda atau kekeliruan pembukuan bernilai jutaan rupiah yang saling menutupi (compensating errors), sehingga menelusuri transaksi hingga tuntas dan seimbang secara sah membuktikan penguasaan kompetensi terbaik dan komitmen tanggung jawab tanpa kompromi. Pengalaman bendahara teladan di kementerian membuktikan bahwa kedisiplinan akurasi hingga digit rupiah terkecil berhasil mengamankan opini WTP institusi negara. Maka dari itu, menelusuri hingga nihil selisih merupakan wujud sejati bekerja tuntas dan akurat.</p><p>Jawaban yang sesuai adalah <strong>A. Tetap berada di kantor menelusuri mutasi transaksi pembukuan hingga selisih dua ratus rupiah ditemukan akarnya dan neraca seimbang sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Salah karena menambal selisih pembukuan dengan uang pribadi melanggar standar akuntansi perbendaharaan dan menutupi kekeliruan sistemik.</li><li><strong>C</strong>: Salah karena memalsukan tanda tangan pimpinan dan menghapus mutasi merupakan tindak pidana pemalsuan dokumen negara yang berat.</li><li><strong>D</strong>: Salah karena menyepelekan selisih kas mencerminkan kecerobohan profesional yang melanggar prinsip kehati-hatian akuntansi negara.</li><li><strong>E</strong>: Salah karena menyalahkan perbankan dan memutus kontrak sepihak merupakan arogansi emosional yang melanggar nilai Sinergi dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Evaluatif", "question": "Seorang kepala kantor wilayah instansi fiskal mendapati bahwa staf pelaksananya mengalami kejenuhan dan krisis kepercayaan diri akibat beban target penerimaan yang berat. Pimpinan memutuskan untuk meluncurkan program pembinaan talenta muda, memfasilitasi beasiswa sertifikasi keahlian profesi internasional, dan memberikan penghargaan bagi analis terbaik. Penilaian yang paling tepat terhadap kepemimpinan kepala kantor wilayah tersebut adalah...", "options": ["Keputusan yang keliru karena menyekolahkan pegawai dan memberikan sertifikasi profesi internasional hanya membuang anggaran kantor.", "Tindakan yang memanjakan pegawai karena staf pelaksana seharusnya diancam dengan hukuman mutasi ke pulau terpencil agar bekerja giat.", "Kepemimpinan transformasional yang sangat tepat karena menumbuhkan kompetensi terbaik dan memulihkan rasa bangga akan profesi dinas.", "Langkah yang melanggar hukum kepegawaian karena sertifikasi keahlian profesi keuangan hanya boleh dimiliki oleh menteri keuangan pusat.", "Kebijakan yang tidak bijaksana karena pimpinan kantor wilayah seharusnya menyuruh seluruh staf menghafal visi misi kantor sepanjang hari."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Membangun nilai Profesionalisme menuntut **kepemimpinan transformasional** (**transformational leadership**) yang berinvestasi pada **pengembangan kompetensi terbaik staf** (**competency enhancement**) serta **memulihkan rasa bangga dan percaya diri akan profesinya** (**fostering professional pride**).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C memberikan penilaian evaluatif yang paling tepat, progresif, dan berlandaskan manajemen talenta sektor publik modern. Secara psikologi keorganisasian, kejenuhan dan hilangnya rasa percaya diri staf tidak dapat disembuhkan dengan ancaman mutasi melainkan membutuhkan pengakuan martabat dan pembekalan keahlian profesional berstandar internasional yang memulihkan kebanggaan diri mereka sebagai pengawal kedaulatan fiskal negara. Rekam jejak alumni beasiswa kementerian keuangan membuktikan bahwa lulusan sertifikasi internasional berhasil melahirkan inovasi tata kelola yang melipatgandakan penerimaan negara secara akuntabel. Oleh sebab itu, program pembinaan talenta dan sertifikasi profesi merupakan keputusan kepemimpinan yang sangat brilian.</p><p>Jawaban yang sesuai adalah <strong>C. Kepemimpinan transformasional yang sangat tepat karena menumbuhkan kompetensi terbaik dan memulihkan rasa bangga akan profesi dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena investasi pada sertifikasi keahlian sumber daya manusia merupakan pilar utama keberlanjutan profesionalisme kementerian.</li><li><strong>B</strong>: Salah karena ancaman mutasi fisik melahirkan iklim ketakutan toksik yang justru mematikan inisiatif inovasi dan memperburuk kinerja.</li><li><strong>D</strong>: Salah karena regulasi kementerian keuangan secara eksplisit mendorong seluruh jajaran fungsional untuk meraih sertifikasi keahlian resmi.</li><li><strong>E</strong>: Salah karena hafalan tekstual visi misi tanpa pembekalan keahlian analitis tidak akan mampu memecahkan kompleksitas target penerimaan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Aplikasi", "question": "Sebuah kantor pelayanan kepabeanan di pulau terpencil dilanda musibah gempa bumi yang merusak sebagian ruang arsip dokumen. Dalam situasi darurat tersebut, datang seorang pengusaha perikanan lokal yang memohon izin pemuatan kontainer ikan beku ekspor agar hasil tangkapan ratusan nelayan tradisional tidak membusuk. Sikap aparatur kepabeanan yang paling mencerminkan prinsip bekerja dengan hati atas dasar kompetensi terbaik adalah...", "options": ["Mengusir pengusaha tersebut keluar area pelabuhan dengan alasan seluruh pegawai sedang berduka menghadapi musibah gempa bumi kantor.", "Menerapkan prosedur pelayanan darurat terakreditasi, melakukan pemeriksaan dokumen secara cermat di pos darurat, dan mengizinkan ekspor sah.", "Meminta uang suap kemanusiaan sebesar lima puluh juta rupiah kepada pengusaha perikanan sebagai biaya pengganti kerusakan gedung dinas.", "Membiarkan kontainer ikan beku tersebut membusuk di pelabuhan agar pengusaha perikanan ikut merasakan penderitaan gempa bumi kantor.", "Menyita seluruh kontainer ikan beku tersebut untuk dibagikan secara gratis kepada keluarga pribadi para pegawai kantor kepabeanan."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Bekerja dengan hati memadukan **empati kemanusiaan kepada nasib rakyat** dengan **kompetensi keahlian mitigasi darurat** (**disaster service continuity**), mengoperasikan prosedur darurat sah agar hasil jerih payah nelayan terselamatkan tanpa melanggar kepatuhan hukum kepabeanan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi B adalah tindakan yang paling heroik, berintegritas, dan mencerminkan kematangan nilai Profesionalisme aparatur negara di saat krisis. Secara etika pelayanan publik dan regulasi kepabeanan, musibah alam tidak boleh menjadi pembenar untuk melumpuhkan ekonomi nelayan kecil, di mana kompetensi terbaik aparatur diuji pada kemampuannya mengoperasikan protokol pelayanan tanggap darurat (business continuity plan) di tenda lapangan guna memeriksa dokumen ikan ekspor secara akurat dan mengizinkan pemuatan kontainer sah. Keberhasilan pelayanan darurat kepabeanan di wilayah bencana membuktikan bahwa dedikasi bekerja dengan hati berhasil menyelamatkan devisa ekspor jutaan dolar milik nelayan bangsa. Maka dari itu, memeriksa via pos darurat dan mengizinkan ekspor sah mencerminkan profesionalisme sejati.</p><p>Jawaban yang sesuai adalah <strong>B. Menerapkan prosedur pelayanan darurat terakreditasi, melakukan pemeriksaan dokumen secara cermat di pos darurat, dan mengizinkan ekspor sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena mengusir pelaku usaha perikanan mencerminkan matinya empati kemanusiaan aparatur terhadap nasib nelayan tradisional.</li><li><strong>C</strong>: Salah karena meminta uang suap di tengah bencana merupakan tindak pidana korupsi pemerasan keji yang mencederai martabat kementerian.</li><li><strong>D</strong>: Salah karena membiarkan komoditas pangan membusuk mencerminkan kebejatan moral yang merugikan perekonomian rakyat kecil.</li><li><strong>E</strong>: Salah karena menjarah kontainer ekspor untuk kepentingan pribadi aparatur merupakan tindak pidana perampasan aset dan pencurian.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Kreasi", "question": "Berdasarkan definisi Profesionalisme (bekerja tuntas dan akurat atas dasar kompetensi terbaik dengan penuh tanggung jawab dan komitmen tinggi), sebuah kementerian fiskal berniat menyusun arsitektur 'Manajemen Talenta Berkelanjutan'. Desain sistem pembinaan yang paling komprehensif untuk memastikan terwujudnya profesionalisme paripurna aparatur adalah...", "options": ["Menetapkan promosi jabatan berdasarkan kedekatan personal keluarga pimpinan dan melarang seluruh staf mengikuti uji kompetensi keahlian.", "Mewajibkan pegawai menyetor uang kas pelicin promosi jabatan kepada kepala biro kepegawaian sekretariat jenderal kementerian.", "Meniadakan seluruh indikator kinerja individu dan menyerahkan penilaian kelulusan aparatur kepada undian roda keberuntungan kantor.", "Mengintegrasikan pemetaan kompetensi terstandar, jalur karier meritokratis terbuka, pelatihan keahlian berkala, dan penegakan etika tuntas.", "Menghapuskan fungsi jabatan fungsional ahli dan mewajibkan seluruh staf bekerja sebagai tenaga pesuruh kantor tanpa keahlian khusus."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Manajemen talenta berbasis Profesionalisme mengintegrasikan **empat pilar utama**: **pemetaan kompetensi objektif** (**competency mapping**), **sistem karier meritokrasi transparan** (*merit system*), **pengembangan keahlian berkelanjutan** (*continuous learning*), serta **penegakan akuntabilitas tanggung jawab kerja tuntas**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi D menyajikan sintesis kebijakan manajemen talenta yang paling utuh, modern, dan berstandar internasional. Secara teori manajemen sumber daya manusia aparatur sipil negara (meritokrasi), profesionalisme sejati hanya dapat tumbuh subur apabila institusi menyediakan kepastian jalur karier yang didasarkan pada kompetensi riil dan rekam jejak prestasi tuntas (merit system), didukung oleh pelatihan pembaruan keahlian berkelanjutan, serta diikat oleh standar akuntabilitas penegakan etika yang adil tanpa nepotisme. Pengakuan KASN terhadap sistem merit Kementerian Keuangan membuktikan bahwa arsitektur talenta ini berhasil mencetak aparatur pengelola fiskal yang profesional dan berwibawa di tingkat global. Oleh karenanya, formulasi opsi D merupakan sintesis manajemen talenta terbaik.</p><p>Jawaban yang sesuai adalah <strong>D. Mengintegrasikan pemetaan kompetensi terstandar, jalur karier meritokratis terbuka, pelatihan keahlian berkala, dan penegakan etika tuntas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena promosi berbasis nepotisme keluarga menghancurkan profesionalisme dan melanggar undang-undang aparatur sipil negara.</li><li><strong>B</strong>: Salah karena memungut uang pelicin promosi jabatan merupakan tindak pidana korupsi jual beli jabatan yang sangat memalukan.</li><li><strong>C</strong>: Salah karena mengundi promosi lewat roda keberuntungan merupakan kebodohan birokrasi yang mematikan motivasi berprestasi aparatur.</li><li><strong>E</strong>: Salah karena meniadakan jabatan fungsional ahli melumpuhkan keahlian analitis perbendaharaan dan memundurkan peradaban tata kelola.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Analitis", "question": "Konsep 'bekerja dengan hati' dalam perilaku utama Profesionalisme menuntut dedikasi penuh dan ketulusan nurani. Di antara pernyataan-pernyataan berikut, manakah simpulan yang KELIRU mengenai hakikat bekerja dengan hati bagi aparatur kementerian keuangan?", "options": ["Bekerja dengan hati berarti aparatur boleh melanggar regulasi perbendaharaan demi menuruti perasaan kasihan pribadi kepada rekanan dinas.", "Bekerja dengan hati menghadirkan empati dalam melayani keluhan publik sehingga interaksi birokrasi terasa humanis dan bermartabat.", "Bekerja dengan hati menuntut keikhlasan mengabdi demi kemaslahatan masyarakat dan keselamatan kedaulatan penerimaan keuangan negara.", "Bekerja dengan hati membangkitkan rasa memiliki pada institusi sehingga aparatur bekerja secara tuntas melampaui batas kewajiban formal.", "Bekerja dengan hati mencegah aparatur dari perilaku sinis dan arogan saat menghadapi masyarakat pemohon layanan di loket kantor."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Bekerja dengan hati **bukan berarti membenarkan kompromi perasaan yang melanggar hukum** (**emotional compromise**). Menabrak aturan perbendaharaan demi kasihan kepada rekanan bukan profesionalisme, melainkan **tindakan maladministrasi dan tindak pidana korupsi**.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C merupakan simpulan yang salah, menyesatkan, dan merusak kepatuhan hukum tata kelola keuangan negara. Secara etika administrasi publik, konsep bekerja dengan hati menuntut ketulusan moral dan empati pelayanan yang tetap teguh berpijak pada koridor peraturan perundang-undangan (rule of law), sehingga perasaan belas kasihan pribadi tidak boleh dijadikan pembenar untuk mencairkan anggaran yang cacat dokumen atau meloloskan tagihan proyek yang belum selesai secara hukum. Fakta persidangan tipikor membuktikan bahwa dalih kasihan kepada kontraktor tidak dapat menghapuskan unsur perbuatan melawan hukum yang merugikan keuangan negara. Oleh karena itu, membenarkan pelanggaran aturan demi kasihan pribadi adalah kekeliruan konsep yang fatal.</p><p>Jawaban yang sesuai adalah <strong>A. Bekerja dengan hati berarti aparatur boleh melanggar regulasi perbendaharaan demi menuruti perasaan kasihan pribadi kepada rekanan dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Merupakan pernyataan yang benar karena empati kemanusiaan memang menjadi pembeda kualitatif yang memanusiakan birokrasi publik.</li><li><strong>C</strong>: Merupakan pernyataan yang benar karena keikhlasan mengabdi demi kemaslahatan bangsa merupakan esensi spiritualitas bekerja dengan hati.</li><li><strong>D</strong>: Merupakan pernyataan yang benar karena rasa memiliki (sense of ownership) intrinsik mendorong dedikasi tuntas melampaui formalitas.</li><li><strong>E</strong>: Merupakan pernyataan yang benar karena kehangatan hati terbukti efektif membasmi arogansi feodal aparatur saat melayani di loket.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Evaluatif", "question": "Sebuah tim penilai kekayaan negara sedang menaksir nilai wajar aset tanah sitaan kasus korupsi yang akan dilelang untuk pemulihan kerugian kas negara. Pimpinan tim menolak tawaran angka taksiran instan dari makelar tanah swasta dan memilih melakukan survei pembanding harga pasar secara mandiri, cermat, dan menggunakan rumus penilaian ilmiah. Evaluasi yang paling tepat terhadap langkah pimpinan tim tersebut adalah...", "options": ["Tindakan yang membuang waktu dinas karena taksiran angka makelar tanah swasta selalu seratus persen benar dan menguntungkan negara.", "Keputusan yang keliru karena seorang penilai pemerintah seharusnya hanya duduk di kantor menerima laporan harga tanah via telepon seluler.", "Keputusan yang sangat tepat dan profesional karena menjamin akurasi nilai aset negara berbasis kompetensi penilaian ilmiah yang sah.", "Langkah yang merugikan kas negara karena survei mandiri mengharuskan kementerian menjual seluruh gedung kantor pelayanan lelang dinas.", "Kebijakan yang tidak bijaksana karena makelar tanah swasta memiliki wewenang hukum yang lebih tinggi dibanding pejabat penilai negara."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Prinsip **akurat atas dasar kompetensi terbaik** mewajibkan penilai pemerintah untuk **melakukan penilaian berbasis metode ilmiah dan survei pasar objektif** (**scientific asset valuation**), menolak angka spekulatif makelar demi mengamankan pemulihan kerugian keuangan negara secara maksimal.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi C memberikan penilaian evaluatif yang paling tepat, profesional, dan memenuhi standar penilaian kekayaan negara yang akuntabel. Secara hukum perbendaharaan dan regulasi penilaian aset negara, penetapan nilai wajar barang sitaan tindak pidana korupsi merupakan proses teknokratis yang wajib didasarkan pada metode penilaian ilmiah yang dapat diuji kebenarannya di hadapan hukum dan auditor BPK, sehingga menolak angka makelar liar dan melakukan survei mandiri menjamin bahwa hasil lelang aset memulihkan kerugian kas negara secara optimal tanpa risiko digugat oleh pihak mana pun. Fakta lelang aset korupsi membuktikan bahwa ketelitian penilai pemerintah sukses menyumbangkan triliunan rupiah penerimaan negara bukan pajak secara sah. Oleh karena itu, langkah pimpinan tim mencerminkan profesionalisme sejati.</p><p>Jawaban yang sesuai adalah <strong>C. Keputusan yang sangat tepat dan profesional karena menjamin akurasi nilai aset negara berbasis kompetensi penilaian ilmiah yang sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena angka makelar tanah swasta sarat spekulasi konflik kepentingan pribadi yang kerap merugikan penerimaan kas negara.</li><li><strong>B</strong>: Salah karena penilaian aset fisik wajib didukung pemeriksaan lapangan faktual dan tidak boleh hanya mengandalkan kabar telepon seluler.</li><li><strong>D</strong>: Salah karena biaya survei mandiri telah dibiayai DIPA resmi dan tidak ada hubungannya dengan penjualan gedung kantor dinas.</li><li><strong>E</strong>: Salah karena pejabat fungsional penilai pemerintah memegang mandat hukum berdaulat yang jauh melampaui perantara makelar swasta.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 24", "difficulty": "HOTS • Aplikasi", "question": "Seorang petugas pos patroli perbatasan laut kepabeanan berhasil menggagalkan penyelundupan kapal pengangkut narkotika bernilai ratusan miliar rupiah di tengah badai ombak besar samudera. Pihak penyelundup sempat menawarkan sekoper uang dolar senilai puluhan miliar rupiah agar kapal dilepaskan. Sikap yang paling mencerminkan rasa bangga akan profesi dan komitmen profesionalisme tinggi dari petugas tersebut adalah...", "options": ["Menerima sekoper uang dolar tersebut dan mengawal kapal penyelundup narkotika hingga bersandar dengan selamat di pelabuhan tujuan.", "Menolak uang suap tersebut tetapi mengambil sebagian narkotika untuk dijual kembali kepada sindikat pengedar narkoba di ibu kota negara.", "Meminta uang suap dinaikkan menjadi dua koper dolar sebagai syarat kesediaan aparat pos patroli menutup mata atas penyelundupan.", "Menenggelamkan kapal penyelundup bersama seluruh awak kapalnya ke dasar laut tanpa membuat berita acara penindakan hukum resmi dinas.", "Menolak secara mutlak suap tersebut, menangkap kapal dan pelaku, mengamankan barang bukti, dan bangga telah menyelamatkan bangsa."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 24", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 24</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Puncak dari **rasa bangga akan profesi** (**highest professional pride**) dan komitmen Profesionalisme adalah **keberanian menolak suap miliaran rupiah demi menyelamatkan jutaan nyawa anak bangsa** dari bahaya narkotika, mengawal kedaulatan hukum negara dengan gagah berani di tengah bahaya maut.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Opsi E adalah tindakan patriotik yang paling mulia, heroik, dan mencerminkan puncak kehormatan nilai Profesionalisme aparatur kementerian keuangan. Secara sumpah jabatan dan mandat undang-undang kepabeanan, petugas patroli laut bertindak sebagai perisai kedaulatan bangsa (customs border guard) yang mempertaruhkan nyawa di tengah badai laut ganas demi menjaga generasi penerus tanah air dari kehancuran narkotika, di mana sekoper uang suap puluhan miliar rupiah tidak ada artinya dibanding rasa bangga dan kehormatan suci menyelamatkan masa depan bangsa Indonesia. Rekam jejak keberanian aparat patroli laut bea cukai yang menolak suap bandar internasional tercatat dengan tinta emas dalam sejarah bangsa dan menuai penghargaan tertinggi dari presiden republik indonesia. Maka dari itu, menolak mutlak suap dan mengamankan barang bukti merupakan penutup paripurna yang sangat membanggakan bagi paket soal ini.</p><p>Jawaban yang sesuai adalah <strong>E. Menolak secara mutlak suap tersebut, menangkap kapal dan pelaku, mengamankan barang bukti, dan bangga telah menyelamatkan bangsa.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Salah karena menerima suap dan mengawal kapal narkoba merupakan tindak pidana korupsi penyuapan dan pengkhianatan kedaulatan negara.</li><li><strong>B</strong>: Salah karena mengambil dan menjual kembali narkotika sitaan merupakan tindak pidana peredaran gelap narkotika yang diancam hukuman mati.</li><li><strong>C</strong>: Salah karena meminta kenaikan uang suap merupakan pemerasan kriminal yang sangat bejat dan menghancurkan martabat korps kepabeanan.</li><li><strong>D</strong>: Salah karena menenggelamkan tanpa prosedur hukum merupakan tindakan pembunuhan di luar peradilan (extrajudicial) yang melanggar hukum.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 24.</div></div>"}];
let current=0;const answers=new Array(questions.length).fill(null);const letters=["A","B","C","D","E"];let seconds=65*60;let submitted=false;


// Anotasi hanya dalam pembahasan. Satu set coretan untuk setiap nomor soal.
const ANNO_KEY='stangolden_kemenkeu_p02_review_annot_v1_user_<?= (int)$USER->id ?>';
let reviewAnnoStore={};
// Data anotasi dimuat dari Moodle agar bisa dibuka dari perangkat berbeda.
let reviewAnnoActive=null,reviewAnnoTool='pen',reviewAnnoDrawing=false,reviewAnnoStroke=null;
const raSaveTimers={};
const raSavePending={};
let raServerReady=false;
async function raLoadServer(){
 try {
   const r=await fetch(`${LEADERBOARD_ENDPOINT}?action=anno_load`,{credentials:'same-origin',cache:'no-store'});
   const data=await r.json();
   if(!r.ok||!data.success)throw new Error(data.message||'Gagal memuat anotasi');
   reviewAnnoStore=data.annotations||{};
   raServerReady=true;
   // Gambar coretan yang sudah tersimpan SECARA OTOMATIS, tanpa menekan
   // tombol Coret/Anotasi. Canvas tetap pasif agar halaman mudah discroll.
   raRestoreAnnotations();
 }catch(e){console.error('Anotasi server:',e);alert('Anotasi belum dapat dimuat dari server. Coba buka ulang pembahasan.');}
}
async function raSendSave(i){
 if(!raServerReady)return;
 const b=new URLSearchParams();b.set('action','anno_save');b.set('sesskey',MOODLE_SESSKEY);
 b.set('question',String(i));b.set('strokesjson',JSON.stringify(raStrokes(i)));
 try {const r=await fetch(LEADERBOARD_ENDPOINT,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:b.toString()});
 const d=await r.json();if(!r.ok||!d.success)throw new Error(d.message||'Gagal menyimpan');}
 catch(e){console.error('Gagal menyimpan anotasi nomor',i+1,e);alert('Coretan nomor '+(i+1)+' belum tersimpan. Periksa koneksi dan coba coret lagi.');}
}
function raSave(i){clearTimeout(raSaveTimers[i]);raSaveTimers[i]=setTimeout(()=>{delete raSaveTimers[i];raSavePending[i]=raSendSave(i).finally(()=>{delete raSavePending[i];});},350);}

// Coretan dibuka otomatis saat review ditampilkan. Canvas yang belum
// terlihat baru diinisialisasi saat masuk viewport (hemat memori untuk 100 soal).
let raReviewObserver=null;
function raRestoreAnnotations(){
 if(raReviewObserver){raReviewObserver.disconnect();raReviewObserver=null;}
 const saved=Object.keys(reviewAnnoStore).filter(k=>Array.isArray(reviewAnnoStore[k]) && reviewAnnoStore[k].length>0);
 const makeVisible=(i)=>{
   const c=raCanvas(i);
   if(!c)return;
   if(!c.dataset.initialized)raInit(i);
   else raResize(i);
 };
 if(typeof IntersectionObserver==='undefined'){
   saved.forEach(k=>makeVisible(Number(k)));
 }else{
   raReviewObserver=new IntersectionObserver(entries=>{
     entries.forEach(entry=>{
       if(!entry.isIntersecting)return;
       const i=Number(entry.target.dataset.question);
       makeVisible(i);
       raReviewObserver.unobserve(entry.target);
     });
   },{rootMargin:'280px 0px'});
   saved.forEach(k=>{
     const c=raCanvas(Number(k));
     if(c)raReviewObserver.observe(c);
   });
 }
 document.querySelectorAll('.review-annotation-canvas[data-initialized]').forEach(c=>raResize(Number(c.dataset.question)));
}
function raStrokes(i){return reviewAnnoStore[String(i)]||(reviewAnnoStore[String(i)]=[]);}
function raCard(i){return document.getElementById('reviewQuestion-'+i);}
function raCanvas(i){return document.getElementById('reviewAnnotationCanvas-'+i);}
function raResize(i){
 const canvas=raCanvas(i),card=raCard(i);if(!canvas||!card||!canvas.dataset.initialized)return;
 const rect=card.getBoundingClientRect(),scale=Math.min(devicePixelRatio||1,2);
 if(!rect.width||!rect.height)return;
 const w=Math.round(rect.width*scale),h=Math.round(rect.height*scale);
 if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
 raRedraw(i);
}
function raRedraw(i){
 const canvas=raCanvas(i);if(!canvas||!canvas.width)return;
 const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;
 ctx.clearRect(0,0,w,h);
 for(const stroke of raStrokes(i)){
  const pts=stroke.points||[];if(!pts.length)continue;
  ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
  ctx.globalCompositeOperation=stroke.tool==='eraser'?'destination-out':'source-over';
  ctx.globalAlpha=stroke.tool==='marker'?.38:1;
  ctx.strokeStyle=stroke.tool==='marker'?'#ffcd22':'#e43d65';
  ctx.lineWidth=(stroke.tool==='eraser'?26:stroke.tool==='marker'?18:3.5)*(w/Math.max(canvas.getBoundingClientRect().width,1));
  ctx.beginPath();ctx.moveTo(pts[0][0]*w,pts[0][1]*h);
  if(pts.length===1)ctx.lineTo(pts[0][0]*w+.2,pts[0][1]*h+.2);
  for(let j=1;j<pts.length;j++)ctx.lineTo(pts[j][0]*w,pts[j][1]*h);
  ctx.stroke();ctx.restore();
 }
}
function raInit(i){
 const canvas=raCanvas(i);if(!canvas||canvas.dataset.initialized)return;
 canvas.dataset.initialized='1';
 canvas.addEventListener('pointerdown',e=>{
  if(reviewAnnoActive!==i||!raServerReady)return;
  e.preventDefault();reviewAnnoDrawing=true;
  const r=canvas.getBoundingClientRect();
  reviewAnnoStroke={tool:reviewAnnoTool,points:[[Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]]};
  raStrokes(i).push(reviewAnnoStroke);
  try{canvas.setPointerCapture(e.pointerId);}catch(_){}raRedraw(i);
 });
 canvas.addEventListener('pointermove',e=>{
  if(!reviewAnnoDrawing||reviewAnnoActive!==i||!reviewAnnoStroke)return;
  e.preventDefault();const r=canvas.getBoundingClientRect();
  reviewAnnoStroke.points.push([Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]);
  raRedraw(i);
 });
 const finish=()=>{if(reviewAnnoDrawing){reviewAnnoDrawing=false;reviewAnnoStroke=null;raSave(i);raToolbar(i);}};
 canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);canvas.addEventListener('lostpointercapture',finish);
 raResize(i);
}
function raToolbar(i){
 const card=raCard(i);if(!card)return;
 const on=reviewAnnoActive===i;card.classList.toggle('annotating',on);
 const toolbar=card.querySelector('.review-annotation-toolbar');
 const buttons=toolbar.querySelectorAll('button');
 buttons[0].textContent=on?'✅ Selesai mencoret':'✏️ Coret / Anotasi';buttons[0].classList.toggle('active',on);
 for(let j=1;j<=3;j++){buttons[j].disabled=!on;buttons[j].classList.toggle('active',on&&reviewAnnoTool===['pen','marker','eraser'][j-1]);}
 buttons[4].disabled=!on||!raStrokes(i).length;
 buttons[5].disabled=!on||!raStrokes(i).length;
 toolbar.querySelector('small').textContent=on?'Coret dengan mouse atau jari. Tekan Selesai mencoret agar halaman dapat digulir seperti biasa.':'Alat anotasi khusus pembahasan. Coretan tersimpan pada akun Stangolden dan dapat dibuka lintas perangkat.';
}
function raToggle(i){
 reviewAnnoDrawing=false;reviewAnnoStroke=null;
 const prior=reviewAnnoActive;reviewAnnoActive=prior===i?null:i;
 if(prior!==null&&prior!==i)raToolbar(prior);
 if(reviewAnnoActive===i){if(!raServerReady){alert('Menunggu data anotasi dari server. Silakan coba lagi.');reviewAnnoActive=null;}else raInit(i);}
 raToolbar(i);
}
function raTool(i,t){if(reviewAnnoActive!==i)return;reviewAnnoTool=t;raToolbar(i);}
function raUndo(i){if(reviewAnnoActive!==i)return;raStrokes(i).pop();raSave(i);raRedraw(i);raToolbar(i);}
function raClear(i){if(reviewAnnoActive!==i||!confirm('Hapus semua coretan pada pembahasan soal ini?'))return;reviewAnnoStore[String(i)]=[];raSave(i);raRedraw(i);raToolbar(i);}
function raButtons(i){return `<div class="review-annotation-toolbar">
 <button type="button" onclick="raToggle(${i})">✏️ Coret / Anotasi</button>
 <button type="button" onclick="raTool(${i},'pen')" disabled>✍️ Pena</button>
 <button type="button" onclick="raTool(${i},'marker')" disabled>🖍️ Stabilo</button>
 <button type="button" onclick="raTool(${i},'eraser')" disabled>⌫ Penghapus</button>
 <button type="button" onclick="raUndo(${i})" disabled>↶ Urungkan</button>
 <button type="button" onclick="raClear(${i})" disabled>🗑️ Hapus coretan</button>
 <small>Alat anotasi khusus pembahasan. Coretan tersimpan pada akun Stangolden dan dapat dibuka lintas perangkat.</small>
 </div>`;}
if(typeof ResizeObserver!=='undefined'){
 window.addEventListener('DOMContentLoaded',()=>{
  const target=document.getElementById('resultContent');if(!target)return;
  const observer=new ResizeObserver(()=>{if(reviewAnnoActive!==null)raResize(reviewAnnoActive);});
  observer.observe(target);
 });
}
window.addEventListener('resize',()=>{
 document.querySelectorAll('.review-annotation-canvas[data-initialized]').forEach(c=>raResize(Number(c.dataset.question)));
});

function svgBase(){return `<svg viewBox="0 0 180 140" class="fig-svg"></svg>`;}
function nsEl(tag,attrs={}){const e=document.createElementNS("http://www.w3.org/2000/svg",tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e;}
function polyPts(cx,cy,r,n,rot=-90){let p=[];for(let i=0;i<n;i++){const a=(Math.PI/180)*(rot+i*360/n);p.push(`${cx+Math.cos(a)*r},${cy+Math.sin(a)*r}`)}return p.join(" ")}
function drawFig(svg,spec){
 svg.innerHTML="";
 svg.appendChild(nsEl("rect",{x:5,y:5,width:170,height:130,rx:14,fill:"#fff",stroke:"#17131f","stroke-width":3}));
 const fill=spec.fill?"#17131f":"#fff",stroke="#17131f";
 if(spec.sides===4)svg.appendChild(nsEl("rect",{x:55,y:32,width:70,height:70,rx:6,fill,stroke,"stroke-width":spec.fill?0:4}));
 else svg.appendChild(nsEl("polygon",{points:polyPts(90,67,42,spec.sides,-90),fill,stroke,"stroke-width":spec.fill?0:4}));
 const rot={up:270,right:0,down:90,left:180}[spec.dir||"right"],g=nsEl("g",{transform:`rotate(${rot} 90 67)`});
 g.appendChild(nsEl("line",{x1:72,y1:67,x2:102,y2:67,stroke:spec.fill?"#fff":"#17131f","stroke-width":6,"stroke-linecap":"round"}));
 g.appendChild(nsEl("polygon",{points:"112,67 98,57 98,77",fill:spec.fill?"#fff":"#17131f"}));svg.appendChild(g);
 const ps={top:[[75,18],[90,18],[105,18]],bottom:[[75,118],[90,118],[105,118]],left:[[20,52],[20,67],[20,82]],right:[[160,52],[160,67],[160,82]]};
 (ps[spec.dotSide]||[]).slice(0,spec.dots).forEach(([x,y])=>svg.appendChild(nsEl("circle",{cx:x,cy:y,r:4.5,fill:"#7C3FFF"})));
}



















function sourceSvgBoxV29(svgHtml,label=""){
  const box=document.createElement("div");
  box.className="series-hots-frame";
  box.style.minWidth="0";
  box.style.position="relative";
  box.style.padding="6px";
  if(label){
    const lab=document.createElement("span");
    lab.className="seq-label";
    lab.textContent=label;
    box.appendChild(lab);
  }
  const holder=document.createElement("div");
  holder.innerHTML=svgHtml;
  const svg=holder.querySelector("svg");
  if(svg){
    svg.style.width="100%";
    svg.style.height="auto";
    svg.style.display="block";
  }
  box.appendChild(holder);
  return box;
}
function renderSourceStimV29(container,q){
  container.innerHTML="";
  const note=document.createElement("div");
  note.className="fig-note";
  if(q.figMode==="series") note.textContent="Lanjutkan gambar berikut.";
  else if(q.figMode==="odd") note.textContent="Cari gambar yang paling berbeda.";
  else note.textContent="Tentukan gambar yang tepat untuk mengisi kotak kosong.";
  container.appendChild(note);

  if(q.figMode==="series"){
    const board=document.createElement("div");
    board.className="series-hots-board";
    q.stimSvg.forEach((svg,i)=>board.appendChild(sourceSvgBoxV29(svg,String(i+1))));
    container.appendChild(board);
  }else if(q.figMode==="matrix"){
    const board=document.createElement("div");
    board.className="xor-matrix-board";
    q.stimSvg.forEach((svg,i)=>{
      if(svg===null){
        const cell=document.createElement("div");
        cell.className="xor-cell missing";
        cell.innerHTML=`<span class="cell-label">${i+1}</span>?`;
        board.appendChild(cell);
      }else{
        const cell=document.createElement("div");
        cell.className="xor-cell";
        cell.style.position="relative";
        cell.innerHTML=`<span class="cell-label">${i+1}</span><div class="srcsvg"></div>`;
        cell.querySelector(".srcsvg").innerHTML=svg;
        const s=cell.querySelector("svg");
        if(s){s.style.width="100%";s.style.height="auto";s.style.display="block";}
        board.appendChild(cell);
      }
    });
    container.appendChild(board);
  }
}
function renderSourceOptionsV29(opts,q,currentIndex,answerStore,clickable=true){
  const wrap=document.createElement("div");
  wrap.className="fig-options";
  q.optionSvg.forEach((svg,i)=>{
    const box=document.createElement("div");
    box.className="fig-option"+(answerStore===i?" selected":"");
    box.innerHTML=`<span class="flabel">${letters[i]}</span><div class="srcsvg"></div>`;
    box.querySelector(".srcsvg").innerHTML=svg;
    const s=box.querySelector("svg");
    if(s){s.style.width="100%";s.style.height="auto";s.style.display="block";}
    if(clickable) box.onclick=()=>{answers[currentIndex]=i;render();};
    wrap.appendChild(box);
  });
  return wrap;
}


